/* ESP32 的临界区需要两样东西：
   ① 一个自旋锁 —— 挡住【另一个核】
   ② 关中断     —— 挡住【同一个核上的中断】                       */

/* 必须是静态初始化的全局量，不能放栈上、不能放堆上 */
static portMUX_TYPE s_tick_mux = portMUX_INITIALIZER_UNLOCKED;

volatile int g_tick = 0;

/* 方式一：短临界区。内部做「取自旋锁 + 关中断」，退出时反向恢复 */
int tick_take_isr_safe(void)
{
    int v;
    portENTER_CRITICAL(&s_tick_mux);   /* 自旋锁 + 关中断 */
    v = g_tick;
    g_tick = v + 1;
    portEXIT_CRITICAL(&s_tick_mux);    /* 恢复中断 + 放锁 */
    return v;
}

/* 方式二：如果这段代码【只可能被 ISR 调用】，
   用 ISR 版本，它省掉了自旋锁（ISR 里不能自旋等待） */
int tick_take_from_isr(void)
{
    int v;
    portENTER_CRITICAL_ISR(&s_tick_mux);
    v = g_tick;
    g_tick = v + 1;
    portEXIT_CRITICAL_ISR(&s_tick_mux);
    return v;
}

/* 关键纪律：enter 和 exit 必须用【同一个】portMUX_TYPE，
   而且不能交叉、不能嵌套不同 mux —— 否则死锁 */

/* 声明这个中断处理函数可以在 IRAM 中运行、且 cache 关闭时也能安全执行 */
esp_err_t err = gpio_install_isr_service(ESP_INTR_FLAG_IRAM);
/* 如果 ISR 里用了 IRAM 之外的函数，ESP-IDF 会在此处或运行时给出明确报错，
   而不是让你在 Flash 操作时收到一个静默崩溃 */

#include <stdio.h>
#include <stdint.h>

struct Frame {           /* 假设 sizeof = 12（含填充） */
    uint32_t id;
    uint16_t len;
    uint8_t  type;
};                       /* 4 + 2 + 1 + 1(pad) = 8 实际是 8 */

int main(void)
{
    uint8_t  a8[8];
    uint32_t a32[8];
    struct Frame fr[4];

    printf("sizeof(struct Frame) = %zu\n\n", sizeof(struct Frame));

    /* 用 uintptr_t 打印地址，避免 %p 的不确定性 */
    printf("uint8_t*  基数=%lu  步长=%lu\n",
           (unsigned long)(uintptr_t)a8,
           (unsigned long)((uintptr_t)(a8 + 1) - (uintptr_t)a8));

    printf("uint32_t* 基数=%lu  步长=%lu\n",
           (unsigned long)(uintptr_t)a32,
           (unsigned long)((uintptr_t)(a32 + 1) - (uintptr_t)a32));

    printf("Frame*    基数=%lu  步长=%lu\n",
           (unsigned long)(uintptr_t)fr,
           (unsigned long)((uintptr_t)(fr + 1) - (uintptr_t)fr));

    /* 指针相减：得到的是"元素个数"，不是字节数 */
    uint32_t *p = &a32[3];
    uint32_t *q = &a32[7];
    printf("\nq - p = %td  (元素个数，不是字节数)\n", q - p);
    printf("字节差  = %td\n", (uint8_t *)q - (uint8_t *)p);

    /* ✕ 经典错误：指针类型不匹配导致步长错误 */
    uint32_t buf[4] = {0x11111111, 0x22222222, 0x33333333, 0x44444444};
    uint8_t *bp = (uint8_t *)buf;          /* 强转成字节指针 */
    printf("\n*(buf+1)   = 0x%08X\n", *(buf + 1));    /* ✔ 0x22222222 */
    printf("*(bp+1)    = 0x%02X        ← 只前进 1 字节\n", *(bp + 1));
    return 0;
}

