       .i2c_addr = 0x40, .timeout_ms = 100,
       .sample_rate_hz = 10, .oversampling = 4,
   };
   sensor_t *th = sensor_create(&cfg);
   if (!th) { ... }

   float t, h;
   sensor_err_t e = sensor_read(th, &t, &h);
   if (e != SENSOR_OK) {
       log_error("sensor_read: %s", sensor_err_str(e));   // ← 可读的错误信息
   }
