/* m01_clock.c — B05-M01 时钟树与启动
 * HSE 8 MHz → PLL ×9 → SYSCLK 72 MHz；SysTick 1 ms；MCO 输出验证。
 * 编译：arm-none-eabi-gcc -mcpu=cortex-m3 -mthumb -Os -ffreestanding -Wall -Wextra -c
 * 目标板频率测量需上板（示波器/频率计读 MCO），正文如实标注。 */
#include "stm32f103_regs.h"

volatile uint32_t g_systick_ms;

/* 带超时的 HSE 起振等待：晶体坏/虚焊时不能死等，否则整机卡在启动 */
static int hse_ready(void)
{
    return (RCC_CR & RCC_CR_HSERDY) != 0u;
}

uint32_t clock_init_72m(void)
{
    /* 1) 使能 HSE（8 MHz 晶振，最常见的外部时钟源） */
    RCC_CR |= RCC_CR_HSEON;
    for (uint32_t i = 0u; i < 0x20000u && !hse_ready(); ++i) {
        /* 空转等待；真实工程这里改为计数 + 失败回退 */
    }
    if (!hse_ready()) {
        return 0u; /* 起振失败：由调用者决定回退 HSI，而不是继续跑 */
    }

    /* 2) Flash 等待周期：72 MHz 需 2 个等待周期（RM0008 FLASH_ACR.LATENCY） */
    R32(FLASH_BASE + 0x00u) = (1u << 4) | (2u << 0); /* PRFTBE=1, LATENCY=2 */

    /* 3) 总线分频：HPRE=/1、PPRE1=/2（APB1 ≤ 36 MHz）、PPRE2=/1（APB2 = 72 MHz） */
    RCC_CFGR = (0u << 4) | (4u << 8) | (0u << 11);

    /* 4) PLL：HSE 不分频作输入，倍频 ×9（PLLMUL=0111） */
    RCC_CFGR = (RCC_CFGR & ~((0xFu << 18) | RCC_CFGR_PLLSRC | RCC_CFGR_PLLXTPRE))
             | RCC_CFGR_PLLSRC | (7u << 18);
    RCC_CR |= RCC_CR_PLLON;
    while ((RCC_CR & RCC_CR_PLLRDY) == 0u) {
    }

    /* 5) 切换 SYSCLK 到 PLL，并等待 SWS 确认 */
    RCC_CFGR = (RCC_CFGR & ~RCC_CFGR_SW) | 0x2u;
    while ((RCC_CFGR & RCC_CFGR_SWS) != (0x2u << 2)) {
    }
    return 72000000u;
}

void systick_init_1ms(uint32_t sysclk_hz)
{
    SYST_RVR = sysclk_hz / 1000u - 1u;
    SYST_CVR = 0u;
    SYST_CSR = SYST_CSR_CLKSOURCE | SYST_CSR_TICKINT | SYST_CSR_ENABLE;
}

void SysTick_Handler(void)
{
    g_systick_ms++;
}

/* MCO 输出：MCO 引脚受 GPIO 输出能力限制（F1 引脚最高 50 MHz），
 * 不能直接输出 72 MHz，因此选 PLL/2 = 36 MHz（MCO[2:0]=111）验证 PLL 是否锁定。 */
void mco_output_pa8(void)
{
    RCC_APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_AFIOEN;
    GPIOA->CRH = (GPIOA->CRH & ~(0xFu << 0))
               | ((uint32_t)GPIO_CNF_AF_PP << 2)
               | (uint32_t)GPIO_MODE_OUT_50M;                 /* PA8 复用推挽 */
    RCC_CFGR = (RCC_CFGR & ~(0x7u << 24)) | (0x7u << 24);    /* MCO = PLL/2 */
}

uint32_t clock_now_mhz(void)
{
    switch (RCC_CFGR & RCC_CFGR_SWS) {
    case (0x0u << 2): return 8u;   /* HSI */
    case (0x1u << 2): return 8u;   /* HSE 直连 */
    case (0x2u << 2): return 72u;  /* PLL */
    default:          return 0u;
    }
}

/* esp_m01_clock.c — ESP32 时钟：XTAL 40MHz → PLL → CPU 240MHz，APB 80MHz
 * 与 STM32 不同：ESP32 的外设时钟大多“复位默认已开”，只有部分需 DPORT 级门控。 */
#include "esp32_regs.h"

extern uint32_t esp_clk_cpu_freq(void);   /* ESP-IDF 提供 */
extern uint32_t esp_clk_apb_freq(void);

uint32_t esp_cpu_mhz(void) { return esp_clk_cpu_freq() / 1000000u; }
uint32_t esp_apb_mhz(void) { return esp_clk_apb_freq() / 1000000u; }

/* 按位使能外设时钟（DPORT），并用 memw 保证顺序——这是 Xtensa 的屏障 */
void esp_periph_enable_bit(uint32_t bit)
{
    DPORT_PERIP_CLK_EN_REG |= (1u << bit);
    esp_memw();
}

/* CPU 频率可在 80/160/240MHz 间切换，并影响功耗与实时性（对比 STM32 的固定 PLL 档） */
extern int esp_pm_configure(const void *cfg);
int esp_power_set(void) { return esp_pm_configure((const void *)0); }

/* h7_m01_clock.c — STM32H7 时钟：HSE→PLL1→SYSCLK，D1/D2/D3 三域分频
 * H7 的 PLL 有 DIVM/DIVN/DIVP，时钟按 D1/D2/D3 域分配，与 F1 的单 PLL 完全不同。
 * 目标 480 MHz（HSE=25MHz：DIVM1=5、DIVN1=192、DIVP1=2 → 5×192/2=480）。 */
#include "stm32h7_regs.h"

uint32_t h7_clock_480m(void)
{
    /* 1) 使能 HSE（HSEON=bit16，HSERDY=bit17，与 F1 相同） */
    H7_RCC_CR |= (1u << 16);
    for (uint32_t i = 0u; i < 0x20000u; ++i) {
        if (H7_RCC_CR & (1u << 17)) { break; }
    }
    if ((H7_RCC_CR & (1u << 17)) == 0u) { return 0u; }   /* 起振失败 */

    /* 2) 关键前置（顺序不能颠倒）：先升压到 VOS0 并设置 Flash 等待周期，
     *    再把任何分频器/开关动到高频，否则切到 480MHz 时取指会出错。
     *    下面两条为示意（真实值按 RM0433 的电压-频率表取）。 */
    R32(0x58024818u) = (3u << 14);   /* PWR_D3CR.VOS = VOS0（示意） */
    R32(0x52002000u) = (2u << 0);    /* FLASH_ACR.LATENCY = 2（示意） */

    /* 3) 总线分频：D1CPRE=/1、HPRE=/1；D2PPRE1=/2（APB1 上限低于 SYSCLK） */
    H7_RCC_D1CFGR = (0u << 0) | (0u << 4);
    H7_RCC_D2CFGR = (4u << 4);

    /* 4) PLL 输入=HSE，DIVM1=5（PLLSRC=10 在 bit[1:0]，DIVM1 在 bit[9:4]） */
    H7_RCC_PLLCKSELR = (2u << 0) | (5u << 4);

    /* 5) DIVN1=192（bit[8:0]）、DIVP1=2（bit[15:9]）；VCO=5×192=960MHz，输出 480MHz */
    H7_RCC_PLL1DIVR = (192u << 0) | (2u << 9);
    H7_RCC_CR |= H7_RCC_CR_PLL1ON;
    while ((H7_RCC_CR & H7_RCC_CR_PLL1RDY) == 0u) {
    }

    /* 6) SYSCLK=PLL1（RCC_CFGR.SW=3），并等 SWS 确认 */
    H7_RCC_CFGR = (H7_RCC_CFGR & ~0x7u) | 3u;
    while (((H7_RCC_CFGR >> 3) & 0x7u) != 3u) {
    }
    return 480000000u;
}

/* H7 的 CPU 有 16KB I-cache / D-cache，默认未开；开启后需注意 DMA 一致性 */
void h7_enable_caches(void)
{
    H7_SCB_CCR |= H7_SCB_CCR_ICACHE | H7_SCB_CCR_DCACHE;
    h7_dsb();
    h7_isb();
}

/* m02_gpio.c — B05-M02 GPIO 深入
 * LED(PC13) + 按键(PA0 上拉) 的寄存器写法；BSRR 原子置位/清除。
 * F1 每引脚 4 位：bit[1:0]=MODE，bit[3:2]=CNF。PC13/14/15 上限 2 MHz、3 mA。 */
#include "stm32f103_regs.h"

#define LED_PIN   13u
#define BUTTON_PIN 0u

void gpio_demo_init(void)
{
    RCC_APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPCEN;

    /* PA0：输入上拉（CNF=10, MODE=00） */
    GPIOA->CRL = (GPIOA->CRL & ~(0xFu << (BUTTON_PIN * 4u)))
               | ((uint32_t)GPIO_CNF_IN_PU << 2)
               | (uint32_t)GPIO_MODE_INPUT;

    /* PC13：通用推挽输出，2 MHz（不能用 50 MHz——RM0008 限 PC13/14/15 为 2 MHz/3 mA） */
    GPIOC->CRH = (GPIOC->CRH & ~(0xFu << ((LED_PIN - 8u) * 4u)))
               | ((uint32_t)GPIO_CNF_OUT_PP << 2)
               | (uint32_t)GPIO_MODE_OUT_2M;
}

/* BSRR 写 1 原子生效：低位区=置位，高位区=清除；不需要读-改-写 */
void led_on(void)  { GPIOC->BSRR = (1u << LED_PIN); }
void led_off(void) { GPIOC->BSRR = (1u << (LED_PIN + 16u)); }
void led_toggle_sw(void) { static uint32_t s; s ^= 1u; if (s) led_on(); else led_off(); }

/* 上拉输入：松开为高、按下为低 */
int button_pressed(void) { return (GPIOA->IDR & (1u << BUTTON_PIN)) == 0u; }

/* 反面示例（片段，不单独编译）：开漏输出必须外接上拉，否则只能输出低电平，
 * 因为开漏结构只能“拉低”，不能“推高”；IC/总线场景常故意如此。 */

/* esp_m02_gpio.c — ESP32 GPIO：IO_MUX（电气/功能）+ GPIO Matrix（信号路由）
 * 与 STM32 的“AF 复用号”不同：外设信号要经 GPIO Matrix 交换到引脚。 */
#include "esp32_regs.h"

void esp_gpio2_out_init(void)
{
    GPIO_ENABLE_W1TS = (1u << 2);              /* 使能输出 */
    /* IO_MUX：MCU_SEL=0 选 GPIO 功能；驱动强度用 FUN_DRV（2 位） */
    IO_MUX_GPIO2_REG = (IO_MUX_GPIO2_REG & ~(0x7u << IO_MUX_MCU_SEL_SHIFT))
                     | (0u << IO_MUX_MCU_SEL_SHIFT);
}

/* 写 1 置位/清除，原子；语义与 STM32 的 BSRR 类似 */
void esp_led_on(void)  { GPIO_OUT_W1TS = (1u << 2); }
void esp_led_off(void) { GPIO_OUT_W1TC = (1u << 2); }

int esp_button_pressed(void) { return (GPIO_IN_REG & (1u << 0)) == 0u; }

/* 注意：GPIO34-39 只能输入、没有内部上下拉；GPIO16/17 在 WROVER 上被 PSRAM 占用。
 * 这些限制与 STM32 的“PC13/14/15 限 2MHz”一样，属于必须记住的引脚约束。 */

/* h7_m02_gpio.c — STM32H7 GPIO：每引脚 2 位的 MODER/OTYPER/OSPEEDR/PUPDR/AFR
 * 与 F1 的 CRL/CRH 4 位 nibble 完全不同；这是跨 F1→H7 移植时必改的一段。 */
#include "stm32h7_regs.h"

#define H7_AF_TIM2 1u   /* PA5 作为 TIM2_CH1 的复用值（AF1） */

void h7_gpio_pa5_af(void)
{
    H7_RCC_AHB4ENR |= (1u << 0);                       /* 开 GPIOA 时钟（H7 用 AHB4ENR） */
    uint32_t s = 5u * 2u;
    H7_GPIOA->MODER   = (H7_GPIOA->MODER & ~(3u << s)) | (H7_MODER_AF << s);
    H7_GPIOA->OTYPER &= ~(1u << 5);                    /* 推挽 */
    H7_GPIOA->OSPEEDR |= (3u << s);                    /* 非常快 */
    H7_GPIOA->PUPDR   &= ~(3u << s);                   /* 无上下拉 */
    H7_GPIOA->AFR[0] = (H7_GPIOA->AFR[0] & ~(0xFu << (5u * 4u)))
                     | (H7_AF_TIM2 << (5u * 4u));      /* AFR[0] 管 pin0..7 */
}

/* BSRR 语义与 F1 相同：低位区置位、高位区清除，单次写原子生效 */
void h7_led_on(void)  { H7_GPIOB->BSRR = (1u << 0); }
void h7_led_off(void) { H7_GPIOB->BSRR = (1u << (0 + 16)); }

/* m03_nvic.c — B05-M03 中断与 NVIC
 * 优先级分组、EXTI 按键中断、PRIMASK/BASEPRI 临界区。
 * 关键事实：PRIMASK/BASEPRI 是内核“专用寄存器”，不是内存映射，必须用 MRS/MSR。 */
#include "stm32f103_regs.h"

#define EXTI0_IRQN 6u   /* STM32F103 的 EXTI0 中断号 */

void nvic_set_priority_grouping(uint32_t group)
{
    /* AIRCR.PRIGROUP：0=1 位抢占/7 位子优先级 … 7=7 位抢占/1 位子优先级 */
    SCB_AIRCR = AIRCR_VECTKEY | (group & 0x7u);
}

void exti0_button_init(void)
{
    RCC_APB2ENR |= RCC_APB2ENR_AFIOEN;
    AFIO_EXTICR1 = (AFIO_EXTICR1 & ~0xFu) | 0x0u; /* PA0 → EXTI0 */
    EXTI_FTSR |= (1u << 0);                        /* 下降沿触发 */
    EXTI_IMR  |= (1u << 0);                        /* 不屏蔽 */
    NVIC_IPR[EXTI0_IRQN] = (uint8_t)(0x2u << 5);   /* 优先级 2（数值越小越紧急） */
    NVIC_ISER = (1u << EXTI0_IRQN);                /* 使能 IRQ */
}

void EXTI0_IRQHandler(void)
{
    if (EXTI_PR & 1u) {
        EXTI_PR = 1u; /* 写 1 清挂起位（写 0 无效，这是最常见的“中断只进一次”原因） */
    }
}

/* 通用临界区：保存-关闭-恢复，避免嵌套时错误地打开中断 */
uint32_t critical_begin(void)
{
    uint32_t saved = b05_get_primask();
    b05_disable_irq();
    b05_dsb();
    return saved;
}

void critical_end(uint32_t saved)
{
    if (saved == 0u) {
        b05_enable_irq(); /* 只在原本开中断时才恢复 */
    }
}

/* BASEPRI：屏蔽“优先级数值 ≥ threshold”的中断，保留更高优先级（数值更小）的实时性。
 * 传 0 等于关闭屏蔽。RTOS 用它把临界区限制在 configMAX_SYSCALL_INTERRUPT_PRIORITY 之内。 */
void mask_at_or_below(uint32_t threshold)
{
    b05_set_basepri(threshold << 4); /* 优先级值需左移到 BASEPRI 的高 4 位 */
}

int in_handler_mode(void) { return b05_get_ipsr() != 0u; }

/* esp_m03_intr.c — ESP32 中断：没有 NVIC，用中断分配器把外设信号绑到某个核
 * 与 Cortex-M 的“固定向量 + 优先级分组”是两种模型。 */
#include "esp32_regs.h"

typedef void (*esp_isr_t)(void *arg);

/* ESP-IDF：esp_intr_alloc(source, flags, handler, arg, handle) */
extern int esp_intr_alloc(int source, int flags, esp_isr_t handler, void *arg, void **handle);
extern void esp_intr_free(void *handle);

int esp_bind_isr(int source, esp_isr_t handler, void *arg)
{
    return esp_intr_alloc(source, 0, handler, arg, (void **)0);
}

/* 双核：可指定 ISR 跑在 PRO_CPU(0) 或 APP_CPU(1)。
 * 跨核/与任务共享数据时，用 memw 或原子，而不是像 Cortex-M 那样只靠 PRIMASK。 */
void esp_isr_memory_barrier(void) { esp_memw(); }

/* 关中断用临界区（portENTER_CRITICAL），它不是简单的“关全局中断”语义 */
extern void esp_port_enter_critical(void);
extern void esp_port_exit_critical(void);
void esp_critical_demo(void) { esp_port_enter_critical(); esp_memw(); esp_port_exit_critical(); }

/* h7_m03_nvic.c — STM32H7 中断：NVIC 与 M3 同架构，但 IRQ 更多、且有 I/D cache
 * PRIMASK/BASEPRI 仍是内核专用寄存器（MRS/MSR），与 F1 一致。 */
#include "stm32h7_regs.h"
#include <stdint.h>

#define NVIC_ISER_H7 R32(0xE000E100u)
#define NVIC_IPR_H7  ((volatile uint8_t *)0xE000E400u)
#define SCB_AIRCR_H7 R32(0xE000ED0Cu)

void h7_set_grouping(uint32_t group)
{
    SCB_AIRCR_H7 = (0x05FAu << 16) | (group & 0x7u);
}

/* EXTI0_IRQn 在 H7 上同样是 6（Cortex-M 系列一致） */
void h7_exti0_enable(void)
{
    NVIC_IPR_H7[6] = (uint8_t)(0x2u << 5);
    NVIC_ISER_H7 = (1u << 6);
}

uint32_t h7_critical_begin(void)
{
    uint32_t saved;
    __asm volatile ("mrs %0, primask" : "=r"(saved));
    __asm volatile ("cpsid i" ::: "memory");
    return saved;
}

void h7_critical_end(uint32_t saved)
{
    if (saved == 0u) { __asm volatile ("cpsie i" ::: "memory"); }
}

void h7_mask_at_or_below(uint32_t priority)
{
    __asm volatile ("msr basepri, %0" :: "r"(priority << 4) : "memory");
}

// 1 kHz、1 µs 分辨率：先分频到 1 MHz，再 1000 个周期
TIM3->PSC = 72 - 1;    // 72MHz/(71+1) = 1MHz
TIM3->ARR = 1000 - 1;  // 1MHz / 1000 = 1kHz
TIM3->CCR1 = (uint32_t)permille * (TIM3->ARR + 1) / 1000;  // 提升 u32 防溢出
TIM3->EGR = TIM_EGR_UG;   // 产生更新事件，参数生效
TIM3->CR1 |= TIM_CR1_CEN;

/* m04_timer.c — B05-M04 定时器
 * TIM2：PWM 呼吸灯（PSC/ARR 计算）；TIM3：编码器模式读位置。
 * 关键事实：APB1 预分频≠1 时，定时器时钟 = APB1 时钟 ×2（F1 的时钟树细节）。 */
#include "stm32f103_regs.h"

/* sysclk_hz=72MHz，APB1=36MHz，故 TIM2 计数时钟 = 72MHz（×2） */
void tim2_pwm_init(uint32_t sysclk_hz, uint32_t pwm_hz)
{
    RCC_APB1ENR |= RCC_APB1ENR_TIM2EN;

    uint32_t tim_clk = sysclk_hz;             /* 已按 ×2 处理 */
    uint32_t psc = tim_clk / 1000000u - 1u;   /* 计数频率 1 MHz → 1 µs 步进 */
    uint32_t arr = 1000000u / pwm_hz - 1u;    /* PWM 周期 */

    TIM2->PSC = psc;
    TIM2->ARR = arr;
    TIM2->CCMR1 = TIM_CCMR1_OC1M_PWM1 | TIM_CCMR1_OC1PE; /* PWM 模式 1 + 预装载 */
    TIM2->CCR1 = 0u;
    TIM2->CCER = TIM_CCER_CC1E;
    TIM2->EGR = 1u;                            /* UG：立即装载 PSC/ARR */
    TIM2->CR1 = TIM_CR1_ARPE | TIM_CR1_CEN;
}

/* 占空比 0..1000（千分比），整数运算避免浮点 */
void tim2_set_duty_permille(uint16_t permille)
{
    if (permille > 1000u) {
        permille = 1000u;
    }
    TIM2->CCR1 = (uint32_t)permille * (TIM2->ARR + 1u) / 1000u;
}

void tim3_encoder_init(void)
{
    RCC_APB1ENR |= (1u << 1);      /* TIM3EN */
    TIM3->CCMR1 = (1u << 0) | (1u << 8); /* CC1S=01(TI1)、CC2S=01(TI2) */
    TIM3->SMCR = TIM_SMCR_SMS_ENCODER;   /* 编码器模式 3：两相双边沿计数 ×4 */
    TIM3->ARR = 0xFFFFu;
    TIM3->CNT = 0u;
    TIM3->CR1 = TIM_CR1_CEN;
}

/* 读增量：用有符号转换处理回绕 */
int16_t tim3_encoder_read(void)
{
    return (int16_t)TIM3->CNT;
}

/* 输入捕获测频（示意公式）：频率 = 计数时钟 / 两次捕获差值 */
uint32_t ic_freq_hz(uint32_t timer_clk, uint16_t captured_delta)
{
    if (captured_delta == 0u) {
        return 0u; /* 防止除零；超高频/无信号时会走到这里 */
    }
    return timer_clk / captured_delta;
}

/* esp_m04_timer.c — ESP32 PWM：常用 LEDC 硬件 PWM，而非通用定时器比较输出
 * 与 STM32 的“TIMx + CCR 比较”不同，LEDC 有独立的分频与占空比寄存器。 */
#include "esp32_regs.h"

/* ESP-IDF：ledc_setup(channel, freq_hz, resolution_bits) 返回实际频率 */
extern int ledc_setup(int channel, uint32_t freq_hz, int resolution_bits);
extern int ledcAttachPin(int pin, int channel);
extern int ledcWrite(int channel, uint32_t duty);

uint32_t esp_ledc_init(int channel, int pin, uint32_t freq_hz, int bits)
{
    uint32_t real_freq = (uint32_t)ledc_setup(channel, freq_hz, bits);
    (void)ledcAttachPin(pin, channel);
    return real_freq;   /* 注意：实际频率可能与请求值不同，必须回读 */
}

void esp_ledc_duty(int channel, uint32_t duty) { (void)ledcWrite(channel, duty); }

/* 若需精确计时的通用定时器，用 GPTimer（gptimer_new_timer/gptimer_set_alarm_action），
 * 那是另一套 API；LEDC 只负责 PWM。 */

/* h7_m04_timer.c — STM32H7 定时器：通用定时器寄存器布局与 F1 相同，但时钟更高
 * H7 的 TIM2/3/4 是 32 位计数器；时钟来自 APB1 且同样受“预分频≠1 则 ×2”规则影响。 */
#include "stm32h7_regs.h"

#define H7_TIM2_CR1   R32(0x40000000u)
#define H7_TIM2_EGR   R32(0x40000014u)
#define H7_TIM2_CCMR1 R32(0x40000018u)
#define H7_TIM2_CCER  R32(0x40000020u)
#define H7_TIM2_CNT   R32(0x40000024u)
#define H7_TIM2_PSC   R32(0x40000028u)
#define H7_TIM2_ARR   R32(0x4000002Cu)
#define H7_TIM2_CCR1  R32(0x40000034u)
#define H7_TIM2EN     (1u << 0)

void h7_tim2_pwm_init(uint32_t tim_clk, uint32_t pwm_hz)
{
    H7_RCC_APB1LENR |= H7_TIM2EN;
    H7_TIM2_PSC = tim_clk / 1000000u - 1u;      /* 1 MHz 计数 */
    H7_TIM2_ARR = 1000000u / pwm_hz - 1u;
    H7_TIM2_CCMR1 = (0x6u << 4) | (1u << 3);    /* PWM1 + 预装载 */
    H7_TIM2_CCR1 = 0u;
    H7_TIM2_CCER = 1u;
    H7_TIM2_EGR = 1u;                            /* UG：装载 PSC/ARR */
    H7_TIM2_CR1 = (1u << 7) | (1u << 0);        /* ARPE | CEN */
}

void h7_tim2_duty(uint16_t permille)
{
    if (permille > 1000u) { permille = 1000u; }
    H7_TIM2_CCR1 = (uint32_t)permille * (H7_TIM2_ARR + 1u) / 1000u;
}

/* 32 位计数是 H7 相对 F1（16 位）的实在优势：低频测速不必频繁处理溢出 */
uint32_t h7_tim2_count32(void) { return H7_TIM2_CNT; }

// 错误：先除后乘，整数除法把精度丢光
// mv = raw / 4095 * vref;
// 正确：乘法在前、除法在后，用 u32
static uint32_t adc_to_mv(uint16_t raw, uint32_t vref_mv) {
    return (uint32_t)raw * vref_mv / 4095u;   // 2048,3300 -> 1650
}

/* m05_adc.c — B05-M05 ADC 采样与标定
 * 校准 → 单次转换 → 过采样平均 → 换算毫伏。采样时间需按源阻抗选取。 */
#include "stm32f103_regs.h"

void adc1_init(void)
{
    RCC_APB2ENR |= RCC_APB2ENR_ADC1EN;
    ADC1->CR2 |= ADC_CR2_ADON;            /* 第一次写 ADON：上电 */

    /* 校准序列：RSTCAL 自清 → CAL 自清 */
    ADC1->CR2 |= ADC_CR2_RSTCAL;
    while (ADC1->CR2 & ADC_CR2_RSTCAL) {
    }
    ADC1->CR2 |= ADC_CR2_CAL;
    while (ADC1->CR2 & ADC_CR2_CAL) {
    }

    /* 通道 0 采样时间 = 55.5 周期（SMPR2 bit[2:0]=101），适配较高源阻抗 */
    ADC1->SMPR2 = (ADC1->SMPR2 & ~(0x7u << 0)) | (0x5u << 0);
    ADC1->SQR3 = 0u;                      /* 规则序列第 1 个转换 = 通道 0，长度 1 */
}

uint16_t adc1_read_once(void)
{
    ADC1->CR2 |= ADC_CR2_ADON;            /* 第二次写 ADON：启动转换（F1 特性） */
    while ((ADC1->SR & ADC_SR_EOC) == 0u) {
    }
    return (uint16_t)ADC1->DR;            /* 读 DR 清 EOC */
}

/* 过采样：N 次平均，牺牲时间换信噪比；注意 sum 用 32 位防溢出 */
uint16_t adc1_read_avg(uint16_t n)
{
    if (n == 0u) {
        return 0u;
    }
    uint32_t sum = 0u;
    for (uint16_t i = 0u; i < n; ++i) {
        sum += adc1_read_once();
    }
    return (uint16_t)(sum / n);
}

/* 原始码 → 毫伏（12 位、VREF 通常 3300 mV） */
uint32_t adc_to_mv(uint16_t raw, uint32_t vref_mv)
{
    return (uint32_t)raw * vref_mv / 4095u;
}

/* esp_m05_adc.c — ESP32 ADC：SAR ADC 由 RTC 控制器管理，需先设衰减获得合适量程
 * 与 STM32 固定 VREF 不同，ESP32 用“衰减档”把量程拉到约 0..3.3V（不同芯片为 ~2.5V）。 */
#include "esp32_regs.h"

typedef enum { ESP_ADC_ATTEN_0DB = 0, ESP_ADC_ATTEN_11DB = 3 } esp_adc_atten_t;

extern int  adc1_config_width(int width_bits);
extern int  adc1_config_channel_atten(int channel, esp_adc_atten_t atten);
extern int  adc1_get_raw(int channel);
extern int  esp_adc_cal_raw_to_voltage(int raw, const void *chars);

int esp_adc1_init(int width_bits)
{
    (void)adc1_config_width(width_bits);                 /* 通常 12 位 */
    return adc1_config_channel_atten(0, ESP_ADC_ATTEN_11DB); /* 通道 0，约 0..3.3V */
}

int esp_adc1_read(void) { return adc1_get_raw(0); }

/* 换算必须带校准：ESP32 的 ADC 非线性明显，IDF 提供 esp_adc_cal 按 eFuse 校准值换算 */
int esp_adc1_read_mv(const void *chars)
{
    return esp_adc_cal_raw_to_voltage(adc1_get_raw(0), chars);
}

/* h7_m05_adc.c — STM32H7 ADC（v3）：16 位、ISR/CFGR/SQR1，与 F1 的 SR/CR2 不同
 * 校准改由 ADCAL 位触发；分辨率与过采样在 CFGR2 配置；参考电压可外接 VREFBUF。 */
#include "stm32h7_regs.h"

#define H7_ADC1_ISR   R32(0x40022000u)
#define H7_ADC1_CR    R32(0x40022008u)
#define H7_ADC1_CFGR  R32(0x4002200Cu)
#define H7_ADC1_CFGR2 R32(0x40022010u)
#define H7_ADC1_SQR1  R32(0x40022030u)
#define H7_ADC1_DR    R32(0x40022040u)
#define H7_ADC_ISR_EOC    (1u << 2)
#define H7_ADC_CR_ADEN    (1u << 0)
#define H7_ADC_CR_ADSTART (1u << 2)
#define H7_ADC_CR_ADCAL   (1u << 31)

void h7_adc1_init(void)
{
    R32(0x580244F0u) |= (1u << 24);    /* APB2 上的 ADC123 时钟（示意） */
    /* H7 必做：先开 ADC 电压调节器并等待就绪，否则 ADEN/ADCAL 不生效 */
    H7_ADC1_CR |= (1u << 28);          /* ADVREGEN（示意，位号见 RM0433） */
    for (volatile uint32_t d = 0u; d < 1000u; ++d) { }   /* 稳压器建立时间 */
    H7_ADC1_CR |= H7_ADC_CR_ADCAL;     /* 触发校准 */
    while (H7_ADC1_CR & H7_ADC_CR_ADCAL) {
    }
    H7_ADC1_CR |= H7_ADC_CR_ADEN;      /* 使能 ADC */
    while ((H7_ADC1_ISR & (1u << 0)) == 0u) {  /* ADRDY */
    }
    H7_ADC1_CFGR &= ~(0x3u << 2);      /* 分辨率 16 位（RES=00） */
    H7_ADC1_SQR1 = 0u;                 /* 序列长度 1，通道 0 */
}

uint16_t h7_adc1_read(void)
{
    H7_ADC1_CR |= H7_ADC_CR_ADSTART;
    while ((H7_ADC1_ISR & H7_ADC_ISR_EOC) == 0u) {
    }
    return (uint16_t)H7_ADC1_DR;
}

/* 16 位 → 毫伏：满量程 65535（F1 是 4095，换算系数不同，移植时改这里最容易漏） */
uint32_t h7_adc_to_mv(uint16_t raw, uint32_t vref_mv)
{
    return (uint32_t)raw * vref_mv / 65535u;
}

DMA1_Channel1->CPAR = (uint32_t)&ADC1->DR;   // 外设地址
DMA1_Channel1->CMAR = (uint32_t)buf;        // 内存地址
DMA1_Channel1->CNDTR = N;
DMA1_Channel1->CCR = DMA_CCR_MINC | DMA_CCR_CIRC |   // 自增 + 循环
                     DMA_CCR_HTIE | DMA_CCR_TCIE | DMA_CCR_EN;
// 半满(HT)处理前半块、全满(TC)处理后半块 → 双缓冲

/* m06_dma.c — B05-M06 DMA
 * ADC1 → 内存 循环搬运：CPU 不参与每次转换。环回模式配合半满/全满中断做双缓冲。 */
#include "stm32f103_regs.h"

volatile uint16_t g_dma_half;
volatile uint16_t g_dma_full;

/* buf 指向长度 len 的 uint16 数组，硬件持续覆盖 */
void adc_dma_start(uint16_t *buf, uint16_t len)
{
    ADC1->CR2 |= ADC_CR2_DMA | ADC_CR2_CONT;   /* 开 DMA 请求 + 连续转换 */
    DMA1_Ch1->CPAR  = (uint32_t)(uintptr_t)&ADC1->DR;  /* 源：ADC 数据寄存器 */
    DMA1_Ch1->CMAR  = (uint32_t)(uintptr_t)buf;        /* 目的：内存缓冲 */
    DMA1_Ch1->CNDTR = len;
    DMA1_Ch1->CCR   = DMA_CCR_MINC | DMA_CCR_PSIZE_16 | DMA_CCR_MSIZE_16
                    | DMA_CCR_CIRC | DMA_CCR_TCIE | DMA_CCR_EN;
    ADC1->CR2 |= ADC_CR2_ADON | ADC_CR2_SWSTART;
}

/* 半满/全满由 DMA 通道的 HTIF/TCIF 判定。
 * DMA1_ISR 每通道占 4 位：GIFx=bit0、TCIFx=bit1、HTIFx=bit2、TEIFx=bit3。
 * 通道 1 即 GIF1/TCIF1/HTIF1/TEIF1；最容易写错的是把 bit1 当半满（其实是“传输完成”）。 */
void dma1_ch1_irq(void)
{
    if (DMA1_ISR & (1u << 2)) {        /* HTIF1：半传输（半满） */
        DMA1_IFCR = (1u << 2);
        g_dma_half++;
    }
    if (DMA1_ISR & (1u << 1)) {        /* TCIF1：传输完成（全满） */
        DMA1_IFCR = (1u << 1);
        g_dma_full++;
    }
}

void dma1_ch1_stop(void)
{
    DMA1_Ch1->CCR &= ~DMA_CCR_EN;
    while (DMA1_Ch1->CCR & DMA_CCR_EN) {
    }
}

/* 关于 cache：Cortex-M7 上 DMA 写入的内存可能留在 cache 里，
 * 需按缓冲方向 clean/invalidate；M3 无数据 cache，本示例不涉及。 */

/* esp_m06_dma.c — ESP32 的 DMA：以“描述符链表”组织（SPI 内建 DMA）
 * 与 STM32 的“通道/流 + 固定请求映射”是两种模型：这里由链表描述每段缓冲。 */
#include <stdint.h>

typedef struct esp_dma_desc {
    uint32_t size : 12, length : 12, offset : 5, sof : 1, eof : 1, owner : 1;
    void *buf;
    struct esp_dma_desc *next;
} esp_dma_desc_t;

void esp_dma_desc_init(esp_dma_desc_t *d, void *buf, uint32_t len, int eof)
{
    d->size = len;
    d->length = len;
    d->offset = 0;
    d->eof = eof ? 1u : 0u;
    d->owner = 1u;                 /* owner=1 交给硬件，完成硬件归还 DMA */
    d->buf = buf;
    d->next = (void *)0;
}

/* 缓冲对齐要求：SPI DMA 需 4 字节对齐、建议 32 字节。ESP32 无 CPU D-cache；
 * 但在 ESP32-S2/S3 上开了 cache，仍需 clean/invalidate（与 STM32H7 同类问题）。 */
extern int spi_bus_initialize(int host, const void *cfg, int dma_chan);
extern int spi_device_transmit(void *dev, void *trans);

int esp_spi_dma_tx(void *dev, void *trans) { return spi_device_transmit(dev, trans); }

/* h7_m06_dma.c — STM32H7 DMA：用“流(stream)”而非“通道”，且有 D-cache 一致性要求
 * 关键差异：F1 固定通道映射；H7 是流 + 请求复用器(DMAMUX)，同一外设可由不同流服务。 */
#include "stm32h7_regs.h"

#define H7_ADC1_DR_ADDR 0x40022040u
#define H7_SxCR_TCIE (1u << 1)
#define H7_SxCR_CIRC (1u << 8)
#define H7_SxCR_MINC (1u << 10)
#define H7_SxCR_PSIZE_16 (1u << 16)
#define H7_SxCR_MSIZE_16 (1u << 18)

void h7_adc_dma_start(uint16_t *buf, uint16_t len)
{
    H7_DMA1_Stream0->PAR  = H7_ADC1_DR_ADDR;
    H7_DMA1_Stream0->M0AR = (uint32_t)(uintptr_t)buf;
    H7_DMA1_Stream0->NDTR = len;
    H7_DMA1_Stream0->CR   = H7_DMA_SxCR_EN | H7_SxCR_TCIE | H7_SxCR_CIRC
                          | H7_SxCR_MINC | H7_SxCR_PSIZE_16 | H7_SxCR_MSIZE_16;

    /* D-cache 开启时：DMA 写入内存前，需保证该区不在 cache 里是脏数据。
     * H7 上“忘记 cache 维护”比 F1 多出的一类 bug，volatile 不能替代。 */
    h7_dcache_clean((uint32_t)(uintptr_t)buf, (uint32_t)len * 2u);
}

void h7_dma1_stream0_stop(void)
{
    H7_DMA1_Stream0->CR &= ~H7_DMA_SxCR_EN;
    while (H7_DMA1_Stream0->CR & H7_DMA_SxCR_EN) {
    }
}

/* host_ringbuf.c — 可在主机运行的环形缓冲自检（gcc，非交叉）
 * 环形缓冲是纯逻辑，最适合先在 PC 上把边界测干净，再搬到 MCU。 */
#include <stdio.h>
#include <stdint.h>

#define RB_SIZE 8u   /* 2 的幂；留一格区分满/空，可用 7 格 */
typedef struct {
    volatile uint16_t head;
    volatile uint16_t tail;
    uint8_t buf[RB_SIZE];
} rb_t;

static int rb_push(rb_t *rb, uint8_t byte)
{
    uint16_t next = (uint16_t)((rb->head + 1u) & (RB_SIZE - 1u));
    if (next == rb->tail) {
        return 0;                        /* 满 */
    }
    rb->buf[rb->head] = byte;
    rb->head = next;
    return 1;
}

static int rb_pop(rb_t *rb, uint8_t *out)
{
    if (rb->head == rb->tail) {
        return 0;                        /* 空 */
    }
    *out = rb->buf[rb->tail];
    rb->tail = (uint16_t)((rb->tail + 1u) & (RB_SIZE - 1u));
    return 1;
}

int main(void)
{
    rb_t rb = { 0u, 0u, { 0u } };
    int failures = 0;
    uint8_t v = 0u;

    /* 空缓冲 pop 必须失败 */
    if (rb_pop(&rb, &v) != 0) { printf("FAIL empty pop\n"); failures++; }

    /* 填满：8 格只能存 7 个 */
    int pushed = 0;
    for (uint8_t i = 1u; i <= 10u; ++i) {
        pushed += rb_push(&rb, (uint8_t)(i * 10u));
    }
    printf("pushed=%d (expect 7)\n", pushed);
    if (pushed != 7) { failures++; }

    /* 顺序必须 FIFO：10,20,...,70 */
    int order_ok = 1;
    for (uint8_t expect = 10u; expect <= 70u; expect += 10u) {
        if (rb_pop(&rb, &v) != 1 || v != expect) { order_ok = 0; }
    }
    printf("fifo_order=%s\n", order_ok ? "ok" : "BAD");
    if (!order_ok) { failures++; }

    /* 反复回绕 100 次 */
    for (int i = 0; i < 100; ++i) {
        rb_push(&rb, (uint8_t)i);
        rb_pop(&rb, &v);
    }
    printf("wrap_cycles=100 ok\n");

    printf(failures ? "RESULT: FAIL (%d)\n" : "RESULT: PASS\n", failures);
    return failures ? 1 : 0;
}

/* m07_uart.c — B05-M07 UART
 * 波特率 BRR 计算 + 溢出错误处理 + ISR 环形接收。DMA + IDLE 收不定长帧见正文。 */
#include "stm32f103_regs.h"

/* 复用阶段①的环形缓冲：容量取 2 的幂，用掩码回绕 */
#define UART_RB_SIZE 256u
typedef struct {
    volatile uint16_t head;
    volatile uint16_t tail;
    uint8_t buf[UART_RB_SIZE];
} uart_rb_t;

static uart_rb_t g_rx;
volatile uint32_t g_rx_overrun;

int uart_rb_push(uart_rb_t *rb, uint8_t byte)
{
    uint16_t next = (uint16_t)((rb->head + 1u) & (UART_RB_SIZE - 1u));
    if (next == rb->tail) {
        return 0;                 /* 满：丢弃新数据并计数 */
    }
    rb->buf[rb->head] = byte;
    rb->head = next;              /* 先写数据，后发布索引 */
    return 1;
}

int uart_rb_pop(uart_rb_t *rb, uint8_t *out)
{
    if (rb->head == rb->tail) {
        return 0;                 /* 空 */
    }
    *out = rb->buf[rb->tail];
    rb->tail = (uint16_t)((rb->tail + 1u) & (UART_RB_SIZE - 1u));
    return 1;
}

/* BRR = fCK/(16×baud)，四舍五入；返回实际写入值便于核对误差 */
uint32_t usart1_baud_init(uint32_t pclk2, uint32_t baud)
{
    uint32_t brr = (pclk2 + baud / 2u) / baud;
    USART1->BRR = brr;
    USART1->CR1 |= USART_CR1_UE | USART_CR1_TE | USART_CR1_RE | USART_CR1_RXNEIE;
    return brr;
}

/* 波特率相对误差（ppm）：越小越好，一般要求 < 2% */
int32_t usart1_baud_error_ppm(uint32_t pclk2, uint32_t baud)
{
    uint32_t brr = (pclk2 + baud / 2u) / baud;
    if (brr == 0u) {
        return 1000000; /* 非法 */
    }
    int32_t actual = (int32_t)(pclk2 / brr);
    return (actual - (int32_t)baud) * 1000000 / (int32_t)baud;
}

/* 中断：先读 SR 再读 DR。ORE 会锁住后续接收，必须读 DR 清掉，否则整段数据丢失 */
void USART1_IRQHandler(void)
{
    uint32_t sr = USART1->SR;
    if (sr & USART_SR_RXNE) {
        uint8_t b = (uint8_t)USART1->DR;
        if (!uart_rb_push(&g_rx, b)) {
            g_rx_overrun++;
        }
    } else if (sr & USART_SR_ORE) {
        (void)USART1->DR;
        g_rx_overrun++;
    }
}

/* esp_m07_uart.c — ESP32 UART：时钟来自 APB(80MHz)，CLKDIV=APB/baud
 * 与 STM32 不同：ESP32 有 128 字节硬件 FIFO，数据搬运用中断/驱动队列。 */
#include "esp32_regs.h"

uint32_t esp_uart_set_baud(uint32_t base, uint32_t baud)
{
