/* h7_m07_uart.c — STM32H7 USART（v2）：ISR/ICR/RDR/TDR 取代 F1 的 SR/DR
 * BRR 公式与格式（含 1/16 小数）与 F1 相同，但寄存器访问方式全变。 */
#include "stm32h7_regs.h"

uint32_t h7_usart1_baud(uint32_t pclk, uint32_t baud)
{
    uint32_t brr = (pclk + baud / 2u) / baud;   /* 与 F1 同：BRR=fCK/baud，含小数位 */
    H7_USART1->BRR = brr;
    H7_USART1->CR1 |= H7_USART_CR1_UE | H7_USART_CR1_TE | H7_USART_CR1_RE;
    return brr;
}

int h7_usart1_getc(uint8_t *c)
{
    if (H7_USART1->ISR & H7_USART_ISR_RXNE) {
        *c = (uint8_t)H7_USART1->RDR;   /* v2 用 RDR，不是 DR */
        return 1;
    }
    return 0;
}

void h7_usart1_putc(uint8_t c)
{
    while ((H7_USART1->ISR & H7_USART_ISR_TXE) == 0u) {
    }
    H7_USART1->TDR = c;                 /* v2 用 TDR */
}

/* v2 的错误标志集中在 ISR，用 ICR 清；ORE 依然是“不处理就锁死接收”的头号坑 */
void h7_usart1_clear_errors(void)
{
    H7_USART1->ICR = (1u << 1) | (1u << 3);   /* 清 ORE/错误标志（见 RM0433） */
}

static int wait_flag(volatile uint32_t *sr, uint32_t mask) {
    uint32_t to = 100000;
    while (!(*sr & mask)) { if (--to == 0) return -1; }  // 带超时
    return 0;
}
/* 线路清理与控制器复位是不同操作；见下方恢复流程。 */

/* m08_i2c.c — B05-M08 STM32F103 单字节读取教学片段。
 * 前置：单控制器、独占 I2C1、已配置时钟/开漏引脚/CR2/CCR/TRISE，POS=0。
 * 计数上限只限制循环次数，不是毫秒期限；产品驱动须换成单调时钟期限。
 * 返回失败后禁止直接重试：调用者须检查线路、复位并重新初始化控制器。
 * 这里只展示寄存器顺序，未在本轮用目标板验证。 */
#include "stm32f103_regs.h"

#define I2C_TIMEOUT 100000u

static int i2c_wait_sr1(uint32_t mask, int want_set)
{
    for (uint32_t t = 0u; t < I2C_TIMEOUT; ++t) {
        if (((I2C1->SR1 & mask) != 0u) == (want_set != 0)) {
            return 0;
        }
    }
    return -1; /* 超时：总线可能被从机拉死 */
}

/* 从机 7 位地址 addr7，读其内部寄存器 reg */
int i2c1_read_reg(uint8_t addr7, uint8_t reg, uint8_t *val)
{
    if (addr7 > 0x7fu || val == 0) return -2;
    if (I2C1->SR2 & I2C_SR2_BUSY) return -3;
    I2C1->CR1 |= I2C_CR1_START;
    if (i2c_wait_sr1(I2C_SR1_SB, 1)) return -1;      /* 起始已发 */
    I2C1->DR = (uint32_t)(addr7 << 1);               /* 写地址 */
    if (i2c_wait_sr1(I2C_SR1_ADDR, 1)) return -1;
    (void)I2C1->SR2;                                 /* 读 SR2 清 ADDR */
    I2C1->DR = reg;
    /* 等 BTF（字节完全移出）再发重复起始；只等 TXE 可能在数据仍在总线上时过早发起，
     * 这是 F1 上“偶尔读错/收到 NACK”的隐蔽原因。 */
    if (i2c_wait_sr1(I2C_SR1_BTF, 1)) return -1;

    I2C1->CR1 |= I2C_CR1_START;                      /* 重复起始 */
    if (i2c_wait_sr1(I2C_SR1_SB, 1)) return -1;
    I2C1->DR = (uint32_t)((addr7 << 1) | 1u);        /* 读地址 */
    if (i2c_wait_sr1(I2C_SR1_ADDR, 1)) return -1;

    /* F1 单字节接收：ADDR 清除与 STOP 设置不能被中断打断；恢复原 PRIMASK。 */
    uint32_t primask;
    __asm volatile ("mrs %0, primask\n\tcpsid i" : "=r"(primask) :: "memory");
    I2C1->CR1 &= ~I2C_CR1_ACK;                       /* 单字节读：先 NACK */
    (void)I2C1->SR2;
    I2C1->CR1 |= I2C_CR1_STOP;
    __asm volatile ("msr primask, %0" :: "r"(primask) : "memory");
    if (i2c_wait_sr1(I2C_SR1_RXNE, 1)) return -1;
    *val = (uint8_t)I2C1->DR;
    return 0;
}

/* 只复位本机控制器，不产生 SCL 脉冲，也不能释放被从机持续拉低的线路。
 * 保持 PE=0；调用者须先处理占线，再重新配置 CR2/CCR/TRISE 等并使能外设。 */
void i2c1_controller_reset(void)
{
    I2C1->CR1 |= I2C_CR1_SWRST;
    b05_dsb();
    I2C1->CR1 &= ~I2C_CR1_SWRST;
    I2C1->CR1 &= ~I2C_CR1_PE;
}

/* ESP-IDF 6.0 I2C 主机 API；组件依赖 esp_driver_i2c。
 * dev 来自已配置总线上的 i2c_master_bus_add_device；器件地址在设备配置中设置。
 * 只支持同步模式（未注册异步回调），缓冲区在调用返回前有效。
 * 此文件是 SDK 函数片段；构建入口见 B06，I2C 接线和故障恢复仍须目标板验证。 */
#include <stdint.h>
#include <stddef.h>
#include "driver/i2c_master.h"
#include "esp_err.h"

esp_err_t esp_i2c_read_reg(i2c_master_dev_handle_t dev, uint8_t reg, uint8_t *val)
{
    if (dev == NULL || val == NULL) return ESP_ERR_INVALID_ARG;
    uint8_t received = 0;
    /* 写寄存器地址后重复 START，再读一个字节；100 是毫秒，不是 RTOS tick。 */
    esp_err_t err = i2c_master_transmit_receive(dev, &reg, 1, &received, 1, 100);
    if (err == ESP_OK) *val = received; /* 失败时不提交不完整结果 */
    return err;
}

/* h7_m08_i2c.c — STM32H7 I²C（v2）：TIMINGR 预置时序、CR2 发起、ISR 状态、TXDR/RXDR
 * 与 F1 的 I2C v1（CR1/SR1/SR2、手动 START/ACK）是两套不同的编程模型。
 * 教学片段：时钟、开漏引脚、滤波、单调期限和故障恢复由完整工程配置。
 * 仅用于独占单控制器；失败后须清理/重新初始化再重试。本轮未做目标板验证。 */
#include "stm32h7_regs.h"

void h7_i2c1_init(uint32_t timingr)
{
    H7_I2C1->CR1 &= ~1u;       /* TIMINGR 只能在 PE=0 时配置 */
    H7_I2C1->TIMINGR = timingr; /* SCLDEL/SDADEL/SCLH/SCLL，按 PCLK 与目标速率算，替代 F1 的 CCR/TRISE */
    H7_I2C1->CR1 |= 1u;
}

static int h7_i2c_wait(uint32_t mask)
{
    for (uint32_t t = 0u; t < 100000u; ++t) {
        if (H7_I2C1->ISR & H7_I2C_ISR_NACKF) { return -2; }
        if (H7_I2C1->ISR & mask) { return 0; }
    }
    return -1;
}

int h7_i2c1_read_reg(uint8_t addr7, uint8_t reg, uint8_t *val)
{
    if (addr7 > 0x7fu || val == 0) { return -3; }
    /* 写阶段：NBYTES=1，RELOAD=0、AUTOEND=0，完成后等 TC 再重复 START。
     * RELOAD=1 会进入 TCR，不能在该配置下等待 TC。 */
    H7_I2C1->CR2 = ((uint32_t)addr7 << 1) | (1u << 16) | (1u << 13);
    if (h7_i2c_wait(H7_I2C_ISR_TXIS)) { return -1; }
    H7_I2C1->TXDR = reg;
    if (h7_i2c_wait(H7_I2C_ISR_TC)) { return -1; }
    if (H7_I2C1->ISR & H7_I2C_ISR_NACKF) { return -2; }

    /* 读阶段：1 字节，AUTOEND=1 自动发 STOP */
    H7_I2C1->CR2 = ((uint32_t)addr7 << 1) | (1u << 16) | (1u << 10)
                 | (1u << 13) | (1u << 25);
    if (h7_i2c_wait(H7_I2C_ISR_RXNE)) { return -1; }
    uint8_t received = (uint8_t)H7_I2C1->RXDR;
    if (h7_i2c_wait(1u << 5)) { return -1; } /* STOPF：等 AUTOEND 真正结束 */
    H7_I2C1->ICR = 1u << 5;                 /* STOPCF */
    *val = received;
    return 0;
}

static uint8_t spi_xfer(uint8_t b) {
    *(volatile uint8_t *)&SPI1->DR = b;      // 只写低字节
    while (!(SPI1->SR & SPI_SR_RXNE)) {}
    return *(volatile uint8_t *)&SPI1->DR;   // 只读低字节
}
/* 读 JEDEC ID：0x9F 后连读 3 字节，W25Q -> 0xEF 0x40 0x15 */

/* m09_spi.c — B05-M09 SPI
 * SPI 模式 0（CPOL=0/CPHA=0）读 Flash JEDEC ID；软件片选。 */
#include "stm32f103_regs.h"

#define FLASH_CS_PIN 4u   /* 软件片选：PA4，推挽 50 MHz */

static uint8_t spi1_xfer(uint8_t out)
{
    while ((SPI1->SR & SPI_SR_TXE) == 0u) {
    }
    *((volatile uint8_t *)&SPI1->DR) = out;   /* F1 上 8 位传输只写低字节 */
    while ((SPI1->SR & SPI_SR_RXNE) == 0u) {
    }
    return *((volatile uint8_t *)&SPI1->DR);
}

void spi1_init(void)
{
    RCC_APB2ENR |= (1u << 12) | RCC_APB2ENR_IOPAEN;   /* SPI1EN */
    /* PA4 片选：通用推挽 50 MHz */
    GPIOA->CRL = (GPIOA->CRL & ~(0xFu << (FLASH_CS_PIN * 4u)))
               | ((uint32_t)GPIO_CNF_OUT_PP << 2)
               | (uint32_t)GPIO_MODE_OUT_50M;
    /* SPI1 默认引脚：PA5=SCK、PA7=MOSI 复用推挽 50 MHz；PA6=MISO 浮空输入。
     * 漏配这三个引脚是最常见的“代码对但收不到数据”。 */
    GPIOA->CRL = (GPIOA->CRL & ~((0xFu << 20) | (0xFu << 24) | (0xFu << 28)))
               | (0xBu << 20)   /* PA5 AF-PP（CNF=10,MODE=11） */
               | (0x4u << 24)   /* PA6 浮空输入（CNF=01,MODE=00） */
               | (0xBu << 28);  /* PA7 AF-PP */
    /* 模式 0 = CPOL=0, CPHA=0；主模式；软件 NSS 且内部拉高；预分频 8（72/8=9 MHz） */
    SPI1->CR1 = SPI_CR1_MSTR | SPI_CR1_SSM | SPI_CR1_SSI
              | (0x2u << 3) | SPI_CR1_SPE;
    GPIOA->BSRR = (1u << FLASH_CS_PIN);                /* 拉高，空闲 */
}

static void cs_low(void)  { GPIOA->BSRR = (1u << (FLASH_CS_PIN + 16u)); }
static void cs_high(void) { GPIOA->BSRR = (1u << FLASH_CS_PIN); }

uint32_t spi_flash_jedec_id(void)
{
    cs_low();
    (void)spi1_xfer(0x9Fu);                    /* JEDEC ID 命令 */
    uint32_t id = (uint32_t)spi1_xfer(0x00);
    id |= (uint32_t)spi1_xfer(0x00) << 8;
    id |= (uint32_t)spi1_xfer(0x00) << 16;
    cs_high();
    return id;                                 /* 典型 Winbond = 0xEF4015 */
}

/* 读状态寄存器 SR1，轮询 BUSY 位 */
uint8_t spi_flash_status(void)
{
    cs_low();
    (void)spi1_xfer(0x05u);
    uint8_t st = spi1_xfer(0x00);
    cs_high();
    return st;
}

/* esp_m09_spi.c — ESP32 SPI：时钟来自 APB，常用 spi_device_transmit 一次事务
 * ESP32 的 SPI 有 1..4 号控制器，SPI2/3 常作主模式接 Flash/传感器。 */
#include <stdint.h>

extern int spi_bus_initialize(int host, const void *cfg, int dma_chan);
extern int spi_bus_add_device(int host, const void *cfg, void **out_dev);
extern int spi_device_transmit(void *dev, void *trans);
extern int spi_bus_remove_device(void *dev);

int esp_spi1_xfer(void *dev, void *trans)
{
    return spi_device_transmit(dev, trans);   /* trans 里指定 tx_buffer/rx_buffer/length */
}

/* 与 STM32 的关键差异：ESP32 的片选、时钟相位/极性、位序都在 bus/device 配置结构里，
 * 且可走 GPIO Matrix 把 SPI 信号映射到任意可用引脚。 */
int esp_spi_bus_up(int host, const void *buscfg)
