}

/* h7_m09_spi.c — STM32H7 SPI（v2）：CFG1/CFG2/IER/SR/TXDR/RXDR，带 FIFO
 * 与 F1 的 CR1/CR2/SR/DR 模型不同；数据通过 TXDR/RXDR，且 FIFO 深度可配。 */
#include "stm32h7_regs.h"

void h7_spi1_init(void)
{
    H7_RCC_APB2ENR |= (1u << 12);          /* SPI1 时钟（示意） */
    H7_SPI1->CFG1 = (7u << 0)              /* DSIZE=8 位（DSIZE=size-1） */
                  | (3u << 28);            /* MBR：主模式波特率预分频（见 RM0433） */
    H7_SPI1->CFG2 = (1u << 22)             /* MASTER */
                  | (1u << 26);            /* SSM：软件片选 */
    H7_SPI1->CR1 = H7_SPI_CR1_SPE | (1u << 12);   /* SPE | SSI */
}

/* 全双工 8 位收发：FIFO 使能后 TXDR/RXDR 需 4 字节对齐访问 */
void h7_spi1_xfer(const uint8_t *tx, uint8_t *rx, uint16_t n)
{
    for (uint16_t i = 0u; i < n; ++i) {
        while ((H7_SPI1->SR & H7_SPI_SR_TXP) == 0u) {
        }
        *((volatile uint8_t *)&H7_SPI1->TXDR) = tx[i];
        while ((H7_SPI1->SR & H7_SPI_SR_RXP) == 0u) {
        }
        rx[i] = *((volatile uint8_t *)&H7_SPI1->RXDR);
    }
}

uint32_t csr = RCC->CSR;
if (csr & RCC_CSR_IWDGRSTF) reason = RESET_IWDG;   // bit29
else if (csr & RCC_CSR_SFTRSTF) reason = RESET_SW; // bit28
else if (csr & RCC_CSR_PORRSTF) reason = RESET_POR; // bit27
RCC->CSR |= RCC_CSR_RMVF;   // bit24 写 1 清除所有复位标志
// 只有 reasons==ALL 时才喂狗：IWDG->KR = 0xAAAA;

/* m10_watchdog.c — B05-M10 看门狗与低功耗
 * IWDG 初始化/喂狗 + 复位原因判别 + STOP 低功耗。 */
#include "stm32f103_regs.h"

#define SCB_SCR  R32(0xE000ED10u)
#define SCB_SCR_SLEEPDEEP (1u << 2)

/* LSI≈40kHz，PR=/64 → 计数 625Hz；reload 12 位上限 4095 → 最长约 6.55 s */
void iwdg_init(uint16_t reload)
{
    IWDG_KR = IWDG_KEY_ENABLE;          /* 解锁 PR/RLR 写保护 */
    IWDG_PR = 4u;                       /* 预分频 /64 */
    while (IWDG_SR & IWDG_SR_PVU) {     /* 等预分频更新完成 */
    }
    IWDG_RLR = reload;
    while (IWDG_SR & IWDG_SR_RVU) {     /* 等重装值更新完成（漏了 RVU 会写入无效） */
    }
    IWDG_KR = IWDG_KEY_RELOAD;
    IWDG_KR = IWDG_KEY_START;           /* 启动后无法关闭，只能复位 */
}

void iwdg_feed(void) { IWDG_KR = IWDG_KEY_RELOAD; }

/* 复位原因：RCC_CSR 的位号容易记错，这里逐位核对（bit31..26 与 RMVF=bit24） */
const char *reset_cause_str(void)
{
    uint32_t csr = RCC_CSR;
    const char *s;
    if      (csr & RCC_CSR_IWDGRSTF) s = "独立看门狗";
    else if (csr & RCC_CSR_WWDGRSTF) s = "窗口看门狗";
    else if (csr & RCC_CSR_SFTRSTF)  s = "软件复位";
    else if (csr & RCC_CSR_PORRSTF)  s = "上电/掉电复位";
    else if (csr & RCC_CSR_PINRSTF)  s = "外部 NRST";
    else if (csr & RCC_CSR_LPWRRSTF) s = "低功耗复位";
    else                             s = "未知";
    RCC_CSR |= RCC_CSR_RMVF;            /* 写 1 清全部标志，避免跨复位残留误判 */
    return s;
}

/* 进入 STOP：保留 SRAM，唤醒后继续；唤醒源可为 EXTI 中断 */
void enter_stop_mode(void)
{
    PWR_CR |= PWR_CR_CWUF;                 /* 清唤醒标志 */
    PWR_CR &= ~PWR_CR_PDDS;                /* STOP（非 STANDBY） */
    PWR_CR |= PWR_CR_LPDS;                 /* 深度睡眠时稳压器低功耗 */
    SCB_SCR |= SCB_SCR_SLEEPDEEP;          /* 选择深度睡眠 */
    __asm volatile ("wfi");
    SCB_SCR &= ~SCB_SCR_SLEEPDEEP;
    PWR_CR &= ~PWR_CR_LPDS;
}

/* 在 STOP 前把现场写入备份寄存器（需先开 PWR/BKP 时钟并解锁 DBP） */
void backup_marker_write(uint32_t marker)
{
    RCC_APB1ENR |= RCC_APB1ENR_PWREN | RCC_APB1ENR_BKPEN;
    PWR_CR |= PWR_CR_DBP;                  /* 解锁备份域写保护 */
    BKP_DR1 = marker;
    b05_dsb();
}

/* esp_m10_watchdog.c — ESP32 看门狗与低功耗：RTC_WDT 跨 deep-sleep，复位原因用 API 读
 * 与 STM32 的 IWDG + RCC_CSR 不同，ESP32 分 RTC_WDT（可跨睡眠）与 TWDT（任务看门狗）。 */
#include "esp32_regs.h"

typedef enum {
    ESP_RST_UNKNOWN, ESP_RST_POWERON, ESP_RST_EXT, ESP_RST_SW,
    ESP_RST_PANIC, ESP_RST_INT_WDT, ESP_RST_TASK_WDT, ESP_RST_WDT,
    ESP_RST_DEEPSLEEP, ESP_RST_BROWNOUT, ESP_RST_SDIO
} esp_reset_reason_t;

extern esp_reset_reason_t esp_reset_reason(void);   /* 比裸寄存器可靠，避免位义记错 */
extern void esp_deep_sleep_start(void);
extern unsigned long long esp_sleep_get_wakeup_cause(void);
extern int esp_sleep_enable_timer_wakeup(unsigned long long us);

/* 每 10 分钟唤醒一次的低功耗节点：定时器唤醒 + deep sleep */
int esp_lowpower_node_start(unsigned int period_s)
{
    esp_sleep_enable_timer_wakeup((unsigned long long)period_s * 1000000ull);
    return (int)esp_sleep_get_wakeup_cause();
}

void esp_enter_deep_sleep(void) { esp_deep_sleep_start(); }

/* RTC 域在 deep sleep 中保持：RTC GPIO / RTC memory 可用于唤醒与保存现场 */
int esp_reset_is_poweron(void) { return esp_reset_reason() == ESP_RST_POWERON; }

/* h7_m10_watchdog.c — STM32H7 看门狗与低功耗：IWDG 寄存器与 F1 相同，低功耗分域不同
 * H7 有 D1/D2/D3 与 DSTANDBY/SRDSB1 等位，STOP/STANDBY 的保留范围比 F1 复杂。 */
#include "stm32h7_regs.h"

#define H7_IWDG_BASE 0x58004800u
#define H7_IWDG_KR   R32(H7_IWDG_BASE + 0x00u)
#define H7_IWDG_PR   R32(H7_IWDG_BASE + 0x04u)
#define H7_IWDG_RLR  R32(H7_IWDG_BASE + 0x08u)
#define H7_IWDG_SR   R32(H7_IWDG_BASE + 0x0Cu)
#define H7_PWR_CPUCR R32(0x58024810u)

void h7_iwdg_init(uint16_t reload)
{
    H7_IWDG_KR = 0x5555u;                    /* 解锁 */
    H7_IWDG_PR = 4u;                         /* /64 */
    while (H7_IWDG_SR & (1u << 0)) { }       /* PVU */
    H7_IWDG_RLR = reload;
    while (H7_IWDG_SR & (1u << 1)) { }       /* RVU */
    H7_IWDG_KR = 0xAAAAu;                    /* 重装 */
    H7_IWDG_KR = 0xCCCCu;                    /* 启动 */
}

void h7_iwdg_feed(void) { H7_IWDG_KR = 0xAAAAu; }

/* 复位原因：H7 在 RCC_RSR（与 F1 的 RCC_CSR 不同），位义也不同 */
uint32_t h7_reset_flags(void) { return R32(0x58024484u); }   /* RCC_RSR */

/* 进入 D1/D2 STOP：CPUCR 置 PDDS_D1/D2 等（此处示意，完整序列见 RM0433） */
void h7_enter_stop(void)
{
    H7_PWR_CPUCR |= (1u << 0);               /* PDDS_D1 */
    __asm volatile ("wfi");
}

