/* m12_layers.c — B05-M12 分层取舍：同一“置位 LED”的三种写法体积对照
 * 用 -ffunction-sections + objdump 逐函数看体量；正文给出真实测量。 */
#include "stm32f103_regs.h"

/* 档 1：裸寄存器宏 */
void led_set_reg(void) { GPIOC->BSRR = (1u << 13); }

/* 档 2：CMSIS 风格内联封装（仍是编译期展开，零调用开销） */
static inline void gpio_set_bits(gpio_t *port, uint32_t bits)
{
    port->BSRR = bits;
}
void led_set_inline(void) { gpio_set_bits(GPIOC, (1u << 13)); }

/* 档 3：带句柄的运行期抽象（多一次间接访问，换来可替换实现） */
typedef struct {
    gpio_t  *port;
    uint32_t pin;
} gpio_handle_t;

static gpio_handle_t g_led = { GPIOC, 13u };

void gpio_handle_write(gpio_handle_t *h, int on)
{
    if (on) {
        h->port->BSRR = (1u << h->pin);
    } else {
        h->port->BSRR = (1u << (h->pin + 16u));
    }
}

void led_set_handle(void) { gpio_handle_write(&g_led, 1); }

/* esp_m12_layers.c — 同一“置位 LED”的三种写法（ESP32 版），用于跨平台体积对照 */
#include "esp32_regs.h"

/* 档 1：裸寄存器 */
void esp_led_reg(void) { GPIO_OUT_W1TS = (1u << 2); }

/* 档 2：内联封装（等价零开销） */
static inline void esp_gpio_set(uint32_t bits) { GPIO_OUT_W1TS = bits; }
void esp_led_inline(void) { esp_gpio_set(1u << 2); }

/* 档 3：IDF 驱动（运行期句柄 + 可能的多层校验，换可移植性） */
extern int gpio_set_level(int gpio_num, uint32_t level);
void esp_led_idf(void) { (void)gpio_set_level(2, 1); }

/* 与 STM32 一致的结论：内联封装通常零开销；句柄/驱动层在“运行期不可知”时才有成本，
 * 但 ESP-IDF 的驱动还额外带来跨芯片可移植性与一致性检查。 */

/* h7_m12_layers.c — 同一“置位 LED”的三种写法（H7 版），用于跨平台体积对照
 * H7 的 BSRR 与 F1 语义相同，但 MODER 是 2 位/引脚；抽象层次与取舍结论与 F1 一致。 */
#include "stm32h7_regs.h"

/* 档 1：裸寄存器 */
void h7_led_reg(void) { H7_GPIOB->BSRR = (1u << 0); }

/* 档 2：内联封装（零开销抽象） */
static inline void h7_gpio_set(h7_gpio_t *p, uint32_t bits) { p->BSRR = bits; }
void h7_led_inline(void) { h7_gpio_set(H7_GPIOB, (1u << 0)); }

/* 档 3：运行期句柄 */
typedef struct { h7_gpio_t *port; uint32_t pin; } h7_gpio_handle_t;
static h7_gpio_handle_t g_h7_led = { H7_GPIOB, 0u };

void h7_gpio_handle_write(h7_gpio_handle_t *h, int on)
{
    h->port->BSRR = on ? (1u << h->pin) : (1u << (h->pin + 16u));
}

void h7_led_handle(void) { h7_gpio_handle_write(&g_h7_led, 1); }

/* host_crc16.c — CRC16-CCITT(FALSE) 自检（gcc 主机运行）
 * 与“设备端存储/协议校验”共用同一算法，用已知向量 0x29B1 对齐。 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint16_t crc16_ccitt(const uint8_t *p, uint32_t n)
{
    uint16_t crc = 0xFFFFu;
    for (uint32_t i = 0u; i < n; ++i) {
        crc ^= (uint16_t)p[i] << 8;
        for (int b = 0; b < 8; ++b) {
            crc = (crc & 0x8000u) ? (uint16_t)((crc << 1) ^ 0x1021u)
                                  : (uint16_t)(crc << 1);
        }
    }
    return crc;
}

int main(void)
{
    const char *check = "123456789";
    uint16_t got = crc16_ccitt((const uint8_t *)check, (uint32_t)strlen(check));
    printf("crc16(\"%s\") = 0x%04X (expect 0x29B1)\n", check, got);
    int ok = (got == 0x29B1u);
    printf(ok ? "RESULT: PASS\n" : "RESULT: FAIL\n");
    return ok ? 0 : 1;
}

/* m13_storage.c — B05-M13 存储器与文件系统接口
 * 块设备抽象 + 掉电可恢复的追加日志（先写数据，最后写“有效”标志）。
 * 关键：区分“写入完成”和“已持久化”，靠提交标记而不是靠写返回判定。 */
#include <stdint.h>
#include <stddef.h>

typedef struct {
    int      (*read)(uint32_t block, void *buf);
    int      (*write)(uint32_t block, const void *buf);
    int      (*erase)(uint32_t block);
    uint32_t block_size;
} blk_dev_t;

/* 记录头：valid 用“魔数”做提交标记。
 * Flash 只能把位从 1 写成 0（擦除后为 0xFF）；所以“未提交”用擦除值 0xFFFF，
 * 提交时写 0xA5A5（在 0xFFFF 上只清位，合法）。
 * 陷阱：先写 0x0000 再改成 0xA5A5 是“置位”，在 Flash 上非法——
 * 这正是本示例第一版会踩的坑，也是理解掉电原子性的关键。 */
#define LOG_VALID_MAGIC  0xA5A5u
#define LOG_VALID_ERASED 0xFFFFu
typedef struct {
    uint32_t seq;
    uint32_t len;
    uint16_t valid;     /* 0xFFFF=未提交（擦除态），0xA5A5=已提交 */
    uint16_t crc;
} log_hdr_t;

static uint16_t crc16_ccitt(const uint8_t *p, uint32_t n)
{
    uint16_t crc = 0xFFFFu;
    for (uint32_t i = 0u; i < n; ++i) {
        crc ^= (uint16_t)p[i] << 8;
        for (int b = 0; b < 8; ++b) {
            crc = (crc & 0x8000u) ? (uint16_t)((crc << 1) ^ 0x1021u) : (uint16_t)(crc << 1);
        }
    }
    return crc;
}

/* 写一条记录：块内布局 = [hdr][payload]。擦除后整块为 0xFF。 */
int log_append(blk_dev_t *dev, uint32_t block, uint32_t seq,
               const void *payload, uint32_t len)
{
    if (dev == NULL || len > dev->block_size - sizeof(log_hdr_t)) {
        return -1;
    }
    if (dev->erase(block) != 0) {
        return -2;
    }
    static uint8_t page[4096];
    log_hdr_t *hdr = (log_hdr_t *)page;
    hdr->seq   = seq;
    hdr->len   = len;
    hdr->valid = LOG_VALID_ERASED;    /* 擦除态=未提交，防掉电读到半成品 */
    hdr->crc   = crc16_ccitt((const uint8_t *)payload, len);
    const uint8_t *src = (const uint8_t *)payload;
    for (uint32_t i = 0u; i < len; ++i) {
        page[sizeof(log_hdr_t) + i] = src[i];
    }
    if (dev->write(block, page) != 0) {
        return -3;                   /* 写入失败 */
    }
    /* 提交：把 valid 从 0xFFFF 写成 0xA5A5（只清位，Flash 允许）；掉电最多丢这一条 */
    hdr->valid = LOG_VALID_MAGIC;
    if (dev->write(block, page) != 0) {
        return -4;
    }
    return 0;                        /* 返回 0 表示已提交；持久化仍以回读校验为准 */
}

int log_read(blk_dev_t *dev, uint32_t block, uint32_t *seq, uint32_t *len)
{
    static uint8_t page[4096];
    if (dev->read(block, page) != 0) {
        return -1;
    }
    const log_hdr_t *hdr = (const log_hdr_t *)page;
    if (hdr->valid != LOG_VALID_MAGIC) {
        return 1;                    /* 未提交记录：视为无效，跳过 */
    }
    *seq = hdr->seq;
    *len = hdr->len;
    return 0;
}

/* esp_m13_storage.c — ESP32 存储：分区表 + NVS/SPIFFS/LittleFS
 * 与 STM32 直接擦写 Flash 不同，ESP32 把 Flash 划分成多个分区，各挂不同文件系统。 */
#include <stdint.h>
#include <stddef.h>

/* partitions.csv 里定义分区，例如：
 *   nvs,      data, nvs,     0x9000,  0x6000
 *   spiffs,   data, spiffs,  0x10000, 0x100000
 * 应用用 esp_partition_find_first 找到分区，再挂载文件系统。 */
typedef int esp_err_t;
typedef struct {
    int      (*read)(uint32_t offset, void *buf, uint32_t len);
    esp_err_t (*write)(uint32_t offset, const void *buf, uint32_t len);
    esp_err_t (*erase_range)(uint32_t offset, uint32_t len);
} esp_partition_t;

extern esp_err_t nvs_flash_init(void);
extern esp_err_t esp_vfs_spiffs_register(const void *cfg);   /* 或 esp_littlefs 挂载 */

/* 键值参数用 NVS（内部自带磨损均衡与掉电安全）；大文件用 SPIFFS/LittleFS 分区 */
esp_err_t esp_storage_init(void)
{
    esp_err_t a = nvs_flash_init();
    if (a != 0) { return a; }
    return esp_vfs_spiffs_register((const void *)0);
}

/* 追加日志的提交语义与 STM32/H7 相同：擦除态→提交魔数（只清位）。
 * ESP32 的 NVS 已经把这一步封装好了，多数场景不必自己写。 */
int esp_log_commit(uint16_t *valid_word)
{
    if (valid_word == NULL || *valid_word != 0xFFFFu) { return -1; }
    *valid_word = 0xA5A5u;
    return 0;
}

/* h7_m13_storage.c — STM32H7 存储：内部 Flash 扇区达 128KB；外扩常用 QUADSPI/OCTOSPI/FMC
 * 提交标记（擦除态 0xFFFF→0xA5A5）与 F1 同一逻辑；新增点是 cache 与擦写粒度更大。 */
#include <stdint.h>
#include <stddef.h>

typedef struct {
    int      (*read)(uint32_t block, void *buf);
    int      (*write)(uint32_t block, const void *buf);
    int      (*erase)(uint32_t block);
    uint32_t block_size;
} h7_blk_dev_t;

/* H7 内部 Flash 扇区 0..7 各 128KB；外扩 OCTOSPI NOR 常按 4KB 擦。
 * 无论哪种，掉电原子性都靠“擦除态→提交魔数”的只清位写法。 */
int h7_log_commit(h7_blk_dev_t *dev, uint32_t block, uint16_t *valid_word)
{
    if (dev == NULL || valid_word == NULL) { return -1; }
    if (*valid_word != 0xFFFFu) { return -2; }   /* 已被写过：需先擦除 */
    *valid_word = 0xA5A5u;                        /* 只清位，合法 */
    return dev->write(block, valid_word) == 0 ? 0 : -3;
}

/* 外扩 NOR/SDRAM 常用地址：0x90000000（OCTOSPI1）；0xC0000000（SDRAM via FMC） */
uint32_t *h7_ext_nor_base(void) { return (uint32_t *)0x90000000u; }

