/* 查询连接状态：AT+CWJAP? 或 AT+CIPSTATUS */
int wifi_h7_query_ip(char *ip_out, int cap)
{
    if (uart_at_send("AT+CIPSTA?") != 0) { return -1; }
    char rsp[160];
    int r = uart_at_read(rsp, sizeof(rsp), 1500);
    if (r <= 0) { return -2; }
    char *p = strstr(rsp, "ip:\"");
    if (!p) { return -3; }
    p += 4;
    int n = 0;
    while (*p && *p != '"' && n < cap - 1) { ip_out[n++] = *p++; }
    ip_out[n] = '\0';
    return 0;
}

