/* m21_ota_boot.c — B05-M21 OTA（STM32F103 自研 Bootloader：校验 + 跳转 + 回滚标志） */
#include "stm32f103_regs.h"

#define APP_BASE 0x08004000u          /* App 从 16KB 处开始，Bootloader 占前 16KB */
typedef void (*app_entry_t)(void);

/* CRC32（与 App 端一致）；用于判断镜像完整，避免跳到半包 */
uint32_t crc32_bytes(const uint8_t *p, uint32_t n)
{
    uint32_t crc = 0xFFFFFFFFu;
    for (uint32_t i = 0; i < n; ++i) {
        crc ^= p[i];
        for (int b = 0; b < 8; ++b) {
            crc = (crc & 1u) ? (crc >> 1) ^ 0xEDB88320u : (crc >> 1);
        }
    }
    return ~crc;
}

/* 校验 App：栈顶必须落在 SRAM、复位向量必须落在 Flash 的 App 区 */
int ota_boot_validate(uint32_t app_base)
{
    uint32_t sp = *(volatile uint32_t *)app_base;
    uint32_t pc = *(volatile uint32_t *)(app_base + 4u);
    if (sp < 0x20000000u || sp > 0x20010000u) { return -1; }
    if (pc < app_base || pc > 0x08040000u) { return -2; }
    return 0;
}

void ota_boot_jump(uint32_t app_base)
{
    uint32_t sp = *(volatile uint32_t *)app_base;
    uint32_t pc = *(volatile uint32_t *)(app_base + 4u);
    /* 跳转前必须关中断并（真实工程里）复位外设/清挂起，避免 App 启动瞬间被旧中断打断 */
    __asm volatile ("cpsid i" ::: "memory");
    SCB_VTOR = app_base;                       /* App 的向量表 */
    b05_dsb(); b05_isb();
    __asm volatile ("msr msp, %0" :: "r"(sp)); /* 先设栈顶 */
    ((app_entry_t)pc)();                       /* 再跳复位向量 */
}

/* 升级请求标志：由 App 写入备份寄存器，Bootloader 读后决定是否进入升级 */
void ota_request_upgrade(uint32_t token) { BKP_DR1 = token; }
int  ota_upgrade_pending(void) { return BKP_DR1 == 0x5AA50F0Fu; }
void ota_clear_upgrade(void) { BKP_DR1 = 0u; }

/* esp_m21_ota.c — B05-M21 OTA / 网络升级与回滚（ESP32 原生 A/B 分区）
 * 流程：写新固件到备用分区 → 校验 → 切启动分区 → 重启；新固件首次启动若不自证，可回滚。 */
#include <stdint.h>

typedef int esp_err_t;
typedef void *esp_ota_handle_t;
typedef void *esp_partition_t;

extern const esp_partition_t *esp_ota_get_next_update_partition(const void *start);
extern esp_err_t esp_ota_begin(const esp_partition_t *p, unsigned image_size, esp_ota_handle_t *out);
extern esp_err_t esp_ota_write(esp_ota_handle_t h, const void *data, unsigned size);
extern esp_err_t esp_ota_end(esp_ota_handle_t h);
extern esp_err_t esp_ota_set_boot_partition(const esp_partition_t *p);
extern esp_err_t esp_ota_mark_app_valid_cancel_rollback(void);
extern esp_err_t esp_ota_mark_app_invalid_rollback_and_reboot(void);

/* 分块写：每块都要检查返回值；中途断电，下次重新开始（备用分区不生效） */
int esp_ota_apply(const uint8_t *image, unsigned len, unsigned chunk)
{
    const esp_partition_t *target = esp_ota_get_next_update_partition((void *)0);
    if (target == (void *)0) { return -1; }
    esp_ota_handle_t h = (void *)0;
    if (esp_ota_begin(target, len, &h) != 0) { return -2; }
    for (unsigned off = 0; off < len; off += chunk) {
        unsigned n = (len - off < chunk) ? (len - off) : chunk;
        if (esp_ota_write(h, image + off, n) != 0) { return -3; }   /* 写入失败需中止 */
    }
    if (esp_ota_end(h) != 0) { return -4; }          /* 校验镜像 */
    if (esp_ota_set_boot_partition(target) != 0) { return -5; }
    return 0;                                        /* 返回后重启即运行新固件 */
}

/* 新固件启动并联网自检通过后调用：确认本次升级，取消回滚 */
int esp_ota_confirm(void) { return esp_ota_mark_app_valid_cancel_rollback(); }

/* h7_m21_ota.c — B05-M21 OTA（STM32H7：双 Bank 交换 + 安全回滚）
 * H7 的 Flash 支持双 Bank 与 Bank Swap：新固件写入备用 Bank，校验后交换启动 Bank。 */
#include "stm32h7_regs.h"

typedef int hal_status_t;
extern hal_status_t HAL_FLASH_Unlock(void);
extern hal_status_t HAL_FLASH_OB_Unlock(void);
extern hal_status_t HAL_FLASHEx_OBProgram(const void *cfg);
extern hal_status_t HAL_FLASH_OB_Launch(void);      /* 触发 Bank Swap 并复位 */

/* Option Bytes 里 SWAP_BANK 位决定从哪个 Bank 启动（见 RM0433 FLASH_OPTSR） */
int h7_ota_swap_bank(int enable_swap)
{
    if (HAL_FLASH_Unlock() != 0) { return -1; }
    if (HAL_FLASH_OB_Unlock() != 0) { return -2; }
    (void)enable_swap;                              /* cfg 里设置 SWAP_BANK */
    if (HAL_FLASHEx_OBProgram((const void *)0) != 0) { return -3; }
    return HAL_FLASH_OB_Launch();                   /* 交换后自动复位，从新 Bank 跑 */
}

/* 双 Bank 的分区语义：Bank1 跑当前固件，新固件写 Bank2；校验失败则保持原 Bank。 */
int h7_ota_bank_of(uint32_t addr) { return (addr < 0x08100000u) ? 1 : 2; }

/* 完整性：与 F1 相同的 CRC32 思路，防止交换到半包镜像 */
uint32_t h7_ota_crc32(const uint8_t *p, uint32_t n)
{
    uint32_t crc = 0xFFFFFFFFu;
    for (uint32_t i = 0; i < n; ++i) {
        crc ^= p[i];
        for (int b = 0; b < 8; ++b) {
            crc = (crc & 1u) ? (crc >> 1) ^ 0xEDB88320u : (crc >> 1);
        }
    }
    return ~crc;
}

/* capstone_node.c — B05 贯穿项目：电池供电环境采集节点（控制器骨架）
 * 串联 M01 时钟、M04 定时、M05/M06 ADC+DMA、M07 UART、M10 看门狗/低功耗、M13 存储。
 * 只做单文件编译（-c）；外设函数在对应模块中实现，此处用原型引用。 */
#include "stm32f103_regs.h"

/* 其它模块提供的接口（原型，便于单独编译本文件） */
extern uint32_t clock_init_72m(void);
extern void     systick_init_1ms(uint32_t sysclk_hz);
extern void     adc_dma_start(uint16_t *buf, uint16_t len);
extern void     iwdg_init(uint16_t reload);
extern void     iwdg_feed(void);
extern void     enter_stop_mode(void);
extern void     backup_marker_write(uint32_t marker);
extern int      uart_rb_pop(void *rb, uint8_t *out);

/* 与 M13 一致的块设备类型；g_log_dev 由存储模块提供 */
typedef struct {
    int      (*read)(uint32_t block, void *buf);
    int      (*write)(uint32_t block, const void *buf);
    int      (*erase)(uint32_t block);
    uint32_t block_size;
} blk_dev_t;
extern blk_dev_t g_log_dev;
extern int log_append(blk_dev_t *dev, uint32_t block, uint32_t seq,
                      const void *payload, uint32_t len);

extern volatile uint32_t g_systick_ms;

#define ADC_BUF_LEN 64u
static uint16_t s_adc_buf[ADC_BUF_LEN];
static uint32_t s_last_report_ms;

typedef struct {
    uint32_t boot_marker;
    uint16_t sample_period_ms;
    uint32_t report_period_ms;     /* 用 uint16 会溢出（600000→10176），这是 -Woverflow 抓到的真实 bug */
    uint32_t watchdog_reload;
} node_cfg_t;

static const node_cfg_t g_cfg = {
    .sample_period_ms = 10u,
    .report_period_ms = 600000u,   /* 每 10 分钟上报一次 */
    .watchdog_reload  = 3000u,     /* ~4.8 s 超时 */
};

/* 初始化：失败即返回，绝不带着半初始化硬件继续跑 */
int node_init(void)
{
    if (clock_init_72m() == 0u) {
        return -1;                 /* HSE 起振失败 */
    }
    systick_init_1ms(72000000u);
    backup_marker_write(0x0BADF00Du);
    iwdg_init((uint16_t)g_cfg.watchdog_reload);
    adc_dma_start(s_adc_buf, ADC_BUF_LEN);
    return 0;
}

/* 主循环：非阻塞调度，采集与上报解耦 */
void node_loop(void)
{
    for (;;) {
        iwdg_feed();               /* 只有走到这里才喂狗：卡死则复位 */

        if ((uint32_t)(g_systick_ms - s_last_report_ms) >= g_cfg.report_period_ms) {
            s_last_report_ms = g_systick_ms;
            uint32_t avg = 0u;
            for (uint32_t i = 0u; i < ADC_BUF_LEN; ++i) {
                avg += s_adc_buf[i];
            }
            avg /= ADC_BUF_LEN;
            uint16_t mv = (uint16_t)(avg * 3300u / 4095u);
            /* 记录一条并进入 STOP，由 RTC/EXTI 唤醒 */
            (void)log_append(&g_log_dev, 0u, g_systick_ms, &mv, sizeof(mv));
            enter_stop_mode();
        }
    }
}

/* Single CPU tick model: D=T, fixed C, no ISR/blocking/switch cost.
 * Response includes waiting: completion - release. Lower prio wins.
 * At missed deadline explicitly DROP unfinished job and release the next.
 * This models a declared overload policy, not an RTOS implementation. */
#include <stdio.h>
#include <string.h>
typedef struct {
    int prio, period, cost;
    int release, remaining, released, finished, missed, ticks, max_response;
} Task;
static int simulate(Task *a, int n, int horizon, char *trace) {
    int rr=0, previous=-1, preemptions=0;
    for (int t=0; t<horizon; ++t) {
        for (int i=0; i<n; ++i) if (t % a[i].period == 0) {
            if (a[i].remaining) ++a[i].missed;
            a[i].release=t; a[i].remaining=a[i].cost; ++a[i].released;
        }
        int pick=-1;
        for (int k=0; k<n; ++k) {
            int i=(rr+k)%n;
            if (a[i].remaining && (pick<0 || a[i].prio<a[pick].prio)) pick=i;
        }
        if (pick<0) { if(trace) trace[t]='.'; previous=-1; continue; }
        if (previous>=0 && previous!=pick && a[previous].remaining &&
            a[pick].prio<a[previous].prio) ++preemptions;
        if(trace) trace[t]=(char)('a'+pick);
        --a[pick].remaining; ++a[pick].ticks;
        if (!a[pick].remaining) {
            int response=t+1-a[pick].release;
            if(response>a[pick].max_response) a[pick].max_response=response;
            ++a[pick].finished;
        }
        rr=(pick+1)%n; /* one tick slice, not run-to-completion */
        previous=a[pick].remaining ? pick : -1;
    }
    /* Fixtures end on a common deadline. */
    for(int i=0;i<n;++i) if(a[i].remaining) ++a[i].missed;
    if(trace) trace[horizon]='\0';
    return preemptions;
}
static int check(int condition,const char *name) {
    if(!condition) fprintf(stderr,"FAIL: %s\n",name);
    return condition;
}
int main(void) {
    Task normal[3]={{.prio=1,.period=10,.cost=3},
                    {.prio=2,.period=20,.cost=5},
                    {.prio=3,.period=40,.cost=8}};
    char trace[641]; int preemptions=simulate(normal,3,640,trace),ok=1;
    /* Independent RTA: R_i=C_i+sum ceil(R_i/T_j)*C_j.
     * A=3; B=5+3=8; C: 8 ->16 ->19 ->19. */
    const int response[]={3,8,19},jobs[]={64,32,16};
    for(int i=0;i<3;++i) {
        printf("%c response=%d completed=%d missed=%d\n",'A'+i,
               normal[i].max_response,normal[i].finished,normal[i].missed);
        ok &= check(normal[i].max_response==response[i],"independent RTA");
        ok &= check(normal[i].finished==jobs[i] && !normal[i].missed,"all jobs");
    }
    printf("trace[0:40]=%.40s\npreemptions=%d\n",trace,preemptions);
    ok &= check(preemptions==16,"preemption of unfinished job");
    ok &= check(normal[0].ticks+normal[1].ticks+normal[2].ticks==480,"CPU accounting");
    Task equal[2]={{.prio=1,.period=10,.cost=5},{.prio=1,.period=10,.cost=5}};
    char rr[11]; simulate(equal,2,10,rr);
    ok &= check(strcmp(rr,"ababababab")==0,"one-tick round robin");
    printf("round_robin=%s\n",rr);
    Task over[3]={{.prio=1,.period=10,.cost=9},{.prio=2,.period=20,.cost=5},
                  {.prio=3,.period=40,.cost=8}};
    simulate(over,3,40,NULL);
    ok &= check(over[0].finished==4 && over[1].missed==2 && over[2].missed==1,"overload");
    for(int i=0;i<3;++i)
        ok &= check(over[i].released==over[i].finished+over[i].missed,"no silent loss");
    printf("overload_misses=%d/%d/%d (drop at deadline)\n",over[0].missed,over[1].missed,over[2].missed);
    puts(ok ? "RESULT: PASS" : "RESULT: FAIL"); return !ok;
}

/* m01_frontback.c —— 前后台轮询 vs RTOS：响应抖动的来源（Cortex-M3）。
 * 用 DWT 周期计数器当硬件秒表，量化“慢任务阻塞快任务”的代价。 */
#include <stdint.h>
#include "rtos_cm.h"
#include "rtos_api.h"

#define DEMCR      (*(volatile uint32_t *)0xE000EDFCu)   /* 调试异常控制：bit24 = CYCCNT 使能 */
#define DWT_CYCCNT (*(volatile uint32_t *)0xE0001004u)   /* 周期计数器 */

void m01_cycles_on(void) { DEMCR |= (1u << 24); DWT_CYCCNT = 0u; }

volatile uint32_t g_fast_period;   /* 快任务两次被服务之间的间隔（周期） */

/* 前后台：快任务与慢任务挤在同一个循环里，慢任务直接把快任务的响应周期拉长 */
void m01_superloop(void) {
    for (;;) {
        uint32_t t0 = DWT_CYCCNT;
        g_fast_period = DWT_CYCCNT - t0;          /* 快任务：应立即处理 */
        uint32_t t1 = DWT_CYCCNT;
        while ((DWT_CYCCNT - t1) < 72000u) { }    /* 慢任务：约 1ms@72MHz 的阻塞 */
    }
}

/* RTOS：快任务独立调度，响应周期不再被慢任务决定 */
static void m01_fast_task(void *arg) {
    (void)arg;
    for (;;) { vTaskDelay(pdMS_TO_TICKS(1)); }
}
void m01_start(void) {
    TaskHandle_t h = 0;
    (void)xTaskCreate(m01_fast_task, "fast", 256u, 0, 2u, &h);
}

/* esp_m01_task_cost.c —— 一个 RTOS 任务的 RAM 成本（ESP32 / XTensa）。
 * 每个任务有独立栈与 TCB；新建任务消耗的堆，就是“多任务”的价格。 */
#include <stdint.h>
#include "esp_idf_api.h"
#include "rtos_api.h"

static void idle_task(void *arg) {
    (void)arg;
    for (;;) { vTaskDelay(1); }
}

/* 返回新建一个 2048 字节栈任务所消耗的堆字节数（含 TCB 与本册内存分配开销） */
uint32_t esp_m01_task_cost(void) {
    uint32_t before = esp_get_free_heap_size();
    TaskHandle_t h = 0;
    (void)xTaskCreate(idle_task, "cost", 2048u, 0, 1u, &h);
    return before - esp_get_free_heap_size();
}

