/* m02_pendsv.c —— 上下文切换发生在 PendSV（Cortex-M3）。
 * 关键点：PendSV 设为最低优先级，保证所有中断处理完后才切换；
 * 硬件已自动压栈 r0-r3/r12/lr/pc/xPSR，端口层只需保存 r4-r11 并切换 PSP。 */
#include <stdint.h>
#include "rtos_cm.h"

typedef struct { uint32_t *sp; } tcb_t;    /* 这里只留栈指针，够讲清切换 */
tcb_t * volatile pxCurrent = 0;            /* 当前任务 */
tcb_t * volatile pxNext    = 0;            /* 下一个任务 */

__attribute__((naked)) void PendSV_Handler(void) {
    __asm volatile(
        ".syntax unified\n"
        "mrs   r0, psp\n"
        "isb\n"
        "stmdb r0!, {r4-r11}\n"        /* 保存被调者保存寄存器 */
        "ldr   r1, =pxCurrent\n"
        "ldr   r2, [r1]\n"
        "str   r0, [r2]\n"             /* pxCurrent->sp = r0 */
        "ldr   r3, =pxNext\n"
        "ldr   r2, [r3]\n"
        "str   r2, [r1]\n"             /* pxCurrent = pxNext */
        "ldr   r0, [r2]\n"             /* r0 = pxNext->sp */
        "ldmia r0!, {r4-r11}\n"
        "msr   psp, r0\n"
        "isb\n"
        "bx    lr\n");
}

/* SysTick 每 tick 选出下一个任务，然后挂起 PendSV 让切换在最低优先级发生 */
void SysTick_Handler(void) {
    pxNext = pxCurrent;
    cm_pend_pendsv();
}

/* esp_m02_dualcore.c —— 双核：把任务固定到指定核（ESP32 / Xtensa LX6）。
 * ESP32 有 2 个核，xTaskCreatePinnedToCore 的最后参数就是亲和核。 */
#include "esp_idf_api.h"
#include "rtos_api.h"

static void worker(void *arg) {
    (void)arg;
    for (;;) { vTaskDelay(pdMS_TO_TICKS(10)); }
}

void esp_m02_pin_cores(void) {
    TaskHandle_t a = 0, b = 0;
    (void)xTaskCreatePinnedToCore(worker, "acq",  4096u, 0, 3u, &a, 0);  /* 核 0：采集 */
    (void)xTaskCreatePinnedToCore(worker, "link", 4096u, 0, 3u, &b, 1);  /* 核 1：通信 */
}

/* 当前任务运行在哪个核（用于确认亲和是否生效） */
BaseType_t esp_m02_where(void) { return xPortGetCoreID(); }

/* h7_m02_fpu.c —— Cortex-M7 的 FPU 上下文（lazy stacking）。
 * 只有真正用过 FPU 的任务才需要保存 S0-S15；端口层按需 vpush/vpop，
 * 不用浮点的任务不为 FPU 付切换成本。 */
#include <stdint.h>
#include "rtos_cm.h"

volatile uint32_t h7_fpu_ready = 0u;

void h7_fpu_init(void) {
    (*(volatile uint32_t *)0xE000ED88u) |= (0xFu << 20);   /* CPACR：使能 CP10/CP11 */
    cm_dsb();
    cm_isb();
    h7_fpu_ready = 1u;
}

void h7_fpu_context_save(void)    { cm_fpu_save(); }
void h7_fpu_context_restore(void) { cm_fpu_restore(); }

/* host_sync.c —— 优先级反转与优先级继承的定量模型（主机可运行）。
 *
 * 场景（经典的三任务反转）：低优先级 L 先拿到互斥量，进入临界区；
 * 中优先级 M 就绪后不停抢占 L；高优先级 H 随后也要这把锁，于是被卡在 L 后面。
 *   · 关闭优先级继承：M 一直霸占 CPU，L 无法推进，H 被“无关的” M 拖住 —— 无界反转。
 *   · 打开优先级继承：H 阻塞在锁上时，L 临时继承 H 的优先级，立刻抢回 CPU 完成临界区，
 *     H 很快拿到锁 —— 反转被“限制在一个临界区以内”。
 *
 * 模型是逐 tick 的固定优先级调度；数字来自本程序真实运行，不是估算。
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_sync.c -o host_sync && ./host_sync
 */
#include <stdio.h>
#include <string.h>

#define T_MAX 200

enum { ST_OFF = 0, ST_READY, ST_DONE };
typedef struct {
    const char *name;
    int base_prio;   /* 越小越紧急 */
    int releases_at;
    int work;        /* 还需执行的 tick */
    int needs_mutex; /* 是否要拿互斥量 */
    int state;
    int blocked;     /* 阻塞在互斥量上 */
    int holds_mutex;
} task_t;

static int g_inversion, g_release_tick, g_acquire_tick;

static int run(int use_pi) {
    task_t T[3] = {
        {"L_low",  3, 0, 6, 1, ST_READY, 0, 0},
        {"M_mid",  2, 1, 20, 0, ST_OFF,   0, 0},
        {"H_high", 1, 2, 1, 1, ST_OFF,   0, 0},
    };
    int locked = 0, owner = -1;   /* 互斥量 */
    int t, acquire = -1;

    for (t = 0; t < T_MAX; t++) {
        int i;
        /* 释放事件 */
        for (i = 0; i < 3; i++)
            if (t == T[i].releases_at) T[i].state = ST_READY;

        /* L 在 t=0 先拿到锁（它是唯一在 t=0 就绪的任务） */
        if (t == 0) { locked = 1; owner = 0; T[0].holds_mutex = 1; }

        /* H 尝试拿锁 */
        if (T[2].state == ST_READY && T[2].needs_mutex && !T[2].holds_mutex) {
            if (!locked) { locked = 1; owner = 2; T[2].holds_mutex = 1; acquire = t; }
            else T[2].blocked = 1;
        }
        /* 锁被释放：让阻塞的等待者下一 tick 能再次尝试 */
        if (!locked) T[2].blocked = 0;

        /* 计算有效优先级：持锁者若有等待者，继承其中最高的（数值最小的）优先级 */
        int eff[3];
        for (i = 0; i < 3; i++) eff[i] = T[i].base_prio;
        if (use_pi && locked && owner >= 0) {
            for (i = 0; i < 3; i++)
                if (T[i].blocked && T[i].base_prio < eff[owner]) eff[owner] = T[i].base_prio;
        }

        /* 选择就绪、未完成、未阻塞、且有效优先级最高的任务 */
        int pick = -1;
        for (i = 0; i < 3; i++) {
            if (T[i].state != ST_READY || T[i].work <= 0 || T[i].blocked) continue;
            if (pick < 0 || eff[i] < eff[pick]) pick = i;
        }
        if (pick < 0) continue;
        T[pick].work--;

        if (T[pick].work == 0) {
            if (T[pick].holds_mutex) { locked = 0; owner = -1; T[pick].holds_mutex = 0; }
            T[pick].state = ST_DONE;
        }
    }
    g_release_tick = 2;                 /* H 在 t=2 就绪并开始等待 */
    g_acquire_tick = acquire;
    g_inversion = acquire - g_release_tick;
    return g_inversion;
}

int main(void) {
    int no_pi = run(0);
    printf("关闭优先级继承：H 从 t=2 等到 t=%d 拿到锁，反转=%d tick\n", g_acquire_tick, no_pi);
    int with_pi = run(1);
    printf("开启优先级继承：H 从 t=2 等到 t=%d 拿到锁，反转=%d tick\n", g_acquire_tick, with_pi);

    int ok = 1;
    if (!(no_pi > 15)) ok = 0;          /* 无界：被中优先级任务长时间拖住 */
    if (!(with_pi <= 6)) ok = 0;        /* 有界：约等于一个临界区（6 tick） */
    if (!(with_pi < no_pi)) ok = 0;
    printf("\n结论：优先级继承把反转从 %d tick 限制到 %d tick（临界区本身 6 tick）。\n", no_pi, with_pi);
    printf("%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m03_mutex.c —— 互斥量：保护临界资源并在阻塞时继承优先级（Cortex-M3）。
 * 互斥量 ≠ 二值信号量：它带所有权，configUSE_MUTEXES=1 时启用优先级继承。 */
#include "rtos_api.h"

static SemaphoreHandle_t g_mtx;

static void sensor_write(void *arg) {
    (void)arg;
    for (;;) {
        if (xSemaphoreTake(g_mtx, pdMS_TO_TICKS(50)) == pdTRUE) {
            /* 临界区：读写共享缓存，越短越好 */
            xSemaphoreGive(g_mtx);
        } else {
            /* 拿不到锁不能死等：超时后降级或重试 */
        }
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}

void m03_create(void) {
    g_mtx = xSemaphoreCreateMutex();
    (void)xTaskCreate(sensor_write, "sensor", 256u, 0, 3u, 0);
}

/* esp_m03_critical.c —— 双核临界区必须用 portMUX（ESP32 / Xtensa）。
 * 单核只关中断就够；双核还要阻止另一个核同时进入，所以用 portMUX_TYPE。 */
#include "esp_idf_api.h"

static portMUX_TYPE g_mux = portMUX_INITIALIZER_UNLOCKED;
static volatile int g_shared = 0;

void esp_shared_bump(void) {
    portENTER_CRITICAL(&g_mux);
    g_shared++;                       /* 临界区：本核不被调度打断，且另一个核被挡在自旋锁外 */
    portEXIT_CRITICAL(&g_mux);
}

int esp_shared_read(void) {
    int v;
    portENTER_CRITICAL(&g_mux);
    v = g_shared;
    portEXIT_CRITICAL(&g_mux);
    return v;
}

/* h7_m03_recursive.c —— 递归互斥量（STM32H7 / Cortex-M7）。
 * 同一任务可重复 take，必须等量 give；适合“已持锁的函数又调用要锁的函数”。 */
#include "rtos_api.h"

static SemaphoreHandle_t g_rec;

static void inner(void) {
    (void)xSemaphoreTakeRecursive(g_rec, portMAX_DELAY);
    /* 需要同一把锁的内层操作 */
    (void)xSemaphoreGiveRecursive(g_rec);
}

static void outer(void *arg) {
    (void)arg;
    for (;;) {
        (void)xSemaphoreTakeRecursive(g_rec, portMAX_DELAY);
        inner();                               /* 再次获取同一把锁，计数 +1，不会自锁 */
        (void)xSemaphoreGiveRecursive(g_rec);  /* 计数归零才真正释放 */
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

void h7_m03_create(void) {
    g_rec = xSemaphoreCreateRecursiveMutex();
    (void)xTaskCreate(outer, "outer", 256u, 0, 3u, 0);
}

/* host_queue.c —— 队列 / 事件组的语义模型（主机可运行）。
 *
 * 覆盖 RTOS 队列最容易被想当然的三件事：
 *   ① 拷贝语义：入队的是“值”，不是指针；之后改原变量不影响队列里的副本。
 *   ② 满/空边界：满时 send 返回失败（不是覆盖）；空时 recv 返回失败。
 *   ③ FromISR 唤醒：中断里 send，只有在“有更高优先级任务在等”时才设置
 *      xHigherPriorityTaskWoken，据此决定是否 portYIELD_FROM_ISR。
 *   ④ 事件组：按位与/或等待与超时。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_queue.c -o host_queue && ./host_queue
 */
#include <stdio.h>

#define QCAP 4
typedef struct { int buf[QCAP]; int head, tail, count; } queue_t;

static void q_init(queue_t *q) { q->head = q->tail = q->count = 0; }
static int  q_send(queue_t *q, int v) {
    if (q->count == QCAP) return 0;               /* 满：拒绝，不覆盖 */
    q->buf[q->tail] = v; q->tail = (q->tail + 1) % QCAP; q->count++; return 1;
}
static int  q_recv(queue_t *q, int *v) {
    if (q->count == 0) return 0;                  /* 空：失败 */
    *v = q->buf[q->head]; q->head = (q->head + 1) % QCAP; q->count--; return 1;
}
/* 中断上下文版本：receiver_waiting 表示是否有更高优先级任务正阻塞在“收”上 */
static int  q_send_from_isr(queue_t *q, int v, int receiver_waiting, int *higher_woken) {
    *higher_woken = 0;
    if (q->count == QCAP) return 0;
    q_send(q, v);
    if (receiver_waiting) *higher_woken = 1;      /* 唤醒后需要 portYIELD_FROM_ISR */
    return 1;
}

/* 事件组：32 位标志 + 等待/超时 */
typedef struct { unsigned bits; } evt_t;
static void evt_set(evt_t *e, unsigned mask) { e->bits |= mask; }
static void evt_clear(evt_t *e, unsigned mask) { e->bits &= ~mask; }
/* 返回 1 表示满足（所有 clear_on_exit 位都置位），0 表示超时 */
static int evt_wait(evt_t *e, unsigned mask, int timeout_ticks, int *waited) {
    int t;
    for (t = 0; t <= timeout_ticks; t++) {
        if ((e->bits & mask) == mask) { *waited = t; return 1; }
    }
    *waited = timeout_ticks; return 0;
}

int main(void) {
    queue_t q; int v, ok = 1;

    q_init(&q);
    /* ① 拷贝语义 */
    int src = 100;
    q_send(&q, src);
    src = 999;                                     /* 改原变量 */
    q_recv(&q, &v);
    printf("拷贝语义：入队 100 后改原变量为 999，出队得到 %d\n", v);
    if (v != 100) ok = 0;

    /* ② 满/空边界 */
    q_init(&q);
    for (int i = 1; i <= QCAP; i++) if (!q_send(&q, i)) ok = 0;
    printf("满队列：已装 %d 项，再 send 返回 %s\n", QCAP, q_send(&q, 99) ? "成功" : "失败(正确)");
    if (q_send(&q, 99)) ok = 0;

    q_recv(&q, &v); q_recv(&q, &v);                /* 取走 1、2 */
    q_send(&q, 5); q_send(&q, 6);                  /* 空出两格再入 5、6 */
    int seq[6], n = 0;
    while (q_recv(&q, &v)) seq[n++] = v;
    printf("FIFO 顺序：");
    for (int i = 0; i < n; i++) printf("%d%s", seq[i], i + 1 < n ? "," : "");
    printf(" (期望 3,4,5,6)\n");
    if (!(n == 4 && seq[0] == 3 && seq[1] == 4 && seq[2] == 5 && seq[3] == 6)) ok = 0;

    /* ③ FromISR 唤醒标志 */
    q_init(&q);
    int woken = -1;
    q_send_from_isr(&q, 7, 0, &woken);
    printf("FromISR：无等待者 → higher_woken=%d (期望 0)\n", woken);
    if (woken != 0) ok = 0;
    q_send_from_isr(&q, 8, 1, &woken);
    printf("FromISR：有高优先级等待者 → higher_woken=%d (期望 1)\n", woken);
    if (woken != 1) ok = 0;

    /* ④ 事件组 */
    evt_t e = {0};
    evt_set(&e, 0x1);
    evt_set(&e, 0x4);
    int waited = 0;
    int r = evt_wait(&e, 0x5, 10, &waited);
    printf("事件组：等待 0x5 → %s，等了 %d tick\n", r ? "满足" : "超时", waited);
    if (!(r == 1 && waited == 0)) ok = 0;
    evt_clear(&e, 0x1);
    if ((e.bits & 0x1) != 0) ok = 0;
    r = evt_wait(&e, 0x2, 5, &waited);
    printf("事件组：等待未置位的 0x2 → %s，等了 %d tick\n", r ? "满足" : "超时", waited);
    if (!(r == 0 && waited == 5)) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m04_queue_isr.c —— 队列按值拷贝 + 中断里入队（Cortex-M3）。
 * 中断只做“搬数据 + 设唤醒标志”；FromISR 后按标志决定是否 portYIELD_FROM_ISR。 */
#include <stdint.h>
#include "rtos_api.h"

typedef struct { uint16_t adc; uint32_t tick; } sample_t;
static QueueHandle_t g_q;

void m04_uart_isr(void) {
    sample_t s;
    BaseType_t woken = pdFALSE;
    s.adc  = 0x0FFFu;                     /* 从外设寄存器取样本 */
    s.tick = xTaskGetTickCount();
    (void)xQueueSendFromISR(g_q, &s, &woken);
    portYIELD_FROM_ISR(woken);            /* 唤醒了更高优先级任务就立刻切换 */
}

static void consumer(void *arg) {
    sample_t s;
    (void)arg;
    for (;;) {
        if (xQueueReceive(g_q, &s, portMAX_DELAY) == pdTRUE) {
            /* 处理样本；队列已拷贝，s 是安全副本 */
        }
    }
}

void m04_create(void) {
    g_q = xQueueCreate(16u, (uint32_t)sizeof(sample_t));
    (void)xTaskCreate(consumer, "cons", 256u, 0, 4u, 0);
}

/* esp_m04_stream.c —— 流缓冲：字节流、无消息边界（ESP32 / Xtensa）。
 * 适合 ISR/驱动与任务之间批量搬运字节，读端按“有多少读多少”。 */
#include <stdint.h>
#include "esp_idf_api.h"
#include "rtos_api.h"

static StreamBufferHandle_t g_sb;
static volatile uint8_t g_dma[64];

void esp_dma_done_isr(void) {
    (void)xStreamBufferSend(g_sb, (const void *)g_dma, (size_t)sizeof(g_dma), 0u);
}

static void parser(void *arg) {
    uint8_t buf[32];
    (void)arg;
    for (;;) {
        size_t n = xStreamBufferReceive(g_sb, buf, sizeof(buf), portMAX_DELAY);
        if (n == 0u) { continue; }
        /* 解析 buf[0..n) */
    }
}

void esp_m04_create(void) {
    g_sb = xStreamBufferCreate(256u, 1u);   /* 容量 256 字节，触发水位 1 */
    (void)xTaskCreate(parser, "parse", 3072u, 0, 5u, 0);
}

/* h7_m04_eventgroup.c —— 事件组：一个任务等待多个事件同时满足（STM32H7）。
 * 比“多个信号量”更省对象，也便于表达“全部就绪才开始”。 */
#include <stdint.h>
#include "rtos_api.h"

#define EVT_NET  (1u << 0)
#define EVT_SENS (1u << 1)
#define EVT_CFG  (1u << 2)
static EventGroupHandle_t g_eg;

static void app(void *arg) {
    (void)arg;
    const EventBits_t need = EVT_NET | EVT_SENS | EVT_CFG;
    for (;;) {
        EventBits_t got = xEventGroupWaitBits(g_eg, need, pdFALSE, pdTRUE, pdMS_TO_TICKS(5000));
        if ((got & need) == need) {
            /* 三个前置都就绪：进入主流程 */
        } else {
            /* 超时：降级或重试 */
        }
    }
}

void h7_m04_create(void) {
    g_eg = xEventGroupCreate();
    (void)xTaskCreate(app, "app", 256u, 0, 3u, 0);
}

/* m05_fromisr.c —— 中断与 RTOS 的边界（Cortex-M3）。
 * ISR 只做两件事：搬走数据、唤醒任务。临界区用 BASEPRI 只屏蔽到阈值，
 * 比阈值更紧急的中断仍可响应，实时性比“关总中断”好。 */
#include <stdint.h>
#include "rtos_cm.h"
#include "rtos_api.h"

static QueueHandle_t g_q;

void m05_isr_enqueue(uint16_t sample) {
    BaseType_t woken = pdFALSE;
    (void)xQueueSendFromISR(g_q, &sample, &woken);
    portYIELD_FROM_ISR(woken);
}

/* 任务里的短临界区：读一个共享寄存器 */
uint32_t m05_read_shared(volatile uint32_t *p) {
    uint32_t saved = cm_enter_critical();
    uint32_t v = *p;
    cm_exit_critical(saved);
    return v;
}

void m05_create(void) {
    g_q = xQueueCreate(8u, sizeof(uint16_t));
}

