 * CFSR/HFSR/MMFAR/BFAR 是内核调试寄存器，能把“跑飞”定位到具体原因与地址。 */
#include <stdint.h>

#define CFSR  (*(volatile uint32_t *)0xE000ED28u)   /* 可配置错误状态 */
#define HFSR  (*(volatile uint32_t *)0xE000ED2Cu)   /* 硬错误状态 */
#define MMFAR (*(volatile uint32_t *)0xE000ED34u)   /* MemManage 出错地址 */
#define BFAR  (*(volatile uint32_t *)0xE000ED38u)   /* BusFault 出错地址 */

volatile uint32_t g_fault[4];

void HardFault_Handler(void) {
    g_fault[0] = CFSR;
    g_fault[1] = HFSR;
    g_fault[2] = MMFAR;
    g_fault[3] = BFAR;
    for (;;) { }        /* 断在这里，用调试器读 g_fault */
}

/* m09_rtthread.c —— RT-Thread 侧写法（对象化 API）。
 * 线程有独立栈，信号量/互斥量都是内核对象，带名字便于 shell(msh) 调试。 */
#include "rtthread_api.h"

static rt_sem_t g_ready;

static void worker(void *param) {
    (void)param;
    for (;;) {
        rt_sem_take(g_ready, RT_WAITING_FOREVER);
        /* 事件处理 */
    }
}

void m09_rtthread_start(void) {
    g_ready = rt_sem_create("ready", 0, 0);
    rt_thread_t t = rt_thread_create("worker", worker, 0, 2048u, 10u, 20u);
    if (t) { (void)rt_thread_startup(t); }
}

