/* esp_m10_pipeline.c —— 双核流水线（ESP32 / Xtensa）。
 * 采集固定到核 0，通信固定到核 1，减少彼此干扰；中间用队列交接。 */
#include <stdint.h>
#include "esp_idf_api.h"
#include "rtos_api.h"

static QueueHandle_t g_q;

static void acq(void *arg) {
    (void)arg;
    for (;;) {
        int v = 0;
        (void)xQueueSend(g_q, &v, pdMS_TO_TICKS(5));
        vTaskDelay(pdMS_TO_TICKS(10));
    }
}
static void link(void *arg) {
    int v;
    (void)arg;
    for (;;) {
        if (xQueueReceive(g_q, &v, portMAX_DELAY) == pdTRUE) { /* 上报 */ }
    }
}
void esp_m10_start(void) {
    TaskHandle_t a = 0, b = 0;
    g_q = xQueueCreate(16u, (uint32_t)sizeof(int));
    (void)xTaskCreatePinnedToCore(acq,  "acq",  4096u, 0, 4u, &a, 0);
    (void)xTaskCreatePinnedToCore(link, "link", 4096u, 0, 3u, &b, 1);
}

/* h7_m10_priority.c —— 优先级分配原则（STM32H7 / Cortex-M7）。
 * 越“靠近截止期、越不能被延迟”的任务优先级越高；共享资源时注意优先级反转。 */
#include "rtos_api.h"

void h7_m10_assign(void) {
    /* 例：控制周期 1ms > 通信 10ms > 显示 100ms */
    (void)xTaskCreate((TaskFunction_t)0, "ctrl", 512u, 0, 5u, 0);
    (void)xTaskCreate((TaskFunction_t)0, "comm", 512u, 0, 3u, 0);
    (void)xTaskCreate((TaskFunction_t)0, "disp", 256u, 0, 1u, 0);
}

/* host_rm.c —— 实时预算与可调度性：利用率界、响应时间分析（主机可运行）。
 *
 *   ① 利用率界 U ≤ n(2^{1/n}-1) 是“充分不必要”：超过它未必不可调度。
 *      本程序用穷举找到一组“U 超过界、但响应时间分析(RTA)仍然可调度”的任务集。
 *   ② 响应时间分析：R_i = C_i + Σ_{j<i} ceil(R_i / T_j)·C_j，迭代到不动点，R_i ≤ T_i 即可调度。
 *   ③ U > 1 一定不可调度。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_rm.c -o host_rm && ./host_rm
 */
#include <stdio.h>
#include <math.h>

static int cdiv(int a, int b) { return (a + b - 1) / b; }

/* 返回最低优先级任务的响应时间；-1 表示某一级不满足截止期 */
static int rta(const int *C, const int *T, int n, int *out_R) {
    for (int i = 0; i < n; i++) {
        int R = C[i], guard = 0;
        for (;;) {
            int nr = C[i];
            for (int j = 0; j < i; j++) nr += cdiv(R, T[j]) * C[j];
            if (nr == R) break;
            R = nr;
            if (++guard > 10000 || R > T[i]) return -1;
        }
        if (R > T[i]) return -1;
        out_R[i] = R;
    }
    return 0;
}

int main(void) {
    int ok = 1, found = 0;
    int C[3], T[3], R[3];

    printf("穷举 n=3（C≤4, T≤12，按周期升序=优先级降序），寻找“U 超界但可调度”的例子：\n");
    for (int c1 = 1; c1 <= 4 && !found; c1++)
    for (int c2 = 1; c2 <= 4 && !found; c2++)
    for (int c3 = 1; c3 <= 4 && !found; c3++)
    for (int t1 = 2; t1 <= 12 && !found; t1++)
    for (int t2 = t1 + 1; t2 <= 12 && !found; t2++)
    for (int t3 = t2 + 1; t3 <= 12 && !found; t3++) {
        C[0]=c1;C[1]=c2;C[2]=c3; T[0]=t1;T[1]=t2;T[2]=t3;
        double U = (double)c1/t1 + (double)c2/t2 + (double)c3/t3;
        double bound = 3.0 * (pow(2.0, 1.0/3.0) - 1.0);
        if (U <= bound || U >= 0.95) continue;
        if (rta(C, T, 3, R) == 0) {
            printf("  找到：C/T = (%d,%d,%d)/(%d,%d,%d)，U=%.4f > 界 %.4f\n",
                   c1, c2, c3, t1, t2, t3, U, bound);
            printf("  响应时间 R = (%d,%d,%d)，均 ≤ 各自周期 → 可调度\n", R[0], R[1], R[2]);
            found = 1;
        }
    }
    if (!found) ok = 0;

    /* 反证：U>1 必然不可调度 */
    int C2[2] = {3, 4}, T2[2] = {4, 5}, R2[2] = {0,0};
    double U2 = 3.0/4.0 + 4.0/5.0;
    int r = rta(C2, T2, 2, R2);
    printf("\nU>1 的例子：(3,4),(4,5) → U=%.2f，RTA 结果=%s（期望不可调度）\n",
           U2, r == 0 ? "可调度" : "不可调度");
    if (U2 > 1.0 && r == 0) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m11_wcet.c —— 用 DWT 周期计数器测 WCET（Cortex-M3）。
 * WCET 关注“最坏一次”，不是平均；要用能覆盖最坏输入/分支的测试。 */
#include <stdint.h>
#include "rtos_cm.h"

#define DEMCR      (*(volatile uint32_t *)0xE000EDFCu)
#define DWT_CYCCNT (*(volatile uint32_t *)0xE0001004u)

volatile uint32_t g_wcet_cycles;

void m11_wcet_on(void) { DEMCR |= (1u << 24); DWT_CYCCNT = 0u; }

void m11_wcet_sample(uint32_t (*job)(void)) {
    uint32_t t0 = DWT_CYCCNT;
    (void)job();
    uint32_t dt = DWT_CYCCNT - t0;
    if (dt > g_wcet_cycles) { g_wcet_cycles = dt; }   /* 取最大，不是平均 */
}

/* esp_m11_rm.c —— 利用率与 RM 界的速查（ESP32 / Xtensa）。
 * 任务按周期升序 = 优先级降序；先算 U=ΣC/T，再对最低优先级做响应时间分析。 */
#include <stdint.h>
#include "rtos_api.h"

/* 例：C/T = (1,2),(1,3),(1,9)，U=0.944 > 界 0.780，但 R=(1,2,6) 均 ≤ 周期 → 可调度 */
void esp_m11_table(void) {
    const uint32_t C[3] = {1u, 1u, 1u};
    const uint32_t T[3] = {2u, 3u, 9u};
    uint32_t u_milli = 0u;
    for (int i = 0; i < 3; i++) { u_milli += (C[i] * 1000u) / T[i]; }
    (void)u_milli;      /* 上板可打印核对：应为 944‰ */
}

/* h7_m11_rm.c —— 响应时间分析（STM32H7 / Cortex-M7）。
 * R_i = C_i + Σ_{j<i} ceil(R_i / T_j)·C_j，迭代到不动点；R_i ≤ T_i 才可调度。 */
#include <stdint.h>

static uint32_t ceil_div(uint32_t a, uint32_t b) { return (a + b - 1u) / b; }

int h7_rm_schedulable(const uint32_t *C, const uint32_t *T, unsigned n) {
    for (unsigned i = 0; i < n; i++) {
        uint32_t R = C[i];
        for (unsigned guard = 0; guard < 10000u; guard++) {
            uint32_t nr = C[i];
            for (unsigned j = 0; j < i; j++) { nr += ceil_div(R, T[j]) * C[j]; }
            if (nr == R) { break; }
            R = nr;
            if (R > T[i]) { return 0; }
        }
        if (R > T[i]) { return 0; }
    }
    return 1;
}

/* host_smp.c —— 多核/并发下的共享计数：丢失更新与自旋锁（主机可运行）。
 *
 * 用真实 C11 原子操作演示两件事：
 *   ① 非原子的“读-改-写”：两个核交错执行时会丢失更新（最终值小于实际自增次数）。
 *   ② 用 atomic_flag 自旋锁或 atomic_fetch_add 保护后，计数严格正确。
 * 模型用“手工交错的步骤”表达两核并发；讨论的是内存序与互斥，不绑定具体指令。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_smp.c -o host_smp && ./host_smp
 */
#include <stdio.h>
#include <stdatomic.h>

int main(void) {
    int ok = 1;

    /* ① 非原子：两核都先读 0，各自 +1 后写回，最终只有 1（丢失一次自增） */
    int counter = 0, a_read, b_read;
    a_read = counter;      /* 核 A 读 */
    b_read = counter;      /* 核 B 读（A 尚未写回） */
    counter = a_read + 1;  /* 核 A 写 */
    counter = b_read + 1;  /* 核 B 写，覆盖了 A 的结果 */
    printf("非原子读改写：期望 2，实际 %d（丢失更新）\n", counter);
    if (counter != 1) ok = 0;

    /* ② atomic_fetch_add：每次自增原子完成，不丢 */
    atomic_int ac = 0;
    atomic_fetch_add(&ac, 1);   /* 核 A */
    atomic_fetch_add(&ac, 1);   /* 核 B */
    printf("atomic_fetch_add：期望 2，实际 %d\n", atomic_load(&ac));
    if (atomic_load(&ac) != 2) ok = 0;

    /* ③ 自旋锁：临界区内 +1，语义上等价于关调度/关中断的短临界区 */
    atomic_flag lock = ATOMIC_FLAG_INIT;
    int guarded = 0;
    for (int i = 0; i < 1000; i++) {
        while (atomic_flag_test_and_set_explicit(&lock, memory_order_acquire)) { /* spin */ }
        guarded++;                                   /* 临界区：只允许一个核进入 */
        atomic_flag_clear_explicit(&lock, memory_order_release);
    }
    printf("自旋锁保护的自增 1000 次：实际 %d\n", guarded);
    if (guarded != 1000) ok = 0;

    /* ④ 内存序对照：relaxed 只保证原子性，不保证跨线程可见顺序 */
    atomic_int seq = 0;
    atomic_store_explicit(&seq, 1, memory_order_relaxed);
    atomic_store_explicit(&seq, 2, memory_order_release);
    printf("release 存储后 relaxed 读 = %d（同线程内可见）\n", atomic_load_explicit(&seq, memory_order_relaxed));
    if (atomic_load_explicit(&seq, memory_order_relaxed) != 2) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m12_lifecycle.c —— 任务生命周期：创建 / 挂起 / 恢复 / 删除（Cortex-M3）。
 * 删除前必须先释放它持有的资源（锁、内存、句柄），否则别的任务会被永久阻塞。 */
#include "rtos_api.h"

static TaskHandle_t g_worker;
static SemaphoreHandle_t g_lock;

static void worker(void *arg) {
    (void)arg;
    for (;;) { vTaskDelay(pdMS_TO_TICKS(100)); }
}

void m12_create(void) {
    g_lock = xSemaphoreCreateMutex();
    (void)xTaskCreate(worker, "worker", 256u, 0, 2u, &g_worker);
}
void m12_stop(void) {
    if (g_worker) { vTaskSuspend(g_worker); }     /* 暂停：保留栈与状态 */
}
void m12_resume(void) {
    if (g_worker) { vTaskResume(g_worker); }
}
void m12_destroy(void) {
    if (g_worker) {
        vTaskDelete(g_worker);                    /* 确保它不再持有 g_lock */
        g_worker = 0;
    }
}

/* esp_m12_smp.c —— SMP 与亲和（ESP32 / Xtensa）。
 * 任务可固定到某个核也可迁移；核间共享数据必须用 spinlock/原子，per-core 数据不要跨核访问。 */
#include <stdint.h>
#include "esp_idf_api.h"
#include "rtos_api.h"

static portMUX_TYPE g_spin = portMUX_INITIALIZER_UNLOCKED;
static volatile uint32_t g_cross;

static void core0_only(void *arg) {
    (void)arg;
    for (;;) {
        portENTER_CRITICAL(&g_spin);
        g_cross++;                      /* 跨核共享：短临界区 + 自旋锁 */
        portEXIT_CRITICAL(&g_spin);
        vTaskDelay(1);
    }
}
void esp_m12_start(void) {
    TaskHandle_t h = 0;
    (void)xTaskCreatePinnedToCore(core0_only, "c0", 4096u, 0, 3u, &h, 0);
}

/* h7_m12_cache.c —— D-Cache 与 DMA 一致性（STM32H7 / Cortex-M7）。
 * DMA/其他核对内存的写入对 CPU 不一定可见：共享缓冲要么放非 cache 区，
 * 要么按 cache line 做 clean/invalidate，并按 line 对齐。 */
#include <stdint.h>

#define ALIGN32 __attribute__((aligned(32)))

static ALIGN32 volatile uint32_t g_dma_buf[16];   /* 32 字节对齐，覆盖一个 cache line */

/* CMSIS 提供这两个函数（此处仅声明，链接时由 CMSIS 提供） */
extern void SCB_CleanDCache_by_Addr(volatile void *addr, int32_t dsize);
extern void SCB_InvalidateDCache_by_Addr(volatile void *addr, int32_t dsize);

void h7_dma_clean(void)      { SCB_CleanDCache_by_Addr((void *)g_dma_buf, (int32_t)sizeof(g_dma_buf)); }
void h7_dma_invalidate(void) { SCB_InvalidateDCache_by_Addr((void *)g_dma_buf, (int32_t)sizeof(g_dma_buf)); }

/* capstone_node_rtos.c —— 贯穿项目骨架：环境采集终端的 RTOS 化（Cortex-M3 示范）。
 * sensor(高) → queue → process(中) → queue → comms(低)；I²C 用互斥量保护，通信任务负责上报与喂狗。 */
#include <stdint.h>
#include "rtos_api.h"
#include "rtos_cm.h"

typedef struct { int16_t t; uint16_t v; } sample_t;
static QueueHandle_t g_raw, g_tx;
static SemaphoreHandle_t g_i2c;

static void sensor_task(void *arg) {
    sample_t s; (void)arg;
    for (;;) {
        if (xSemaphoreTake(g_i2c, pdMS_TO_TICKS(5)) == pdTRUE) {
            s.t = 0; s.v = 0;                              /* 读传感器 */
            (void)xSemaphoreGive(g_i2c);
            (void)xQueueSend(g_raw, &s, pdMS_TO_TICKS(5));
        }
        vTaskDelay(pdMS_TO_TICKS(100));                    /* 100ms 采样周期 */
    }
}
static void process_task(void *arg) {
    sample_t s; (void)arg;
    for (;;) {
        if (xQueueReceive(g_raw, &s, portMAX_DELAY) == pdTRUE) {
            (void)xQueueSend(g_tx, &s, pdMS_TO_TICKS(50));
        }
    }
}
static void comms_task(void *arg) {
    sample_t s; (void)arg;
    for (;;) {
        if (xQueueReceive(g_tx, &s, pdMS_TO_TICKS(1000)) == pdTRUE) {
            /* 上报成功后才喂狗；超时说明链路异常 */
        }
    }
}
void capstone_start(void) {
    g_raw = xQueueCreate(8u, (uint32_t)sizeof(sample_t));
    g_tx  = xQueueCreate(8u, (uint32_t)sizeof(sample_t));
    g_i2c = xSemaphoreCreateMutex();
    (void)xTaskCreate(sensor_task,  "sensor",  512u, 0, 4u, 0);
    (void)xTaskCreate(process_task, "process", 512u, 0, 3u, 0);
    (void)xTaskCreate(comms_task,   "comms",   768u, 0, 2u, 0);
}

/* host_frame.c —— 帧解析状态机：转义、CRC、噪声重同步、序号去重（主机可运行）。
 *
 * 线格式：[SOF=0x7E] 转义后的 body [EOF=0x7F]，body = seq | len | payload | crc16。
 * 转义规则：0x7E/0x7F/0x7D 前插 0x7D，并把原字节异或 0x20。
 * 解析器逐字节喂入，必须做到：
 *   ① 从噪声中重新同步（不因一个坏字节丢掉后面的好帧）；
 *   ② CRC 失败计一次错误并继续；
 *   ③ 重复序号只处理一次（幂等）。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_frame.c -o host_frame && ./host_frame
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define SOF 0x7E
#define EOFB 0x7F
#define ESC 0x7D

static uint16_t crc16(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1);
    }
    return c;
}

/* 构造一帧（含转义），返回字节数 */
static int make_frame(uint8_t seq, const uint8_t *pl, int pln, uint8_t *out) {
    uint8_t body[64]; int bn = 0;
    body[bn++] = seq;
    body[bn++] = (uint8_t)pln;
    memcpy(body + bn, pl, pln); bn += pln;
    uint16_t c = crc16(body, bn);
    body[bn++] = (uint8_t)(c & 0xFF);
    body[bn++] = (uint8_t)(c >> 8);
    int on = 0; out[on++] = SOF;
    for (int i = 0; i < bn; i++) {
        uint8_t b = body[i];
        if (b == SOF || b == EOFB || b == ESC) { out[on++] = ESC; out[on++] = (uint8_t)(b ^ 0x20); }
        else out[on++] = b;
    }
    out[on++] = EOFB;
    return on;
}

typedef struct {
    int state;            /* 0=等待 SOF, 1=收 body, 2=收到 ESC */
    uint8_t body[64]; int blen;
    uint8_t seq; uint8_t payload[32]; int plen;
    int good, crc_err, dup;
    uint8_t seen[4]; int seen_n;    /* 最近 4 个序号，用于去重 */
    uint8_t last_seq, last_payload[32]; int last_plen;   /* 最近“被接受”的帧 */
} parser_t;

static int already_seen(parser_t *P, uint8_t seq) {
    for (int i = 0; i < P->seen_n; i++) if (P->seen[i] == seq) return 1;
    return 0;
}
static void remember(parser_t *P, uint8_t seq) {
    if (P->seen_n < 4) P->seen[P->seen_n++] = seq;
    else { memmove(P->seen, P->seen + 1, 3); P->seen[3] = seq; }
}
/* 返回：1=产出帧, -1=CRC 错误, 0=无事件 */
static int feed(parser_t *P, uint8_t b) {
    if (P->state == 0) { if (b == SOF) { P->state = 1; P->blen = 0; } return 0; }
    if (b == ESC && P->state != 2) { P->state = 2; return 0; }
    if (P->state == 2) { b = (uint8_t)(b ^ 0x20); P->state = 1; }
    if (b == SOF) { P->state = 1; P->blen = 0; return 0; }   /* 中途遇到 SOF：重新开始 */
    if (b == EOFB) {
        P->state = 0;
        if (P->blen < 4) return 0;                            /* 太短：丢弃 */
        int dlen = P->blen - 2;
        if (crc16(P->body, dlen) != (uint16_t)(P->body[dlen] | (P->body[dlen + 1] << 8))) { P->crc_err++; return -1; }
        P->seq = P->body[0];
        P->plen = P->body[1];
        if (P->plen > (int)sizeof(P->payload) || P->plen + 2 != dlen) return 0;
        memcpy(P->payload, P->body + 2, P->plen);
        if (already_seen(P, P->seq)) { P->dup++; return 0; }
        remember(P, P->seq);
        P->last_seq = P->seq;
        P->last_plen = P->plen;
        memcpy(P->last_payload, P->payload, (size_t)P->plen);
        P->good++;
        return 1;
    }
    if (P->blen < (int)sizeof(P->body)) P->body[P->blen++] = b;
    else P->blen = 0;                                         /* 溢出：丢弃 */
    return 0;
}

int main(void) {
    parser_t P; memset(&P, 0, sizeof(P));
    uint8_t f1[64], f2[64], f3[64];
    const uint8_t pa[] = {'a', 'b', 'c'};
    const uint8_t pb[] = {'d', 'e'};
    int n1 = make_frame(1, pa, 3, f1);
    int n2 = make_frame(2, pb, 2, f2);
    int n3 = make_frame(3, pb, 2, f3);
    f2[2] ^= 0x01;                                            /* 破坏第 2 帧 → CRC 失败 */

    int got = 0, ev;
    uint8_t noise[] = {0x11, 0x22, 0x7E, 0x33};               /* 噪声里甚至混入一个 SOF */
    for (unsigned i = 0; i < sizeof(noise); i++) feed(&P, noise[i]);
    for (int i = 0; i < n1; i++) { ev = feed(&P, f1[i]); if (ev == 1) got++; }
    for (int i = 0; i < n2; i++) { ev = feed(&P, f2[i]); if (ev == 1) got++; }
    for (int i = 0; i < n3; i++) { ev = feed(&P, f3[i]); if (ev == 1) got++; }
    for (int i = 0; i < n1; i++) { ev = feed(&P, f1[i]); if (ev == 1) got++; }   /* 重复帧 */

    printf("产出帧=%d（期望 2：第 1、3 帧）  CRC 错误=%d（期望 1）  重复丢弃=%d（期望 1）\n",
           P.good, P.crc_err, P.dup);
    printf("最后被接受的帧：seq=%d payload=%c%c\n", P.last_seq, P.last_payload[0], P.last_payload[1]);

    int ok = 1;
    if (P.good != 2) ok = 0;
    if (P.crc_err != 1) ok = 0;
    if (P.dup != 1) ok = 0;
    if (!(P.last_seq == 3 && P.last_plen == 2 && P.last_payload[0] == 'd')) ok = 0;
    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m01_framing.c —— 设备侧帧解析状态机（Cortex-M3）。
 * SOF(0x7E)…EOF(0x7F)；长度与 CRC 由协议层校验。逐字节喂入，溢出即放弃本帧。 */
#include <stdint.h>
#include "comm_api.h"

typedef struct { uint8_t buf[64]; int n; int in; } fparse_t;

int frame_feed(fparse_t *p, uint8_t b) {
    if (!p->in) { if (b == 0x7E) { p->in = 1; p->n = 0; } return 0; }
    if (b == 0x7F) { p->in = 0; return p->n >= 4 ? 1 : 0; }
    if (p->n < (int)sizeof(p->buf)) p->buf[p->n++] = b;
    else { p->in = 0; }                 /* 溢出：放弃本帧，等下一个 SOF */
    return 0;
}

void uart_rx_task(void *arg) {
    fparse_t fp; uint8_t b; (void)arg;
    fp.in = 0; fp.n = 0;
    for (;;) {
        if (uart_recv(&b, 1u, portMAX_DELAY) == 1) {
            if (frame_feed(&fp, b)) { /* 一帧完整：交给协议层 */ }
        }
    }
}

/* esp_m01_framing.c —— ESP32 侧 UART 收帧（Xtensa）。
 * UART 驱动按字节读，帧头/帧尾驱动状态机；长度与 CRC 交给协议层。 */
#include <stdint.h>
#include "esp_comm.h"
#include "comm_api.h"

void esp_uart_rx_task(void *arg) {
    uint8_t b;
    int in_frame = 0;
    (void)arg;
    for (;;) {
        if (uart_read_bytes(1, &b, 1u, portMAX_DELAY) == 1) {
            if (!in_frame && b == 0x7E) in_frame = 1;
            else if (in_frame && b == 0x7F) in_frame = 0;   /* 帧结束：进入处理 */
        }
    }
}

/* h7_m01_framing.c —— H7 侧批量收帧（Cortex-M7）。
 * 用 DMA + 空闲中断拿到一整块字节，再按帧头切分；比逐字节中断省中断开销。 */
#include <stdint.h>
#include <stddef.h>
#include "comm_api.h"

void h7_uart_rx_full_callback(const uint8_t *buf, size_t n) {
    size_t off = 0;
    while (off < n) {
        if (buf[off] != 0x7E) { off++; continue; }   /* 找帧头 */
        /* 从 off 起解析一帧：长度字段 → CRC 校验 → 提交，失败则 off++ 重同步 */
        break;
    }
}

/* host_crc.c —— 校验和/CRC8/CRC16/CRC32：位运算版与查表版等价性（主机可运行）。
 *
 * 覆盖协议里最常见的三种 CRC 参数模型，并用标准检查值 "123456789" 断言：
 *   CRC-8   (poly 0x07, init 0x00)            → 0xF4
 *   CRC-16/MODBUS (poly 0xA001 反射, init 0xFFFF) → 0x4B37
 *   CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF) → 0x29B1
 *   CRC-32/ISO-HDLC (poly 0xEDB88320 反射)    → 0xCBF43926
 * 同时验证“查表版 == 位运算版”，这是把 CRC 换成查表/硬件前必须先做的对拍。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_crc.c -o host_crc && ./host_crc
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint8_t crc8_bit(const uint8_t *p, int n) {
    uint8_t c = 0x00;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 0x80) ? (uint8_t)((c << 1) ^ 0x07) : (uint8_t)(c << 1);
    }
    return c;
}
static uint16_t crc16_modbus_bit(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1);
    }
    return c;
}
static uint16_t crc16_ccitt_bit(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) {
        c ^= (uint16_t)(p[i] << 8);
        for (int b = 0; b < 8; b++) c = (c & 0x8000) ? (uint16_t)((c << 1) ^ 0x1021) : (uint16_t)(c << 1);
    }
    return c;
}
static uint32_t crc32_bit(const uint8_t *p, int n) {
    uint32_t c = 0xFFFFFFFFu;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 1) ? ((c >> 1) ^ 0xEDB88320u) : (c >> 1);
    }
    return c ^ 0xFFFFFFFFu;
}

/* 查表版：先建表，再按字节喂入 */
static uint16_t tbl16[256];
static void build_table16(void) {
    for (int i = 0; i < 256; i++) {
        uint16_t c = (uint16_t)i;
        for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1);
        tbl16[i] = c;
    }
}
static uint16_t crc16_modbus_tab(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) c = (uint16_t)((c >> 8) ^ tbl16[(c ^ p[i]) & 0xFF]);
    return c;
}

int main(void) {
    const char *s = "123456789";
    const uint8_t *p = (const uint8_t *)s;
    int n = (int)strlen(s);
    int ok = 1;

    uint8_t c8 = crc8_bit(p, n);
    uint16_t m = crc16_modbus_bit(p, n);
    uint16_t cc = crc16_ccitt_bit(p, n);
    uint32_t c32 = crc32_bit(p, n);
    printf("检查值 \"%s\"：CRC8=0x%02X  CRC16/MODBUS=0x%04X  CRC16/CCITT=0x%04X  CRC32=0x%08X\n",
           s, c8, m, cc, c32);
    if (c8 != 0xF4) ok = 0;
    if (m != 0x4B37) ok = 0;
    if (cc != 0x29B1) ok = 0;
    if (c32 != 0xCBF43926u) ok = 0;

    build_table16();
    uint16_t mt = crc16_modbus_tab(p, n);
    printf("查表版 CRC16/MODBUS=0x%04X（应与位运算版一致）\n", mt);
    if (mt != m) ok = 0;

    /* 单比特错误必须改变 CRC（否则检错能力有问题） */
    uint8_t bad[9];
    memcpy(bad, s, 9);
    bad[3] ^= 0x01;
    printf("翻转 1 位后 CRC16/MODBUS=0x%04X（应与原始不同）\n", crc16_modbus_bit(bad, n));
    if (crc16_modbus_bit(bad, n) == m) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m02_crc.c —— 硬件 CRC 与软件 CRC 并用（Cortex-M3）。
 * 硬件 CRC32：写数据寄存器，读结果；Modbus 用软件 CRC16（参数模型固定）。 */
#include <stdint.h>
#include "comm_api.h"
#include "stm32_comm.h"

uint32_t hw_crc32(const uint8_t *p, uint32_t n) {
    CRC_CR = 1u;                         /* RESET：清初值寄存器 */
    for (uint32_t i = 0; i < n; i++) { CRC_DR = p[i]; }
    return CRC_DR;
}

uint16_t frame_crc16(const uint8_t *p, uint32_t n) { return crc16_modbus(p, n); }

/* esp_m02_crc.c —— ESP32 侧校验（Xtensa）。
 * Modbus 用软件 CRC16（查表）；固件镜像用 CRC32。二者参数模型必须与对端一致。 */
#include <stdint.h>
#include "esp_comm.h"
#include "comm_api.h"

uint16_t esp_modbus_crc(const uint8_t *p, size_t n) { return crc16_modbus(p, n); }
uint32_t esp_image_crc(const uint8_t *p, size_t n)  { return crc32_ieee(p, n); }

/* h7_m02_crc.c —— H7 侧校验（Cortex-M7）。
 * 除软件 CRC16 外，镜像完整性用 CRC32；若用硬件 CRC 单元，注意它是共享外设，
 * 多任务/多核并发使用要加锁，且改写前必须复位初值。 */
#include <stdint.h>
#include "comm_api.h"

uint16_t h7_frame_crc16(const uint8_t *p, size_t n) { return crc16_modbus(p, n); }
uint32_t h7_image_crc32(const uint8_t *p, size_t n) { return crc32_ieee(p, n); }

/* host_modbus.c —— Modbus RTU 帧构造/解析与 CRC 自洽（主机可运行）。
 *
 * Modbus RTU 的不变量：把 CRC 也算进去后，整帧再算一遍 CRC16/MODBUS 必须等于 0。
 * 本程序据此校验请求帧，并解析一条正常响应与一条异常响应。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_modbus.c -o host_modbus && ./host_modbus
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint16_t crc16(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1);
    }
    return c;
}
static int append_crc(uint8_t *f, int n) {
    uint16_t c = crc16(f, n);
    f[n++] = (uint8_t)(c & 0xFF);        /* Modbus：低字节在前 */
    f[n++] = (uint8_t)(c >> 8);
    return n;
}
static void print_hex(const char *tag, const uint8_t *p, int n) {
    printf("%s", tag);
    for (int i = 0; i < n; i++) printf("%02X%s", p[i], i + 1 < n ? " " : "");
    printf("\n");
}

int main(void) {
    int ok = 1, n;
    uint8_t req[16];

    /* 请求：从站 1，功能 0x03（读保持寄存器），起始 0x0000，数量 0x000A */
    n = 0;
    req[n++] = 0x01; req[n++] = 0x03;
    req[n++] = 0x00; req[n++] = 0x00;
    req[n++] = 0x00; req[n++] = 0x0A;
    n = append_crc(req, n);
    print_hex("请求帧: ", req, n);
    printf("整帧 CRC 自洽（含 CRC 再算=0）：%s\n", crc16(req, n) == 0 ? "是" : "否");
    if (n != 8 || crc16(req, n) != 0) ok = 0;

    /* 正常响应：01 03 04 AA BB CC DD + CRC → 两个 16 位寄存器 0xAABB、0xCCDD（线上大端） */
    uint8_t resp[16]; int rn = 0;
    resp[rn++] = 0x01; resp[rn++] = 0x03; resp[rn++] = 0x04;
    resp[rn++] = 0xAA; resp[rn++] = 0xBB; resp[rn++] = 0xCC; resp[rn++] = 0xDD;
    rn = append_crc(resp, rn);
    print_hex("响应帧: ", resp, rn);
    if (crc16(resp, rn) != 0) ok = 0;
    int bc = resp[2];
    uint16_t v0 = (uint16_t)((resp[3] << 8) | resp[4]);
    uint16_t v1 = (uint16_t)((resp[5] << 8) | resp[6]);
    printf("字节数=%d 寄存器0=0x%04X 寄存器1=0x%04X（期望 0xAABB / 0xCCDD）\n", bc, v0, v1);
    if (!(bc == 4 && v0 == 0xAABB && v1 == 0xCCDD)) ok = 0;

    /* 异常响应：功能码最高位置 1，异常码 0x02（非法数据地址） */
    uint8_t exc[8]; int en = 0;
    exc[en++] = 0x01; exc[en++] = 0x83; exc[en++] = 0x02;
    en = append_crc(exc, en);
    print_hex("异常帧: ", exc, en);
    int is_exc = (exc[1] & 0x80) != 0;
    printf("是否异常响应=%s 异常码=0x%02X（期望异常、0x02）\n", is_exc ? "是" : "否", exc[2]);
    if (!(is_exc && exc[2] == 0x02)) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m03_modbus.c —— 组 Modbus RTU 请求并发送（Cortex-M3）。
 * 帧：addr|func|reg_hi|reg_lo|qty_hi|qty_lo|crc_lo|crc_hi。 */
#include <stdint.h>
#include "comm_api.h"

int modbus_read_holding(uint8_t addr, uint16_t reg, uint16_t qty) {
    uint8_t f[8];
    f[0] = addr;
    f[1] = 0x03;                         /* 功能码：读保持寄存器 */
    f[2] = (uint8_t)(reg >> 8);
    f[3] = (uint8_t)reg;
    f[4] = (uint8_t)(qty >> 8);
    f[5] = (uint8_t)qty;
    uint16_t c = crc16_modbus(f, 6);
    f[6] = (uint8_t)(c & 0xFF);          /* Modbus：CRC 低字节在前 */
    f[7] = (uint8_t)(c >> 8);
    return uart_send(f, 8u);
}

/* esp_m03_modbus.c —— ESP32 侧发 Modbus 请求（Xtensa）。
 * 组帧逻辑与设备端一致；发送走 UART 驱动。 */
#include <stdint.h>
#include "esp_comm.h"
#include "comm_api.h"

int esp_modbus_read(uint8_t addr, uint16_t reg, uint16_t qty) {
    uint8_t f[8];
    f[0] = addr; f[1] = 0x03;
    f[2] = (uint8_t)(reg >> 8); f[3] = (uint8_t)reg;
    f[4] = (uint8_t)(qty >> 8); f[5] = (uint8_t)qty;
    uint16_t c = crc16_modbus(f, 6);
    f[6] = (uint8_t)c; f[7] = (uint8_t)(c >> 8);
    return uart_write_bytes(1, f, 8u);
}

/* h7_m03_modbus.c —— H7 侧解析 Modbus 响应（Cortex-M7）。
 * 校验整帧 CRC（含 CRC 再算应为 0）；功能码最高位置 1 表示异常。 */
#include <stdint.h>
#include "comm_api.h"

/* 返回 0=正常（regs[0..n) 有效），正数=异常码，-1=CRC 错 */
int h7_modbus_parse(const uint8_t *f, int n, uint16_t *regs, int max) {
    if (n < 5) return -1;
    uint16_t c = crc16_modbus(f, (size_t)(n - 2));
    if ((uint16_t)(f[n - 2] | (f[n - 1] << 8)) != c) return -1;   /* CRC 失败 */
    if (f[1] & 0x80) return f[2];                                  /* 异常响应 */
    int bc = f[2];
    int cnt = bc / 2;
    for (int i = 0; i < cnt && i < max; i++)
        regs[i] = (uint16_t)((f[3 + 2 * i] << 8) | f[4 + 2 * i]);   /* 线上大端 */
    return 0;
}

/* host_can.c —— CAN 位定时、仲裁与总线负载的小模型（主机可运行）。
 *
 *   ① 位定时：位时间 = 1(同步段) + BS1 + BS2 个时间份额(tq)，tq = 1/时钟；
 *      预分频 = 外设时钟 / (波特率 × 总 tq 数)，必须为整数。采样点 = (1+BS1)/总 tq。
 *   ② 仲裁：多个节点同时发送时，标识符数值越小优先级越高，逐位仲裁，输者自动重发。
 *   ③ 总线负载：负载‰ = 每秒帧数 × 每帧位数 / 波特率 × 1000。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_can.c -o host_can && ./host_can
 */
#include <stdio.h>
#include <stdint.h>

static int prescaler_for(uint32_t clock, uint32_t bitrate, int tq_total, int *out_presc, int *out_sp_permille, int bs1) {
    uint32_t denom = bitrate * (uint32_t)tq_total;
    if (denom == 0 || clock % denom != 0) return 0;
    *out_presc = (int)(clock / denom);
    *out_sp_permille = (1 + bs1) * 1000 / tq_total;
    return 1;
}
static int bus_load_permille(uint32_t fps, int bits_per_frame, uint32_t bitrate) {
    return (int)(((uint64_t)fps * (uint64_t)bits_per_frame * 1000u) / bitrate);
}

int main(void) {
    int ok = 1, presc = 0, sp = 0;

    /* ① 36MHz 外设时钟、500kbps、18 tq（BS1=15, BS2=2） */
    int found = prescaler_for(36000000u, 500000u, 18, &presc, &sp, 15);
    printf("位定时：36MHz / 500kbps / 18tq → 预分频=%d（期望 4），采样点=%d‰（期望 ~889‰）\n", presc, sp);
    if (!(found && presc == 4 && sp == 888)) ok = 0;

    /* 非整数预分频必须被拒绝：72MHz / 500kbps / 18tq = 8（整数）；改成 17tq 则不是整数 */
    if (prescaler_for(72000000u, 500000u, 17, &presc, &sp, 15)) { printf("本应拒绝非整数预分频\n"); ok = 0; }

    /* ② 仲裁：ID 越小越优先 */
    uint32_t ids[3] = {0x200u, 0x100u, 0x180u};
    uint32_t winner = ids[0];
    for (int i = 1; i < 3; i++) if (ids[i] < winner) winner = ids[i];
    printf("仲裁：{0x200,0x100,0x180} 的胜者=0x%03X（期望 0x100）\n", winner);
    if (winner != 0x100u) ok = 0;

    /* ③ 总线负载：1000 帧/s × 111 位 / 500kbps */
    int load = bus_load_permille(1000u, 111, 500000u);
    printf("总线负载：1000fps × 111bit / 500kbps = %d‰（期望 222‰）\n", load);
    if (load != 222) ok = 0;

    if (bus_load_permille(3000u, 130, 500000u) < 500) { printf("高负载估算偏低\n"); ok = 0; }

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m04_can.c —— bxCAN 初始化与发送（Cortex-M3）。
 * 位定时 500kbps（见 stm32_comm.h）；标准帧写入邮箱后置 TXRQ 触发发送。 */
#include <stdint.h>
#include "comm_api.h"
#include "stm32_comm.h"

void can500_init(void) {
    bxcan_set_500k();
    (void)can_accept_filter(0x100u, 0x700u);   /* 只收 0x100..0x1FF */
}

int can_tx_std(uint16_t id, const uint8_t *d, uint8_t dlc) {
    uint32_t lo = 0u, hi = 0u;
    for (int i = 0; i < 4; i++) {
        lo |= (uint32_t)((i < dlc) ? d[i] : 0u) << (8 * i);
        hi |= (uint32_t)((i + 4 < dlc) ? d[i + 4] : 0u) << (8 * i);
    }
    CAN1_TI0R  = ((uint32_t)id << 21);         /* 标准帧，ID 在 [31:21] */
    CAN1_TDT0R = dlc;
    CAN1_TDL0R = lo;
    CAN1_TDH0R = hi;
    CAN1_TI0R |= 0x1u;                         /* TXRQ：请求发送 */
    return 0;
}

/* esp_m04_twai.c —— 内置 TWAI(CAN 2.0B)（ESP32 / Xtensa）。
 * 安装 → 启动 → 发送；接收用 twai_receive（中断/轮询由驱动负责）。 */
#include <stdint.h>
#include "esp_comm.h"
#include "comm_api.h"

void esp_can_init(void) {
    twai_general_config_t g = {0};
    twai_timing_config_t  t = {0};
    twai_filter_config_t  f = {0};
    (void)twai_driver_install(&g, &t, &f);
    (void)twai_start();
}

int esp_can_tx(uint32_t id, const uint8_t *d, uint8_t dlc) {
    twai_message_t m;
    m.identifier = id;
    m.data_length_code = dlc;
    m.flags = 0;
    for (uint8_t i = 0; i < dlc && i < 8u; i++) m.data[i] = d[i];
    return (int)twai_transmit(&m, pdMS_TO_TICKS(10));
}

/* h7_m04_fdcan.c —— FDCAN 初始化骨架（STM32H7 / Cortex-M7）。
 * CAN-FD 支持更大载荷；位定时在 NBTP，收发描述符放在消息 RAM。 */
#include <stdint.h>
#include "comm_api.h"
#include "stm32_comm.h"

void h7_fdcan_init(void) {
    FDCAN_CCCR |= (1u << 0);            /* INIT：进入初始化 */
    FDCAN_CCCR |= (1u << 1);            /* CCE：允许写配置寄存器 */
    FDCAN_NBTP  = (4u << 16) | (14u << 8) | (1u << 0);   /* 示例：标称位定时字段 */
    FDCAN_CCCR &= ~(1u << 1);           /* 关闭配置使能 */
    FDCAN_CCCR &= ~(1u << 0);           /* 退出初始化 */
    while (FDCAN_CCCR & 1u) { }
}

uint32_t h7_fdcan_error_counters(void) {
    return FDCAN_PSR;                   /* 读取 REC/TEC 等错误计数用于总线诊断 */
}

