/* h7_m07_boot.c —— H7 跳转到 App（Cortex-M7）。
 * 除向量表/栈外，还要在跳转前关闭 I/D-Cache，避免与 App 的 cache 配置冲突。 */
#include <stdint.h>
#include "comm_api.h"
#include "rtos_cm.h"

#define SCB_CCR (*(volatile uint32_t *)0xE000ED14u)

void h7_jump_to_app(uint32_t base) {
    uint32_t sp = *(volatile uint32_t *)base;
    uint32_t pc = *(volatile uint32_t *)(base + 4u);
    cm_set_primask(1u);                                 /* 关中断 */
    SCB_CCR &= ~((1u << 16) | (1u << 17));              /* 关 D-Cache / I-Cache */
    CM_VTOR = base;                                     /* 重定位向量表 */
    cm_dsb();
    cm_isb();
    __asm volatile ("msr msp, %0" :: "r"(sp) :);
    ((void (*)(void))pc)();                             /* 跳转，不返回 */
}

/* host_ota.c —— OTA 分块写入 + 校验 + 掉电回滚模型（主机可运行）。
 *
 * 双区模型：A 区运行当前固件，B 区接收新固件。规则：
 *   ① 只有“所有分块写完 + 整镜像 CRC 校验通过”才切换运行区；
 *   ② 中途掉电 → B 区不完整，校验失败 → 继续运行 A 区（回滚）；
 *   ③ 切换后若新固件未“确认”，下次仍可退回 A 区。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_ota.c -o host_ota && ./host_ota
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define NCHUNK 4
#define CLEN 8

static uint16_t crc16(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1);
    }
    return c;
}

/* 返回 1=已切换运行区，0=保持/回滚；*reason 记录原因 */
static int ota_run(const uint8_t img[NCHUNK][CLEN], int fail_after, uint16_t expected_crc,
                   int confirm, const char **reason) {
    uint8_t staging[NCHUNK][CLEN];
    int written = 0;
    memset(staging, 0, sizeof(staging));
    for (int i = 0; i < NCHUNK; i++) {
        if (i == fail_after) { *reason = "掉电：分块未写完"; }
        if (fail_after >= 0 && i >= fail_after) break;
        memcpy(staging[i], img[i], CLEN);
        written++;
    }
    if (written != NCHUNK) return 0;                       /* 不完整 → 回滚 */
    uint16_t c = crc16((const uint8_t *)staging, NCHUNK * CLEN);
    if (c != expected_crc) { *reason = "整镜像 CRC 不匹配"; return 0; }
    if (!confirm) { *reason = "已切换但未确认：下次可退回"; return 1; }
    *reason = "校验通过并确认：切换完成";
    return 1;
}

int main(void) {
    int ok = 1;
    uint8_t img[NCHUNK][CLEN];
    for (int i = 0; i < NCHUNK; i++)
        for (int j = 0; j < CLEN; j++) img[i][j] = (uint8_t)(i * CLEN + j);
    uint16_t good = crc16((const uint8_t *)img, NCHUNK * CLEN);

    const char *r;
    int a = ota_run(img, -1, good, 1, &r);
    printf("正常升级：结果=%s（%s）\n", a ? "切换" : "回滚", r);
    if (a != 1) ok = 0;

    int b = ota_run(img, 2, good, 1, &r);
    printf("第 2 块后掉电：结果=%s（%s）\n", b ? "切换" : "回滚", r);
    if (b != 0) ok = 0;

    int c = ota_run(img, -1, (uint16_t)(good ^ 0xFFFF), 1, &r);
    printf("镜像被篡改：结果=%s（%s）\n", c ? "切换" : "回滚", r);
    if (c != 0) ok = 0;

    int d = ota_run(img, -1, good, 0, &r);
    printf("校验通过但未确认：结果=%s（%s）\n", d ? "切换" : "回滚", r);
    if (d != 1) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m08_ota.c —— 串口分块 OTA（Cortex-M3）。
 * 边收边写；任一步失败或超时都保留旧固件；全部写完并校验通过才切换。 */
#include <stdint.h>
#include <stddef.h>
#include "comm_api.h"

int ota_over_uart(uint32_t total, uint32_t crc) {
    uint8_t buf[256];
    if (ota_begin(total, crc) != 0) return -1;
    uint32_t got = 0;
    while (got < total) {
        int n = uart_recv(buf, sizeof(buf), 5000u);
        if (n <= 0) return -2;                      /* 超时：回滚 */
        if (ota_write(buf, (size_t)n) != 0) return -3;
        got += (uint32_t)n;
    }
    return ota_finish();                            /* 校验 + 切换 */
}

/* esp_m08_ota.c —— ESP32 原生 OTA（Xtensa）。
 * 写备用分区 → 校验 → 设置启动分区；启动后未调用 mark_valid 会触发回滚。 */
#include "esp_comm.h"

int esp_ota_apply(const uint8_t *img, size_t n) {
    esp_ota_handle_t h;
    const esp_partition_t *p = esp_ota_get_next_update_partition(0);
    if (!p) return -1;
    if (esp_ota_begin(p, n, &h) != ESP_OK) return -2;
    if (esp_ota_write(h, img, n) != ESP_OK) return -3;
    if (esp_ota_end(h) != ESP_OK) return -4;
    if (esp_ota_set_boot_partition(p) != ESP_OK) return -5;
    return 0;
}

void esp_ota_confirm(void) { (void)esp_ota_mark_app_valid_cancel_rollback(); }
void esp_ota_reject(void)  { (void)esp_ota_mark_app_invalid_rollback_and_reboot(); }

/* h7_m08_ota.c —— 双 Bank OTA（STM32H7 / Cortex-M7）。
 * 新固件写入备用 Bank，校验通过后做 Bank Swap；失败则不交换，继续跑原 Bank。 */
#include <stdint.h>
#include <stddef.h>
#include "comm_api.h"

int h7_ota_dualbank(const uint8_t *img, size_t n, uint32_t image_crc) {
    if (ota_begin((uint32_t)n, image_crc) != 0) return -1;
    if (ota_write(img, n) != 0) return -2;
    return ota_finish();        /* 校验通过后交换 Bank，并记录“待确认”标志 */
}

int h7_ota_confirm(void)  { return 0; }             /* 运行正常：清除待确认标志 */
int h7_ota_rollback(void) { return ota_rollback(); }/* 启动超时：换回原 Bank */

/* m09_debug.c —— 链路统计与总线负载（Cortex-M3）。
 * 现场诊断先看三类计数：CRC 错、超时、总线关闭；再算总线负载是否过高。 */
#include <stdint.h>
#include "comm_api.h"

typedef struct { uint32_t crc_err; uint32_t timeout; uint32_t bus_off; uint32_t frames; } link_stat_t;

void link_stat_frame(link_stat_t *s, int crc_ok) {
    s->frames++;
    if (!crc_ok) s->crc_err++;
}

int bus_load_permille(uint32_t fps, uint32_t bits_per_frame, uint32_t bitrate) {
    return (int)(((uint64_t)fps * bits_per_frame * 1000u) / bitrate);
}

/* 错误率超过阈值就应告警/降速 */
int link_should_alert(const link_stat_t *s, int permille_threshold) {
    if (s->frames == 0) return 0;
    return (int)(s->crc_err * 1000u / s->frames) > permille_threshold;
}

