#include "esp_comm.h"

int esp_link_rssi(void) { return esp_wifi_sta_get_rssi(); }

/* RSSI 分级：低于 -80dBm 视为弱链路，应降速或换信道（经验阈值） */
int esp_link_quality(void) {
    int r = esp_link_rssi();
    if (r >= -60) return 2;
    if (r >= -80) return 1;
    return 0;
}

/* h7_m09_debug.c —— FDCAN 错误计数（STM32H7 / Cortex-M7）。
 * PSR 里有 TEC/REC 与总线状态位：错误计数持续上升说明终端电阻/线缆/波特率有问题。 */
#include <stdint.h>
#include "comm_api.h"
#include "stm32_comm.h"

uint32_t h7_can_error_state(void) { return FDCAN_PSR; }

/* 提取接收/发送错误计数（示意字段，实际位域见参考手册） */
