/* host_backoff.c —— 断网重连的指数退避、去重缓存与幂等（主机可运行）。
 *
 *   ① 指数退避：退避 = min(base × 2^attempt, cap)，避免断网时雪崩式重连。
 *   ② 有界去重缓存：只保留最近 N 条消息 id，防止重复执行；缓存满则淘汰最旧。
 *   ③ 幂等：同一条命令重复到达，状态只应改变一次。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_backoff.c -o host_backoff && ./host_backoff
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint32_t backoff_ms(int attempt, uint32_t base, uint32_t cap) {
    uint64_t v = (uint64_t)base << attempt;          /* base × 2^attempt */
    return v > cap ? cap : (uint32_t)v;
}

#define CACHE 4
typedef struct { int id[CACHE]; int n; } cache_t;
static int cache_has(cache_t *c, int id) {
    for (int i = 0; i < c->n; i++) if (c->id[i] == id) return 1;
    return 0;
}
static void cache_put(cache_t *c, int id) {
    if (c->n < CACHE) c->id[c->n++] = id;
    else { memmove(c->id, c->id + 1, (CACHE - 1) * sizeof(int)); c->id[CACHE - 1] = id; }
}

int main(void) {
    int ok = 1;

    printf("指数退避（base=100ms, cap=30000ms）：");
    uint32_t last = 0;
    for (int a = 0; a <= 10; a++) {
        uint32_t v = backoff_ms(a, 100, 30000);
        printf("%ums%s", v, a < 10 ? ", " : "\n");
        if (a > 0 && v < last) ok = 0;               /* 必须非递减 */
        if (v > 30000u) ok = 0;                      /* 不超过 cap */
        last = v;
    }
    if (backoff_ms(0, 100, 30000) != 100 || backoff_ms(9, 100, 30000) != 30000) ok = 0;

    cache_t c; memset(&c, 0, sizeof(c));
    for (int id = 1; id <= 5; id++) cache_put(&c, id);
    printf("去重缓存（容量 %d，插入 1..5）：has(1)=%d（应 0，已淘汰）has(3)=%d（应 1）has(5)=%d（应 1）\n",
           CACHE, cache_has(&c, 1), cache_has(&c, 3), cache_has(&c, 5));
    if (cache_has(&c, 1) != 0 || cache_has(&c, 3) != 1 || cache_has(&c, 5) != 1) ok = 0;

    /* 幂等：命令 id=42 重复 3 次，状态只应 +1 */
    int state = 0;
    cache_t seen; memset(&seen, 0, sizeof(seen));
    for (int i = 0; i < 3; i++) {
        if (!cache_has(&seen, 42)) { state += 1; cache_put(&seen, 42); }
    }
    printf("幂等：命令 id=42 重复 3 次 → state=%d（期望 1）\n", state);
    if (state != 1) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m12_backoff.c —— 指数退避与有界离线缓存（Cortex-M3）。
 * 断网时不能死循环重连；缓存有上界，满了丢最旧并计数，避免 RAM 被吃光。 */
#include <stdint.h>
#include <string.h>
#include "comm_api.h"

uint32_t reconnect_backoff_ms(int attempt) {
    uint64_t v = 100ull << attempt;                 /* 100ms × 2^attempt */
    return v > 30000ull ? 30000u : (uint32_t)v;
}

#define CACHE_CAP 64
#define ITEM_LEN  32
typedef struct { uint8_t buf[CACHE_CAP][ITEM_LEN]; int n; uint32_t dropped; } offcache_t;

int cache_push(offcache_t *c, const uint8_t *d) {
    if (c->n == CACHE_CAP) {                         /* 满：丢最旧，计数 */
        memmove(c->buf[0], c->buf[1], (CACHE_CAP - 1) * ITEM_LEN);
        c->n = CACHE_CAP - 1;
        c->dropped++;
    }
    memcpy(c->buf[c->n++], d, ITEM_LEN);
    return 0;
}

/* esp_m12_reconnect.c —— 断连事件触发指数退避重连（ESP32 / Xtensa）。
 * 连接失败/断开时不要立刻重连，按退避时间等待并更新状态。 */
#include "esp_comm.h"
#include "comm_api.h"

static uint32_t backoff_ms(int attempt) {
    uint32_t v = 100u << attempt;
    return v > 30000u ? 30000u : v;
}

void esp_on_disconnect(int *attempt) {
    uint32_t wait = backoff_ms(*attempt);
    (*attempt)++;
    vTaskDelay(pdMS_TO_TICKS(wait));
    (void)esp_wifi_connect();
    if (*attempt > 8) *attempt = 8;      /* 退避封顶，避免无限增长 */
}

/* h7_m12_ringcache.c —— 断网期间的环形离线缓存（STM32H7 / Cortex-M7）。
 * head/tail 分离读写；区分空与满；恢复后按序补传，保证不丢不乱序。 */
#include <stdint.h>
#include "comm_api.h"

#define RCAP 128
typedef struct {
    uint8_t  buf[RCAP][32];
    uint16_t head;     /* 写位置 */
    uint16_t tail;     /* 读位置 */
    uint16_t count;
    uint32_t dropped;
} ring_t;

int ring_push(ring_t *r, const uint8_t *d) {
    if (r->count == RCAP) { r->dropped++; return -1; }   /* 满：拒绝新数据并计数 */
    for (int i = 0; i < 32; i++) r->buf[r->head][i] = d[i];
    r->head = (uint16_t)((r->head + 1u) % RCAP);
    r->count++;
    return 0;
}

int ring_pop(ring_t *r, uint8_t *out) {
    if (r->count == 0) return -1;                        /* 空 */
    for (int i = 0; i < 32; i++) out[i] = r->buf[r->tail][i];
    r->tail = (uint16_t)((r->tail + 1u) % RCAP);
    r->count--;
    return 0;
}

/* m13_version.c —— 镜像/协议版本比较与升级准入（Cortex-M3）。
 * 版本用整型打包（如高 16 位主版本、低 16 位次版本）便于比较；
 * 升级准入规则：不降级、跨度过大先迁移。 */
#include <stdint.h>
#include "comm_api.h"

int ver_cmp(uint32_t a, uint32_t b) { return a < b ? -1 : (a > b ? 1 : 0); }

/* 返回 1=允许，0=不升（同版或更旧），-1=需先迁移到最低兼容版本 */
int upgrade_allowed(uint32_t cur, uint32_t img, uint32_t min_from) {
    if (img <= cur) return 0;          /* 不允许降级/同版 */
    if (cur < min_from) return -1;     /* 跨度过大：先做参数迁移 */
    return 1;
}

