/* esp_m13_rollback.c —— ESP32 升级确认与回滚（Xtensa）。
 * 新固件首次启动后必须在自检通过时调用 confirm，否则复位时自动回滚。 */
#include "esp_comm.h"

void esp_confirm_ok(void) { (void)esp_ota_mark_app_valid_cancel_rollback(); }
void esp_rollback_now(void) { (void)esp_ota_mark_app_invalid_rollback_and_reboot(); }

/* 启动自检：联网、外设、参数版本都正常才算“确认” */
int esp_selfcheck(int net_ok, int periph_ok, int cfg_ok) {
    if (net_ok && periph_ok && cfg_ok) { esp_confirm_ok(); return 0; }
    return -1;      /* 不确认：留给下次复位回滚 */
}

/* h7_m13_rollback.c —— H7 双 Bank 升级确认（Cortex-M7）。
 * “待确认”标志与启动计数存在备份域；连续启动失败超过阈值就换回原 Bank。 */
#include <stdint.h>
#include "comm_api.h"

#define BKP_FLAG  (*(volatile uint32_t *)0x40006C04u)   /* 备份寄存器示例地址 */
#define BKP_TRIES (*(volatile uint32_t *)0x40006C08u)

void h7_mark_pending(void) { BKP_FLAG = 0xA5A5A5A5u; BKP_TRIES = 0u; }
void h7_mark_confirmed(void) { BKP_FLAG = 0u; }

/* 启动时决策：返回 1=继续运行并计数，0=正常运行（已确认），-1=回滚 */
int h7_boot_decision(int selfcheck_ok) {
    if (BKP_FLAG != 0xA5A5A5A5u) return 0;              /* 没有待确认标志 */
    if (selfcheck_ok) { h7_mark_confirmed(); return 0; }
    BKP_TRIES++;
    if (BKP_TRIES > 3u) return -1;                      /* 连续失败：回滚 */
    return 1;
}

/* capstone_ota_node.c —— 贯穿项目骨架：可远程升级传感器节点（Cortex-M3 示范）。
 * 采样轮询（Modbus）与升级分块共用串口，用互斥量串行化；
 * 升级写入备用区，校验通过才切换；新固件自检通过前不确认（可回滚）。 */
#include <stdint.h>
