static SemaphoreHandle_t g_bus;
static QueueHandle_t g_uplink;

typedef struct { uint16_t reg; uint16_t val; } sample_t;

static void poll_task(void *arg) {
    uint8_t req[8] = {0x01, 0x03, 0x00, 0x00, 0x00, 0x02};
    uint16_t c = crc16_modbus(req, 6);
    req[6] = (uint8_t)c; req[7] = (uint8_t)(c >> 8);
    (void)arg;
    for (;;) {
        if (xSemaphoreTake(g_bus, pdMS_TO_TICKS(50)) == pdTRUE) {
            (void)uart_send(req, 8u);
            xSemaphoreGive(g_bus);
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

static void ota_task(void *arg) {
    (void)arg;
    for (;;) {
        /* 收到命令：ota_begin(total, crc)；循环 uart_recv + ota_write；ota_finish() 校验并切换 */
        vTaskDelay(pdMS_TO_TICKS(5000));
    }
}

static void mode_switch(int enter_ota) {
    cm_set_primask(enter_ota ? 1u : 0u);   /* 进入升级前后对关键窗口做保护（示意） */
}

void capstone_start(void) {
    g_bus = xSemaphoreCreateMutex();
    g_uplink = xQueueCreate(16u, (uint32_t)sizeof(sample_t));
    (void)g_uplink;
    (void)xTaskCreate(poll_task, "poll", 512u, 0, 3u, 0);
    (void)xTaskCreate(ota_task,  "ota",  768u, 0, 2u, 0);
    mode_switch(0);
}

/* host_fsm.c —— 应用状态机：正常/降级/故障锁存（主机可运行）。
 *
 * 把界面的“模式”与业务的“状态”统一成一张显式状态机：
 *   BOOT → IDLE → RUN →（STOP）IDLE；RUN 遇 SENSOR_INVALID → FAULT（锁存）。
 * 关键规则：① 故障优先并锁存，必须显式 RESET 才能清除；② 非法的 (状态,事件) 组合被忽略，不改变状态。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_fsm.c -o host_fsm && ./host_fsm
 */
#include <stdio.h>
#include <string.h>

typedef enum { BOOT, IDLE, RUN, FAULT, SLEEP, NSTATE } state_t;
typedef enum { EV_START, EV_ARM, EV_STOP, EV_SENSOR_INVALID, EV_RESET, EV_SLEEP, EV_WAKE, NEVENT } event_t;

static const char *SNAME[NSTATE]  = {"BOOT", "IDLE", "RUN", "FAULT", "SLEEP"};
static const char *ENAME[NEVENT]  = {"START", "ARM", "STOP", "SENSOR_INVALID", "RESET", "SLEEP", "WAKE"};

/* 返回下一个状态；无效组合返回当前状态 */
static state_t step(state_t s, event_t e) {
    switch (s) {
        case BOOT:  return (e == EV_START) ? IDLE : s;
        case IDLE:  if (e == EV_ARM) return RUN;
                    if (e == EV_SLEEP) return SLEEP;
                    return s;
        case RUN:   if (e == EV_STOP) return IDLE;
                    if (e == EV_SLEEP) return SLEEP;
                    if (e == EV_SENSOR_INVALID) return FAULT;   /* 故障优先且锁存 */
                    return s;
        case FAULT: return (e == EV_RESET) ? IDLE : s;          /* 只能显式复位 */
        case SLEEP: return (e == EV_WAKE) ? IDLE : s;
        default:    return s;
    }
}

int main(void) {
    event_t script[] = {EV_START, EV_ARM, EV_SENSOR_INVALID, EV_ARM, EV_RESET, EV_ARM};
    state_t s = BOOT;
    int entered_fault = 0, ignored_in_fault = 0;
    printf("起始状态: %s\n", SNAME[s]);
    for (unsigned i = 0; i < sizeof(script) / sizeof(script[0]); i++) {
        state_t ns = step(s, script[i]);
        printf("  %-14s: %s -> %s%s\n", ENAME[script[i]], SNAME[s], SNAME[ns],
               ns == s ? "（忽略）" : "");
        if (ns == FAULT) entered_fault = 1;
        if (s == FAULT && ns == FAULT) ignored_in_fault++;
        s = ns;
    }
    printf("最终状态: %s\n", SNAME[s]);

    int ok = 1;
    if (!entered_fault) ok = 0;          /* 故障被进入 */
    if (ignored_in_fault < 1) ok = 0;    /* 锁存：FAULT 期间的 ARM 被忽略 */
    if (s != RUN) ok = 0;                /* 复位并重新 ARM 后回到 RUN */
    if (step(IDLE, EV_SENSOR_INVALID) != IDLE) ok = 0;  /* IDLE 下该事件无效 */
    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m01_arch.c —— 模块化架构：接口表 + 状态机（Cortex-M3）。
 * 先把模块抽象成 {init, poll} 接口，再决定前后台还是任务骨架；先画架构再写代码。 */
#include <stdint.h>
#include "app_api.h"

typedef struct { const char *name; int (*init)(void); int (*poll)(void); } module_t;

extern int sensor_mod_init(void);   extern int sensor_mod_poll(void);
extern int ui_mod_init(void);       extern int ui_mod_poll(void);
extern int comm_mod_init(void);     extern int comm_mod_poll(void);

static const module_t g_modules[] = {
    {"sensor", sensor_mod_init, sensor_mod_poll},
    {"ui",     ui_mod_init,     ui_mod_poll},
    {"comm",   comm_mod_init,   comm_mod_poll},
};

/* 前后台骨架：按“截止期从紧到松”排序后轮询；有硬期限后再升级为 RTOS（M10/M11） */
void app_superloop(void) {
    for (unsigned i = 0; i < sizeof(g_modules) / sizeof(g_modules[0]); i++) {
        if (g_modules[i].init) (void)g_modules[i].init();
    }
    for (;;) {
        for (unsigned i = 0; i < sizeof(g_modules) / sizeof(g_modules[0]); i++) {
            (void)g_modules[i].poll();
        }
    }
}

/* esp_m01_arch.c —— 任务化架构（ESP32 / Xtensa）。
 * 每个模块一个任务，用亲和把“采集”和“通信”分到不同核，接口仍是 {init, task}。 */
#include "esp_app.h"
#include "app_api.h"

/* 由外部提供：界面刷新（示例） */
int ui_refresh(void);

static void sensor_task(void *arg) { (void)arg; for (;;) { vTaskDelay(pdMS_TO_TICKS(100)); } }
static void ui_task(void *arg)     { (void)arg; for (;;) { (void)ui_refresh(); vTaskDelay(pdMS_TO_TICKS(50)); } }
static void comm_task(void *arg)   { (void)arg; for (;;) { vTaskDelay(pdMS_TO_TICKS(1000)); } }

void esp_arch_start(void) {
    TaskHandle_t a = 0, b = 0;
    (void)xTaskCreatePinnedToCore(sensor_task, "sensor", 4096u, 0, 4u, &a, 0);
    (void)xTaskCreatePinnedToCore(ui_task,     "ui",     4096u, 0, 3u, &b, 1);
    (void)xTaskCreatePinnedToCore(comm_task,   "comm",   4096u, 0, 2u, &a, 1);
}

/* h7_m01_arch.c —— 任务 + 队列架构（STM32H7 / Cortex-M7）。
 * 采集任务投递样本，处理/通信任务消费；用队列解耦速率。 */
#include <stdint.h>
#include "app_api.h"

typedef struct { int16_t v; } sample_t;
static QueueHandle_t g_q;

static void acq_task(void *arg) {
    sample_t s = {0};
    (void)arg;
    for (;;) {
        (void)xQueueSend(g_q, &s, pdMS_TO_TICKS(5));
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}
static void proc_task(void *arg) {
    sample_t s;
    (void)arg;
    for (;;) {
        if (xQueueReceive(g_q, &s, portMAX_DELAY) == pdTRUE) { /* 处理 */ }
    }
}
void h7_arch_start(void) {
    g_q = xQueueCreate(8u, (uint32_t)sizeof(sample_t));
    (void)xTaskCreate(acq_task,  "acq",  512u, 0, 4u, 0);
    (void)xTaskCreate(proc_task, "proc", 512u, 0, 3u, 0);
}

