/* host_ringlog.c —— 环形日志 + 掉电提交（主机可运行）。
 *
 * 存储只能把位从 1 写成 0。做法：每条记录带 seq + CRC；写完记录后才写“提交标记”。
 * 掉电发生在“写记录”和“写提交标记”之间时，恢复后该记录因无提交标记而被跳过。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_ringlog.c -o host_ringlog && ./host_ringlog
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define N 4
typedef struct { uint8_t seq; int16_t v; uint8_t committed; uint16_t crc; } rec_t;

static uint16_t crc16(const uint8_t *p, int n) {
    uint16_t c = 0xFFFF;
    for (int i = 0; i < n; i++) { c ^= p[i]; for (int b = 0; b < 8; b++) c = (c & 1) ? (uint16_t)((c >> 1) ^ 0xA001) : (uint16_t)(c >> 1); }
    return c;
}
static uint16_t rec_crc(const rec_t *r) { return crc16((const uint8_t *)r, 4); }  /* seq+v+crc 前的 4 字节 */

typedef struct { rec_t slot[N]; int head; int written; int committed; } log_t;

static void log_write(log_t *L, uint8_t seq, int16_t v, int powerfail_before_commit) {
    rec_t *r = &L->slot[L->head];
    memset(r, 0, sizeof(*r));
    r->seq = seq; r->v = v;
    r->crc = rec_crc(r);
    L->written++;
    if (powerfail_before_commit) return;      /* 掉电：未写提交标记 */
    r->committed = 1;
    L->committed++;
    L->head = (L->head + 1) % N;
}
/* 恢复：只把“有提交标记且 CRC 正确”的记录算作有效 */
static int log_recover(const log_t *L, int16_t *out, int max) {
    int n = 0;
    for (int i = 0; i < N; i++) {
        const rec_t *r = &L->slot[i];
        if (r->committed && rec_crc(r) == r->crc) {
            if (n < max) out[n] = r->v;
            n++;
        }
    }
    return n;
}

int main(void) {
    log_t L; memset(&L, 0, sizeof(L));
    int16_t out[N];
    int ok = 1;

    log_write(&L, 1, 100, 0);
    log_write(&L, 2, 200, 0);
    log_write(&L, 3, 300, 1);          /* 第 3 条写完但提交前掉电 */
    int valid = log_recover(&L, out, N);
    printf("写完 3 条（第 3 条掉电于提交前）→ 有效记录 %d 条：", valid);
    for (int i = 0; i < valid; i++) printf("%d ", out[i]);
    printf("\n");
    if (valid != 2) ok = 0;
    if (!(out[0] == 100 && out[1] == 200)) ok = 0;

    /* 提交标记被破坏 → CRC 不符也跳过 */
    L.slot[0].crc ^= 0xFF;
    int v2 = log_recover(&L, out, N);
    printf("损坏第 1 条后 → 有效记录 %d 条（期望 1）\n", v2);
    if (v2 != 1) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m04_log.c —— 环形日志落盘与掉电提交（Cortex-M3）。
 * 先写记录，再写提交标记；掉电中断只会丢弃最后一条未提交记录。 */
#include <stdint.h>
#include "app_api.h"

#define LOG_BASE 0x0801F000u
typedef struct { uint8_t seq; int16_t v; uint8_t committed; } rec_t;

int log_append(uint8_t seq, int16_t v) {
    rec_t r;
    r.seq = seq; r.v = v; r.committed = 0;
    if (storage_write(LOG_BASE, &r, 3) != 0) return -1;      /* 写记录 */
    uint8_t c = 1;
    if (storage_write(LOG_BASE + 2, &c, 1) != 0) return -2;  /* 写提交标记 */
    return (int)storage_sync();
}

/* esp_m04_nvs.c —— ESP32 用 NVS 持久化（Xtensa）。
 * NVS 自带磨损均衡与掉电安全；写入后必须 commit 才落盘。 */
#include "esp_app.h"
#include "app_api.h"

int esp_store_sample(uint16_t v) {
    nvs_handle_t h;
    if (nvs_open("log", 1, &h) != ESP_OK) return -1;
    if (nvs_set_u16(h, "s", v) != ESP_OK) return -2;
    return (int)nvs_commit(h);
}

/* h7_m04_log.c —— H7 大扇区日志与回放（Cortex-M7）。
 * 记录追加到扇区，用提交标记区分“写完”与“未写完”；导出时跳过未提交。 */
#include <stdint.h>
#include <stddef.h>
#include "app_api.h"
#include "stm32_app.h"

#define SECTOR_SIZE 131072u
typedef struct { uint32_t seq; int16_t v; uint32_t committed; } rec_t;

int h7_log_append(uint32_t offset, uint32_t seq, int16_t v) {
    if (offset + sizeof(rec_t) > SECTOR_SIZE) return -1;     /* 扇区边界 */
    rec_t r;
    r.seq = seq; r.v = v; r.committed = 0;
    if (storage_write(offset, &r, sizeof(r) - 4) != 0) return -2;
    r.committed = 0xA5A5A5A5u;
    return (int)storage_write(offset + offsetof(rec_t, committed), &r.committed, 4);
}

/* host_pid.c —— 离散 PID 与积分抗饱和（主机可运行）。
 *
 * 被控对象：一阶加热模型 y' = (K·u − y)/tau，u∈[0,1]，K=100 → u=0.5 时稳态 50℃。
 * 对比：关闭抗饱和时执行器饱和期间积分无界累积（windup），回落设定后大幅超调；
 *       开启抗饱和（饱和且误差同号时停止积分）后积分有界、回落平顺。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_pid.c -o host_pid && ./host_pid
 */
#include <stdio.h>

typedef struct { double kp, ki; double I, last_e; int use_aw; } pid_t;

static double pid_step(pid_t *p, double sp, double y, double dt, int *sat) {
    double e = sp - y;
    double P = p->kp * e;
    double u = P + p->ki * p->I;          /* I = ∫e dt（积分状态） */
    *sat = 0;
    if (u > 1.0) { u = 1.0; *sat = 1; }
    if (u < 0.0) { u = 0.0; *sat = -1; }
    /* 抗饱和：饱和且误差会把执行器推得更满时，停止积分 */
    int freeze = p->use_aw && (*sat != 0) && ((*sat > 0 && e > 0) || (*sat < 0 && e < 0));
    if (!freeze) p->I += e * dt;
    p->last_e = e;
    return u;
}

static void run(int use_aw, double sp1, double sp2, double *peak_I, double *max_y_after2, int *within) {
    pid_t p = {0.03, 0.02, 0.0, 0.0, use_aw};
    double y = 0.0, dt = 0.05, K = 100.0, tau = 8.0, peak = 0.0, after2max = 0.0;
    int i, sat;
    for (i = 0; i < 400; i++) {                 /* 阶段 1：设定 sp1（可能不可达→饱和） */
        double u = pid_step(&p, sp1, y, dt, &sat);
        y += dt * (K * u - y) / tau;
        if (p.I > peak) peak = p.I;
    }
    for (i = 0; i < 400; i++) {                 /* 阶段 2：回落到 sp2 */
        double u = pid_step(&p, sp2, y, dt, &sat);
        y += dt * (K * u - y) / tau;
        if (y > after2max) after2max = y;
        if (p.I > peak) peak = p.I;
    }
    *peak_I = peak;
    *max_y_after2 = after2max;
    *within = (y > sp2 - 2.0 && y < sp2 + 2.0);
}

int main(void) {
    double peak_on, peak_off, ymax_on, ymax_off;
    int ok_on, ok_off;
    run(1, 150.0, 40.0, &peak_on, &ymax_on, &ok_on);    /* 开抗饱和 */
    run(0, 150.0, 40.0, &peak_off, &ymax_off, &ok_off); /* 关抗饱和 */

    printf("设定 150 不可达（执行器上限），再回落到 40：\n");
    printf("  开抗饱和：峰值积分=%.1f  回落后峰值 y=%.1f  最终在 40±2 内=%d\n", peak_on, ymax_on, ok_on);
    printf("  关抗饱和：峰值积分=%.1f  回落后峰值 y=%.1f  最终在 40±2 内=%d\n", peak_off, ymax_off, ok_off);

    int ok = 1;
    if (!ok_on) ok = 0;
    if (!(peak_off > peak_on * 1.5)) ok = 0;    /* 无抗饱和积分明显更大 */
    if (!(ymax_off > ymax_on + 2.0)) ok = 0;    /* 无抗饱和回落超调更大 */
    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* m05_pid.c —— 离散 PID 与抗饱和（Cortex-M3）。 */
#include "app_api.h"
#include "pid_api.h"

int pid_step(pid_t *p, float sp, float y, float dt, int out_min, int out_max) {
    float e = sp - y;
    p->I += e * dt;                                   /* 积分 */
    float u = p->kp * e + p->ki * p->I + p->kd * (e - p->last_e) / dt;
    p->last_e = e;
    int uu = (int)u, sat = 0;
    if (uu > out_max) { uu = out_max; sat = 1; }
    if (uu < out_min) { uu = out_min; sat = -1; }
    if (sat && ((sat > 0 && e > 0) || (sat < 0 && e < 0))) p->I -= e * dt;  /* 抗饱和回退 */
    return uu;
}

/* esp_m05_pid.c —— ESP32 速度环 + LEDC PWM（Xtensa）。 */
#include "esp_app.h"
#include "pid_api.h"

static pid_t g_pid = { 8.0f, 0.5f, 0.1f, 0.0f, 0.0f };

int esp_motor_ctrl(float sp, float speed, float dt) {
    int duty = pid_step(&g_pid, sp, speed, dt, 0, 1023);
    ledc_set_duty(0, 0, (uint32_t)duty);
    ledc_update_duty(0, 0);
    return duty;
}

/* h7_m05_pid.c —— H7 速度环 + 定时器 PWM + 编码器（Cortex-M7）。 */
#include "pid_api.h"
#include "stm32_app.h"

static pid_t g_pid = { 8.0f, 0.5f, 0.1f, 0.0f, 0.0f };

int h7_motor_ctrl(float sp, float speed, float dt) {
    int d = pid_step(&g_pid, sp, speed, dt, 0, 1000);
