/* capstone_app_node.c —— 贯穿项目：产品级环境监测终端（Cortex-M3 示范）。
 * 采集(高) → 队列 → 界面(低)；共享 I²C 用互斥量；看门狗仅在关键任务健康时喂；
 * 参数双副本、上报走 B07 的协议与 OTA。 */
#include <stdint.h>
#include "app_api.h"
#include "stm32_app.h"

void wdt_init(void);
void wdt_feed_if_healthy(int sensor_ok, int control_ok, int comm_ok);

static QueueHandle_t g_samples;
static SemaphoreHandle_t g_i2c;

static void acq_task(void *arg) {
    float t = 0.0f, r = 0.0f;
    (void)arg;
    for (;;) {
        if (xSemaphoreTake(g_i2c, pdMS_TO_TICKS(5)) == pdTRUE) {
            if (sensor_read(&t, &r) == 0) { (void)xQueueSend(g_samples, &t, pdMS_TO_TICKS(5)); }
            xSemaphoreGive(g_i2c);
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}
static void ui_task(void *arg) {
    (void)arg;
    for (;;) { (void)display_flush(); vTaskDelay(pdMS_TO_TICKS(500)); }
}
static void monitor_task(void *arg) {
    (void)arg;
    for (;;) {
        wdt_feed_if_healthy(1, 1, 1);   /* 三个关键任务都健康才喂狗 */
        vTaskDelay(pdMS_TO_TICKS(200));
    }
}

void capstone_start(void) {
    g_samples = xQueueCreate(16u, (uint32_t)sizeof(float));
    g_i2c = xSemaphoreCreateMutex();
    (void)xTaskCreate(acq_task,     "acq", 512u, 0, 4u, 0);
    (void)xTaskCreate(ui_task,      "ui",  512u, 0, 2u, 0);
    (void)xTaskCreate(monitor_task, "mon", 512u, 0, 1u, 0);
    wdt_init();
}

/* host_bootlog.c —— 启动日志分阶段与耗时分析（主机可运行）。
 *
 * 启动链 ROM→SPL→U-Boot→Kernel→init，每一跳都会在串口打印带时间戳的日志。
 * 本程序把日志按关键字分阶段、算出各阶段耗时，并检测 panic/卡死等异常。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_bootlog.c -o host_bootlog && ./host_bootlog
 */
#include <stdio.h>
#include <string.h>

typedef struct { int ms; const char *s; } line_t;

static const char *phase_of(const char *s) {
    if (strstr(s, "ROM"))       return "ROM";
    if (strstr(s, "SPL"))       return "SPL";
    if (strstr(s, "U-Boot"))    return "U-Boot";
    if (strstr(s, "Linux version")) return "Kernel";
    if (strstr(s, "init:"))     return "init";
    return 0;
}
static int has_panic(const line_t *L, int n) {
    for (int i = 0; i < n; i++)
        if (strstr(L[i].s, "panic") || strstr(L[i].s, "ERROR")) return L[i].ms;
    return -1;
}
static int analyze(const line_t *L, int n) {
    const char *phases[5] = {"ROM", "SPL", "U-Boot", "Kernel", "init"};
    int at[5]; for (int i = 0; i < 5; i++) at[i] = -1;
    for (int i = 0; i < n; i++) {
        const char *p = phase_of(L[i].s);
        for (int j = 0; j < 5; j++) if (p && strcmp(p, phases[j]) == 0 && at[j] < 0) at[j] = L[i].ms;
    }
    printf("阶段时间(ms):");
    for (int j = 0; j < 5; j++) printf(" %s=%d", phases[j], at[j]);
    printf("\n");
    int order_ok = 1;
    for (int j = 1; j < 5; j++) if (at[j] < at[j - 1]) order_ok = 0;
    printf("阶段耗时(ms): ROM→SPL=%d SPL→U-Boot=%d U-Boot→Kernel=%d Kernel→init=%d 总=%d\n",
           at[1] - at[0], at[2] - at[1], at[3] - at[2], at[4] - at[3], at[4] - at[0]);
    int panic = has_panic(L, n);
    printf("异常(panic/ERROR)时刻=%d\n", panic);
    return order_ok && at[0] >= 0 && at[4] > at[0];
}

int main(void) {
    line_t good[] = {
        {0, "[ROM] boot mode SD"}, {8, "[SPL] ddr init"}, {18, "[U-Boot] 2023.10"},
        {140, "[U-Boot] loading kernel"}, {600, "[Linux version] 6.1"}, {2700, "[init:] started"},
    };
    line_t bad[] = {
        {0, "[ROM] boot"}, {10, "[SPL] ok"}, {30, "[U-Boot] load kernel"},
        {500, "[Linux version] 6.1"}, {900, "ERROR: rootfs mount failed"}, {1200, "Kernel panic - not syncing"},
    };
    int ok = 1, n1 = (int)(sizeof(good) / sizeof(good[0])), n2 = (int)(sizeof(bad) / sizeof(bad[0]));
    printf("== 正常启动 ==\n");
    if (!analyze(good, n1)) ok = 0;
    printf("\n== 故障启动 ==\n");
    int ok_bad = analyze(bad, n2);
    if (ok_bad) ok = 0;              /* 故障启动不应被判为“正常” */
    if (ok) printf("\n%s\n", "RESULT: PASS"); else printf("\n%s\n", "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_toolchain.c —— 交叉工具链与 sysroot 一致性检查（主机可运行）。
 *
 * 用户态应用须匹配目标 ABI/libc；内核及模块使用匹配的内核构建树与配置。
 * 本程序仅按路径名字提示架构，不验证 ELF、浮点 ABI、libc 或加载器兼容性。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_toolchain.c -o host_toolchain && ./host_toolchain
 */
#include <stdio.h>
#include <string.h>

static int family_ok(const char *triple, const char *sysroot) {
    if (strncmp(triple, "arm", 3) == 0) return strstr(sysroot, "arm") || strstr(sysroot, "cortex") ? 1 : 0;
    if (strncmp(triple, "aarch64", 7) == 0) return strstr(sysroot, "aarch64") ? 1 : 0;
    return 0;
}

typedef struct { const char *who; const char *triple; const char *sysroot; } tc_t;

int main(void) {
    tc_t T[] = {
        {"STM32MP1", "arm-ostl-linux-gnueabi", "/opt/st/sysroots/cortexa7t2hf-neon-vfpv4"},
        {"i.MX6ULL", "arm-poky-linux-gnueabi", "/opt/yocto/sysroots/armv7ahf-neon"},
        {"V3s",      "arm-linux-gnueabihf",    "/opt/v3s-sdk/sysroot/arm-linux-gnueabihf"},
        {"错配示例", "aarch64-linux-gnu",      "/opt/v3s-sdk/sysroot/arm-linux-gnueabihf"},
    };
    int n = (int)(sizeof(T) / sizeof(T[0])), ok = 1;
    for (int i = 0; i < n; i++) {
        int good = family_ok(T[i].triple, T[i].sysroot);
        printf("%-10s triple=%-26s sysroot=%-42s 一致=%s\n",
               T[i].who, T[i].triple, T[i].sysroot, good ? "是" : "否");
        if (i < n - 1 && !good) ok = 0;      /* 前三个应一致 */
        if (i == n - 1 && good) ok = 0;      /* 最后一个应判为不一致 */
    }
    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_devtree.c —— 设备树语义模型：路径查找 + compatible 匹配 + status（主机可运行）。
 *
 * 内核用“节点路径 + 属性”描述硬件；驱动靠 compatible 匹配设备，status=disabled 表示不使能。
 * 本程序用一个内存中的树模型验证：① 按路径找到节点；② compatible 匹配；③ 只对 enabled 节点驱动。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_devtree.c -o host_devtree && ./host_devtree
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *k; const char *v; } prop_t;
typedef struct { const char *name; const char *parent; prop_t props[4]; int np; } node_t;

static node_t tree[] = {
    {"/", 0, {{0, 0}}, 0},
    {"soc", "/", {{0, 0}}, 0},
    {"uart@40011000", "soc", {{"compatible", "st,stm32-uart"}, {"status", "okay"}}, 2},
    {"i2c@40012000", "soc", {{"compatible", "st,stm32-i2c"}, {"status", "disabled"}}, 2},
};
#define NN (int)(sizeof(tree) / sizeof(tree[0]))

/* 构造节点的全路径：/soc/uart@40011000 */
static void full_path(const node_t *n, char *out) {
    if (n->parent == 0) { strcpy(out, "/"); return; }
    for (int i = 0; i < NN; i++) {
        if (&tree[i] == n) continue;
        if (strcmp(tree[i].name, n->parent) == 0) {
            char up[128];
            full_path(&tree[i], up);
            if (strcmp(up, "/") == 0) snprintf(out, 128, "/%s", n->name);
            else snprintf(out, 128, "%s/%s", up, n->name);
            return;
        }
    }
    strcpy(out, "/?");
}
static const node_t *dt_find(const char *path) {
    char buf[128];
    for (int i = 0; i < NN; i++) { full_path(&tree[i], buf); if (strcmp(buf, path) == 0) return &tree[i]; }
    return 0;
}
static const char *dt_prop(const node_t *n, const char *k) {
    for (int i = 0; i < n->np; i++) if (strcmp(n->props[i].k, k) == 0) return n->props[i].v;
    return 0;
}
static int dt_is_enabled(const node_t *n) {
    const char *s = dt_prop(n, "status");
    return (s == 0 || strcmp(s, "okay") == 0);     /* 缺省为 enabled */
}
static int dt_compatible(const node_t *n, const char *drv) {
    const char *c = dt_prop(n, "compatible");
    return c && strcmp(c, drv) == 0;
}

int main(void) {
    int ok = 1, probed = 0;
    const node_t *u = dt_find("/soc/uart@40011000");
    char buf[128];
    if (u) { full_path(u, buf); printf("找到节点: %s  compatible=%s  status=%s\n",
             buf, dt_prop(u, "compatible"), dt_prop(u, "status") ? dt_prop(u, "status") : "okay"); }
    if (!u) ok = 0;
    if (!(u && dt_compatible(u, "st,stm32-uart"))) ok = 0;
    if (!(u && dt_is_enabled(u))) ok = 0;

    const node_t *i2c = dt_find("/soc/i2c@40012000");
    printf("i2c 节点 status=%s → 驱动%s\n", i2c ? dt_prop(i2c, "status") : "?",
           (i2c && dt_is_enabled(i2c)) ? "探测" : "跳过（disabled）");
    if (!(i2c && !dt_is_enabled(i2c))) ok = 0;

    for (int i = 0; i < NN; i++) if (dt_is_enabled(&tree[i]) && dt_prop(&tree[i], "compatible")) probed++;
    printf("可被 compatible 匹配且 enabled 的节点数=%d（期望 1：uart）\n", probed);
    if (probed != 1) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* i.MX6ULL · 设备树片段：启用 uart1 作为 console */
/dts-v1/;

