/* host_kconfig.c —— Kconfig 依赖/选择解析（主机可运行）。
 *
 * 内核配置里：`depends on` 表示前置必须满足；`select` 会强制打开另一个符号（可能绕过其依赖）。
 * 本程序解析一个请求集合，展开 select，并检测“被选中但依赖未满足”的冲突。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_kconfig.c -o host_kconfig && ./host_kconfig
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *sym; const char *dep; const char *sel; } opt_t;
static opt_t O[] = {
    {"A", 0,   0  },
    {"B", "A", 0  },     /* B depends on A */
    {"C", 0,   "B"},     /* C selects B（即使 B 的依赖未满足也会被选中） */
};
#define NO (int)(sizeof(O) / sizeof(O[0]))

static int find(const char *s) { for (int i = 0; i < NO; i++) if (strcmp(O[i].sym, s) == 0) return i; return -1; }

/* 解析请求：展开 select，返回冲突数并打印启用集合 */
static int resolve(const char *const *req, int nr) {
    int on[8] = {0};
    for (int i = 0; i < nr; i++) { int k = find(req[i]); if (k >= 0) on[k] = 1; }
    int changed = 1;
    while (changed) {                    /* 展开 select */
        changed = 0;
        for (int i = 0; i < NO; i++)
            if (on[i] && O[i].sel) { int k = find(O[i].sel); if (k >= 0 && !on[k]) { on[k] = 1; changed = 1; } }
    }
    printf("启用: ");
    for (int i = 0; i < NO; i++) if (on[i]) printf("%s ", O[i].sym);
    printf("\n");
    int conflicts = 0;
    for (int i = 0; i < NO; i++)
        if (on[i] && O[i].dep && !on[find(O[i].dep)]) {
            printf("  冲突: %s 依赖 %s，但 %s 未启用\n", O[i].sym, O[i].dep, O[i].dep);
            conflicts++;
        }
    return conflicts;
}

int main(void) {
    int ok = 1;
    printf("请求 {C}：\n");
    const char *r1[] = {"C"};
    int c1 = resolve(r1, 1);
    if (c1 != 1) ok = 0;                 /* C 选中 B，但 A 未启用 → 冲突 */

    printf("请求 {A,C}：\n");
    const char *r2[] = {"A", "C"};
    int c2 = resolve(r2, 2);
    if (c2 != 0) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_rootfs.c —— 根文件系统布局自检（主机可运行）。
 *
 * init 之前要求最小根文件系统就位：关键目录、init、fstab、以及 busybox 的 applet 链接。
 * 缺目录或链接指向不存在的 busybox 都会导致启动失败（“No init found”）。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_rootfs.c -o host_rootfs && ./host_rootfs
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *path; const char *target; } ent_t;   /* target!=0 表示符号链接 */

static const char *REQ_DIRS[] = {"/bin", "/etc", "/lib", "/dev", "/proc", "/sys", "/usr"};
static const char *REQ_FILES[] = {"/sbin/init", "/etc/fstab"};

static int has_path(const ent_t *e, int n, const char *p) {
    for (int i = 0; i < n; i++) if (strcmp(e[i].path, p) == 0) return 1;
    return 0;
}
static const ent_t *find(const ent_t *e, int n, const char *p) {
    for (int i = 0; i < n; i++) if (strcmp(e[i].path, p) == 0) return &e[i];
    return 0;
}
/* 返回错误数，并打印每个问题 */
static int check(const ent_t *e, int n) {
    int errs = 0;
    for (unsigned i = 0; i < sizeof(REQ_DIRS) / sizeof(REQ_DIRS[0]); i++)
        if (!has_path(e, n, REQ_DIRS[i])) { printf("  缺目录: %s\n", REQ_DIRS[i]); errs++; }
    for (unsigned i = 0; i < sizeof(REQ_FILES) / sizeof(REQ_FILES[0]); i++)
        if (!has_path(e, n, REQ_FILES[i])) { printf("  缺文件: %s\n", REQ_FILES[i]); errs++; }
    /* busybox applet：/bin/sh 应是指向 busybox 的符号链接，且 busybox 存在 */
    const ent_t *sh = find(e, n, "/bin/sh");
    if (!sh) { printf("  缺 /bin/sh\n"); errs++; }
    else if (sh->target) {
        if (!has_path(e, n, "/bin/busybox")) { printf("  /bin/sh 指向 %s，但 busybox 不存在\n", sh->target); errs++; }
    }
    return errs;
}

int main(void) {
    ent_t good[] = {
        {"/bin", 0}, {"/etc", 0}, {"/lib", 0}, {"/dev", 0}, {"/proc", 0}, {"/sys", 0}, {"/usr", 0},
        {"/sbin/init", 0}, {"/etc/fstab", 0}, {"/bin/busybox", 0}, {"/bin/sh", "busybox"},
    };
    ent_t bad[] = {
        {"/bin", 0}, {"/etc", 0}, {"/lib", 0}, {"/dev", 0}, {"/sys", 0}, {"/usr", 0},   /* 缺 /proc */
        {"/sbin/init", 0}, {"/bin/sh", "busybox"},                                       /* 缺 fstab、busybox */
    };
    int ok = 1, e1, e2;
    printf("完整 rootfs 自检：\n");
    e1 = check(good, (int)(sizeof(good) / sizeof(good[0])));
    printf("  错误数=%d（期望 0）\n", e1);
    if (e1 != 0) ok = 0;

    printf("残缺 rootfs 自检：\n");
    e2 = check(bad, (int)(sizeof(bad) / sizeof(bad[0])));
    printf("  错误数=%d（期望 ≥3）\n", e2);
    if (e2 < 3) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_initdeps.c —— init 服务依赖排序与故障传播（主机可运行）。
 *
 * SysV/systemd 都要按依赖启动服务。本程序做拓扑排序，验证顺序满足依赖；
 * 再让一个被依赖的服务失败，验证其下游不会被“假装启动”。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_initdeps.c -o host_initdeps && ./host_initdeps
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *name; const char *deps[2]; int fail; } svc_t;

static int idx_of(svc_t *s, int n, const char *name) {
    for (int i = 0; i < n; i++) if (strcmp(s[i].name, name) == 0) return i;
    return -1;
}
/* 返回 1=排序成功，0=存在环 */
static int topo(svc_t *s, int n, int *order) {
    int indeg[8] = {0}, done[8] = {0}, oc = 0;
    for (int i = 0; i < n; i++) for (int d = 0; d < 2 && s[i].deps[d]; d++) indeg[i]++;
    for (int step = 0; step < n; step++) {
        int pick = -1;
        for (int i = 0; i < n; i++) if (!done[i] && indeg[i] == 0) { pick = i; break; }
        if (pick < 0) return 0;                    /* 有环 */
        done[pick] = 1; order[oc++] = pick;
        for (int i = 0; i < n; i++)
            for (int d = 0; d < 2 && s[i].deps[d]; d++)
                if (strcmp(s[i].deps[d], s[pick].name) == 0) indeg[i]--;
    }
    return 1;
}

int main(void) {
    svc_t S[5] = {
        {"sysinit", {0, 0}, 0},
        {"network", {"sysinit", 0}, 0},
        {"sshd",    {"network", 0}, 0},
        {"mqtt",    {"network", 0}, 0},
        {"ui",      {"sysinit", 0}, 0},
    };
    int n = 5, order[8], ok = 1;

    if (!topo(S, n, order)) ok = 0;
    printf("启动顺序:");
    for (int i = 0; i < n; i++) printf(" %s", S[order[i]].name);
    printf("\n");
    /* 校验：每个服务的依赖都在它之前 */
    int pos[8]; for (int i = 0; i < n; i++) pos[order[i]] = i;
    for (int i = 0; i < n; i++)
        for (int d = 0; d < 2 && S[i].deps[d]; d++) {
            int j = idx_of(S, n, S[i].deps[d]);
            if (!(pos[j] < pos[i])) ok = 0;
        }

    /* 故障传播：network 失败 → sshd/mqtt 不应启动 */
    S[idx_of(S, n, "network")].fail = 1;
    int started[8] = {0};
    for (int k = 0; k < n; k++) {
        int i = order[k], good = !S[i].fail;
        for (int d = 0; d < 2 && S[i].deps[d]; d++) {
            int j = idx_of(S, n, S[i].deps[d]);
            if (!started[j]) good = 0;
        }
        started[i] = good;
    }
    printf("network 失败后已启动:");
    for (int i = 0; i < n; i++) if (started[i]) printf(" %s", S[i].name);
    printf("\n");
    if (started[idx_of(S, n, "network")]) ok = 0;
    if (started[idx_of(S, n, "sshd")] || started[idx_of(S, n, "mqtt")]) ok = 0;
    if (!started[idx_of(S, n, "sysinit")] || !started[idx_of(S, n, "ui")]) ok = 0;

    /* 环检测 */
    svc_t C[2] = { {"a", {"b", 0}, 0}, {"b", {"a", 0}, 0} };
    int ord2[4];
    printf("环依赖 topo 返回=%d（期望 0）\n", topo(C, 2, ord2));
    if (topo(C, 2, ord2) != 0) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_partition.c —— 分区表与 root= 设备一致性检查（主机可运行）。
 *
 * 内核 cmdline 的 root= 必须指向真实的根分区；写错索引会“找不到根”而 panic。
 * 本程序把分区名/文件系统与 root= 设备做映射校验。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_partition.c -o host_partition && ./host_partition
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *name; const char *fs; int idx; } part_t;
static const part_t PARTS[] = {
    {"fsbl1", "(raw)", 1}, {"ssbl", "(raw)", 3}, {"boot", "ext4", 4}, {"rootfs", "ext4", 5},
};
#define NP (int)(sizeof(PARTS) / sizeof(PARTS[0]))

/* 取设备名末尾的分区号：/dev/mmcblk0p5 → 5；/dev/sda2 → 2 */
static int dev_index(const char *dev) {
    int n = (int)strlen(dev), i = n;
    while (i > 0 && dev[i - 1] >= '0' && dev[i - 1] <= '9') i--;
    int v = 0;
    for (int k = i; k < n; k++) v = v * 10 + (dev[k] - '0');
    return v;
}
static const part_t *find_idx(int idx) {
    for (int i = 0; i < NP; i++) if (PARTS[i].idx == idx) return &PARTS[i];
    return 0;
}

int main(void) {
    int ok = 1;
    const char *root1 = "/dev/mmcblk0p5";
    const part_t *p = find_idx(dev_index(root1));
    printf("root=%s → 分区 %d：%s (%s)\n", root1, dev_index(root1),
           p ? p->name : "不存在", p ? p->fs : "-");
    if (!(p && strcmp(p->name, "rootfs") == 0 && strcmp(p->fs, "ext4") == 0)) ok = 0;

    const char *root2 = "/dev/mmcblk0p7";
    printf("root=%s → %s（期望“不存在/越界”被拒绝）\n", root2, find_idx(dev_index(root2)) ? "存在" : "不存在");
    if (find_idx(dev_index(root2)) != 0) ok = 0;

    int raw = find_idx(3)->name ? strcmp(find_idx(3)->fs, "(raw)") == 0 : 0;
    printf("分区 3=%s 是否为裸分区（不可作 root）=%s\n", find_idx(3)->name, raw ? "是" : "否");
    if (!raw) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_debuglog.c —— 日志等级统计与告警（dmesg 语义，主机可运行）。
 *
 * 内核日志有等级（emerg/err/warn/info…）。系统层调试第一步是“按等级筛”，
 * 再判断是否达到告警条件。本程序统计各级别出现次数并给出告警结论。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_debuglog.c -o host_debuglog && ./host_debuglog
 */
#include <stdio.h>
#include <string.h>

static const char *level_of(const char *s) {
    if (strstr(s, "emerg")) return "emerg";
    if (strstr(s, "err"))   return "err";
    if (strstr(s, "warn"))  return "warn";
    if (strstr(s, "info"))  return "info";
    return "debug";
}
static int rank(const char *lvl) {
    if (strcmp(lvl, "emerg") == 0) return 0;
    if (strcmp(lvl, "err") == 0) return 3;
    if (strcmp(lvl, "warn") == 0) return 4;
    if (strcmp(lvl, "info") == 0) return 6;
    return 7;
}

int main(void) {
    const char *log[] = {
        "kern.info: Linux version 6.1.0",
        "kern.info: mmc0: SDHCI controller on 2190000.mmc",
        "kern.warn: mmc0: card lacks reliable write",
        "kern.err: mmc0: error -110 during read",
        "kern.err: EXT4-fs (mmcblk0p5): error loading journal",
        "kern.emerg: Kernel panic - not syncing",
    };
    int n = (int)(sizeof(log) / sizeof(log[0]));
    int cnt[8] = {0}, worst = 7;
    for (int i = 0; i < n; i++) {
        const char *l = level_of(log[i]);
        cnt[rank(l)]++;
        if (rank(l) < worst) worst = rank(l);
    }
    printf("统计: info=%d warn=%d err=%d emerg=%d\n", cnt[6], cnt[4], cnt[3], cnt[0]);
    printf("最严重级别=%s\n", worst == 0 ? "emerg" : worst == 3 ? "err" : worst == 4 ? "warn" : "info");

    int ok = 1;
    if (!(cnt[6] == 2 && cnt[4] == 1 && cnt[3] == 2 && cnt[0] == 1)) ok = 0;
    int alert = (cnt[0] > 0) || (cnt[3] > 0);
    printf("是否告警=%s（emerg/err 存在即告警）\n", alert ? "是" : "否");
    if (!alert) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

/* host_shellparse.c —— 命令行分词（Shell 语义模型，主机可运行）。
 *
 * Shell 分词的规则并不简单：引号内空格不分割、反斜杠转义、管道是独立 token。
 * 本程序实现一个最小分词器，验证引号/转义/管道的处理。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_shellparse.c -o host_shellparse && ./host_shellparse
 */
#include <stdio.h>
#include <string.h>

#define MAXTOK 16

/* 返回 token 数；token 指向内部静态缓冲 */
static int tokenize(const char *s, char tok[][64]) {
    int n = 0, i = 0, ti = 0, in_s = 0, in_d = 0, esc = 0;
    for (; s[i]; i++) {
        char c = s[i];
        if (esc) { tok[n][ti++] = c; esc = 0; continue; }
        if (c == '\\' && !in_s) { esc = 1; continue; }        /* 反斜杠转义（单引号内不转义） */
        if (c == '\'' && !in_d) { in_s = !in_s; continue; }
        if (c == '"' && !in_s) { in_d = !in_d; continue; }
        if (!in_s && !in_d && (c == ' ' || c == '\t')) {
            if (ti) { tok[n][ti] = 0; n++; ti = 0; }
            continue;
        }
        if (!in_s && !in_d && c == '|') {                     /* 管道是独立 token */
            if (ti) { tok[n][ti] = 0; n++; ti = 0; }
            tok[n][0] = '|'; tok[n][1] = 0; n++;
            continue;
        }
        tok[n][ti++] = c;
    }
    if (ti) { tok[n][ti] = 0; n++; }
    return n;
}

int main(void) {
    char tok[MAXTOK][64];
    const char *cmd = "echo \"a b\" c\\ d | grep x";
    int n = tokenize(cmd, tok), ok = 1;
    printf("命令: %s\n分词(%d):", cmd, n);
    for (int i = 0; i < n; i++) printf(" [%s]", tok[i]);
    printf("\n");
    if (n != 6) ok = 0;
    const char *want[6] = {"echo", "a b", "c d", "|", "grep", "x"};
    for (int i = 0; i < 6 && i < n; i++) if (strcmp(tok[i], want[i]) != 0) ok = 0;

    char tok2[MAXTOK][64];
    int n2 = tokenize("cat '/etc/passwd'", tok2);
    printf("分词2(%d): [%s] [%s]（单引号内不转义）\n", n2, tok2[0], n2 > 1 ? tok2[1] : "");
    if (!(n2 == 2 && strcmp(tok2[1], "/etc/passwd") == 0)) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

