/* host_platform.c —— platform driver 匹配与 deferred probe 模型（主机可运行）。
 *
 * 内核按 compatible 把设备与驱动绑定；若某设备的依赖尚未就绪，则返回 -EPROBE_DEFER，稍后重试。
 * 本程序验证：匹配成功 → probe；依赖未就绪 → deferred；无匹配 → unbound。
 *
 * 编译运行：gcc -std=c11 -Wall -Wextra -O2 host_platform.c -o host_platform && ./host_platform
 */
#include <stdio.h>
#include <string.h>

typedef struct { const char *compatible; const char *drv; } match_t;
static const match_t MATCH[] = { {"v,dev-a", "drvA"}, {"v,dev-b", "drvB"} };
#define NM (int)(sizeof(MATCH) / sizeof(MATCH[0]))

typedef struct { const char *name; const char *compat; const char *dep; int probed; int deferred; } dev_t;
static dev_t DEV[] = {
    {"dev-b@0", "v,dev-b", "v,dev-a", 0, 0},
    {"dev-a@1", "v,dev-a", 0,         0, 0},
    {"dev-c@2", "v,dev-c", 0,         0, 0},
};
#define NDV (int)(sizeof(DEV) / sizeof(DEV[0]))

static const char *drv_for(const char *c) { for (int i = 0; i < NM; i++) if (strcmp(MATCH[i].compatible, c) == 0) return MATCH[i].drv; return 0; }
static int dep_ready(const char *dep) { if (!dep) return 1; for (int i = 0; i < NDV; i++) if (strcmp(DEV[i].compat, dep) == 0) return DEV[i].probed; return 0; }

int main(void) {
    int ok = 1;
    /* 第一遍：dev-b 的依赖 dev-a 尚未 probe → deferred */
    for (int i = 0; i < NDV; i++) {
        const char *d = drv_for(DEV[i].compat);
        if (!d) { printf("%-8s unbound（无匹配驱动）\n", DEV[i].name); continue; }
        if (!dep_ready(DEV[i].dep)) { DEV[i].deferred = 1; printf("%-8s deferred（依赖 %s 未就绪）\n", DEV[i].name, DEV[i].dep); continue; }
        DEV[i].probed = 1; printf("%-8s probe → %s\n", DEV[i].name, d);
    }
    if (DEV[1].probed != 1) ok = 0;      /* dev-a 已 probe */
    if (DEV[0].probed != 0 || DEV[0].deferred != 1) ok = 0;

    /* 第二遍：重试 deferred */
    printf("-- 重试 deferred --\n");
    for (int i = 0; i < NDV; i++)
        if (DEV[i].deferred && dep_ready(DEV[i].dep)) { DEV[i].probed = 1; printf("%-8s probe → %s\n", DEV[i].name, drv_for(DEV[i].compat)); }
    if (DEV[0].probed != 1) ok = 0;

    printf("最终：probed=%d unbound=1\n", DEV[0].probed + DEV[1].probed);
    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

static const struct of_device_id my_of[] = {
    { .compatible = "vendor,myplat" },
    { }
};
static int my_probe(struct platform_device *pdev) {
    void __iomem *base = devm_platform_ioremap_resource(pdev, 0);
    if (IS_ERR(base)) return PTR_ERR(base);
    int irq = platform_get_irq(pdev, 0);
    if (irq < 0) return dev_err_probe(&pdev->dev, irq, "no irq");
    return 0;   // 依赖未就绪时返回 -EPROBE_DEFER
}

/* Host resource state machine only. model_* functions are NOT Linux APIs.
 * This model keeps an object alive after model_put to check logical misuse.
 * A real descriptor must never be used after gpiod_put. Real gpiod_get errors
 * use ERR_PTR/IS_ERR, not this model's NULL. MMIO with a disabled clock may
 * fault, hang, or behave differently on different SoCs. */
#include <stdio.h>
#include <string.h>

#define ENODEV 19    /* 资源不可用（未使能 / 已释放） */
#define ENOENT  2    /* 设备树中找不到该资源 */

typedef struct { int in_use; } gpio_desc;
typedef struct { int enabled; } clk;

static int g_led_value = 0;

/* 申请 GPIO 描述符：只有设备树里存在的名字才成功 */
static gpio_desc *model_gpiod_get(const char *name) {
    if (strcmp(name, "led") != 0) return 0;   /* 无此资源 */
    static gpio_desc d;
    d.in_use = 1;
    return &d;
}
/* 设置输出电平：未申请或已释放一律拒绝 */
static int model_gpiod_set_value(gpio_desc *d, int v) {
    if (!d || !d->in_use) return -ENODEV;     /* use-after-put 被拒 */
    g_led_value = v;
    return 0;
}
static void model_gpiod_put(gpio_desc *d) { if (d) d->in_use = 0; }

static int model_clk_prepare_enable(clk *c) { c->enabled = 1; return 0; }
static void model_clk_disable_unprepare(clk *c) { c->enabled = 0; }
/* 读外设寄存器：时钟未使能时访问非法 */
static int model_reg_read(clk *c) { return c->enabled ? 0 : -ENODEV; }

int main(void) {
    int ok = 1;
    gpio_desc *led = model_gpiod_get("led");
    clk uart = {0};

    printf("model_gpiod_get(\"led\")=%s\n", led ? "ok" : "NULL");
    if (!led) ok = 0;

    if (model_gpiod_set_value(led, 1) != 0) ok = 0;
    printf("model_gpiod_set_value(1) → value=%d\n", g_led_value);
    if (g_led_value != 1) ok = 0;

    printf("clk 未 enable 访问寄存器 → %d（期望 -%d）\n", model_reg_read(&uart), ENODEV);
    if (model_reg_read(&uart) != -ENODEV) ok = 0;

    model_clk_prepare_enable(&uart);
    printf("clk enable 后访问寄存器 → %d（期望 0）\n", model_reg_read(&uart));
    if (model_reg_read(&uart) != 0) ok = 0;
    model_clk_disable_unprepare(&uart);

    model_gpiod_put(led);
    printf("model_gpiod_put 后 set_value → %d（期望 -%d，use-after-put 被拒）\n",
           model_gpiod_set_value(led, 0), ENODEV);
    if (model_gpiod_set_value(led, 0) != -ENODEV) ok = 0;

    printf("model_gpiod_get(\"missing\")=%s → -%d\n",
           model_gpiod_get("missing") ? "ok" : "NULL", ENOENT);
    if (model_gpiod_get("missing") != 0) ok = 0;

    printf("\n%s\n", ok ? "RESULT: PASS" : "RESULT: FAIL");
    return ok ? 0 : 1;
}

struct gpio_desc *led = devm_gpiod_get(dev, "led", GPIOD_OUT_LOW);
if (IS_ERR(led)) return PTR_ERR(led);
model_gpiod_set_value(led, 1);          // 逻辑电平，自动处理 active-low

struct clk *clk = devm_clk_get(dev, NULL);
if (IS_ERR(clk)) return PTR_ERR(clk);
