// 消费者
while (!atomic_load_explicit(&flag, memory_order_relaxed)) {}  // ✗ 没有 acquire
use(data);   // 可能读到未就绪的 data

// 生产者（安全写法）
data = 42;
atomic_store_explicit(&flag, 1, memory_order_release);   // ✓
// 消费者（安全写法）
while (!atomic_load_explicit(&flag, memory_order_acquire)) {}  // ✓
use(data);   // 必然看到 42

